export const specSources: Record<string, { yaml: string; data: unknown }> = {
  "ad-spend": { yaml: "id: ad-spend\nname: Ad spend\naliases:\n  - Marketing spend\n  - Media spend\n  - Paid media spend\n  - Advertising spend\nfamily: acquisition\ncatalog_id: spend\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: Money spent on paid ads across every synced ad platform in the week, as each platform reports it.\n  formula: Sum of daily spend across ad channels and campaigns\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n      - name: campaign\n        description: The campaign name or id on that platform.\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency, before agency fees.\n      - name: impressions\n        description: Ads shown that day.\n      - name: clicks\n        description: Link clicks that day, as the platform defines them.\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nnoise:\n  type: process\n  min_denominator: 1\n  volume_unit: campaigns with spend a week\n  typical: 20000\n\nexample:\n  business: store\n  level: 300000\n  volume: 60\n  trend: 0.25\n\ndrivers:\n  - id: sync\n    label: Spend sync\n    breakdown: channel\n    dropped:\n      check: Did a platform's sync fail or fall behind, so some days are missing?\n      yes: One channel shows zero or partial spend for some days while its own dashboard shows the usual amount.\n    spiked:\n      check: Is a day synced twice, or a currency recorded as if it were dollars?\n      yes: One channel shows exactly double a day, or a jump that matches an exchange rate.\n  - id: billing\n    label: Billing and account status\n    feed: ad-platforms\n    dropped:\n      check: Was a payment method declined, a spending limit hit, an account suspended or ads disapproved?\n      yes: One platform's spend stops on a single day and its delivery notifications say why.\n    spiked:\n      check: Did a stopped account come back and catch up on delivery?\n      yes: One platform's spend returns after a gap, sometimes above its usual daily rate.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did a planned push such as Black Friday or a launch end?\n      yes: Budgets return to their usual level the week after the event.\n    spiked:\n      check: Is this a planned sale, holiday or launch week with raised budgets?\n      yes: The same week last year shows the same rise, and the plan says so.\n  - id: campaigns\n    label: Campaigns and budgets\n    breakdown: campaign\n    dropped:\n      check: Did a campaign pause, end, or lose delivery after a learning reset or audience change?\n      yes: One or two campaigns account for most of the fall.\n    spiked:\n      check: Did a new campaign launch, a budget rise, or automated bidding start spending past its usual pace?\n      yes: One or two campaigns account for most of the rise; check whether results rose with them.\n  - id: auction\n    label: Auction prices\n    metric: cpm\n    dropped:\n      check: With budgets uncapped, did cheaper or scarcer impressions lower what the platforms could spend?\n      yes: CPMs fall or delivery is limited while budgets are unchanged.\n    spiked:\n      check: Did auction prices rise, so the same delivery costs more?\n      yes: CPMs rise across platforms in the same week, often in Q4.\n\ndiagnose_order: [sync, billing, calendar, campaigns, auction]\n\nrelated: [mer, ncac, roas, cpm, paid-sessions, blended-cac]\n\nprose:\n  why_it_matters: >-\n    Spend is the one acquisition number the team chooses, so a move that nobody planned is\n    either a broken sync or a campaign spending without supervision. Automated bidding can spend\n    a week's budget in two days. At $300,000 a week, a sync that drops one platform for a day\n    makes MER and CAC look 5 to 10% better than they are.\n  pitfalls:\n    - Ad platforms report days in the ad account's time zone. Summed into UTC weeks, a few hours of spend move between weeks, and a time zone change on the account shifts a whole day.\n    - Platforms restate recent spend for invalid clicks and late data. Re-sync the last 7 days every day, or last week's number changes after you report it.\n    - Spend here is media only. Agency fees, creative production and platform tools are real acquisition costs; sync them as their own channel if CAC should include them.\n    - Accounts billed in different currencies need one fixed exchange rate per week, or currency moves look like budget changes.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ad-spend","name":"Ad spend","aliases":["Marketing spend","Media spend","Paid media spend","Advertising spend"],"family":"acquisition","catalog_id":"spend","kind":"currency","polarity":"down-is-good","definition":{"one_line":"Money spent on paid ads across every synced ad platform in the week, as each platform reports it.","formula":"Sum of daily spend across ad channels and campaigns"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."},{"name":"campaign","description":"The campaign name or id on that platform."},{"name":"spend","description":"Amount spent that day, in the store's reporting currency, before agency fees."},{"name":"impressions","description":"Ads shown that day."},{"name":"clicks","description":"Link clicks that day, as the platform defines them."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"noise":{"type":"process","min_denominator":1,"volume_unit":"campaigns with spend a week","typical":20000},"example":{"business":"store","level":300000,"volume":60,"trend":0.25},"drivers":[{"id":"sync","label":"Spend sync","breakdown":"channel","dropped":{"check":"Did a platform's sync fail or fall behind, so some days are missing?","yes":"One channel shows zero or partial spend for some days while its own dashboard shows the usual amount."},"spiked":{"check":"Is a day synced twice, or a currency recorded as if it were dollars?","yes":"One channel shows exactly double a day, or a jump that matches an exchange rate."}},{"id":"billing","label":"Billing and account status","feed":"ad-platforms","dropped":{"check":"Was a payment method declined, a spending limit hit, an account suspended or ads disapproved?","yes":"One platform's spend stops on a single day and its delivery notifications say why."},"spiked":{"check":"Did a stopped account come back and catch up on delivery?","yes":"One platform's spend returns after a gap, sometimes above its usual daily rate."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did a planned push such as Black Friday or a launch end?","yes":"Budgets return to their usual level the week after the event."},"spiked":{"check":"Is this a planned sale, holiday or launch week with raised budgets?","yes":"The same week last year shows the same rise, and the plan says so."}},{"id":"campaigns","label":"Campaigns and budgets","breakdown":"campaign","dropped":{"check":"Did a campaign pause, end, or lose delivery after a learning reset or audience change?","yes":"One or two campaigns account for most of the fall."},"spiked":{"check":"Did a new campaign launch, a budget rise, or automated bidding start spending past its usual pace?","yes":"One or two campaigns account for most of the rise; check whether results rose with them."}},{"id":"auction","label":"Auction prices","metric":"cpm","dropped":{"check":"With budgets uncapped, did cheaper or scarcer impressions lower what the platforms could spend?","yes":"CPMs fall or delivery is limited while budgets are unchanged."},"spiked":{"check":"Did auction prices rise, so the same delivery costs more?","yes":"CPMs rise across platforms in the same week, often in Q4."}}],"diagnose_order":["sync","billing","calendar","campaigns","auction"],"related":["mer","ncac","roas","cpm","paid-sessions","blended-cac"],"prose":{"why_it_matters":"Spend is the one acquisition number the team chooses, so a move that nobody planned is either a broken sync or a campaign spending without supervision. Automated bidding can spend a week's budget in two days. At $300,000 a week, a sync that drops one platform for a day makes MER and CAC look 5 to 10% better than they are.","pitfalls":["Ad platforms report days in the ad account's time zone. Summed into UTC weeks, a few hours of spend move between weeks, and a time zone change on the account shifts a whole day.","Platforms restate recent spend for invalid clicks and late data. Re-sync the last 7 days every day, or last week's number changes after you report it.","Spend here is media only. Agency fees, creative production and platform tools are real acquisition costs; sync them as their own channel if CAC should include them.","Accounts billed in different currencies need one fixed exchange rate per week, or currency moves look like budget changes."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "add-to-cart-rate": { yaml: "id: add-to-cart-rate\nname: Add-to-cart rate\naliases:\n  - ATC rate\n  - Add to cart conversion rate\n  - Cart addition rate\nfamily: conversion\ncatalog_id: add_to_cart_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that viewed a product and added something to the cart, the store's clearest read on product pages.\n  formula: Sessions that added to cart ÷ sessions that viewed a product\n\nevents:\n  - name: product_viewed\n    description: A product detail page rendered with its product, once per view.\n    also_called: [view_item, Product Viewed, product_viewed]\n    properties:\n      - name: product_id\n        description: The product shown.\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n      - name: quantity\n        description: Units added in this action.\n      - name: price\n        description: Unit price at the time of adding, before discounts.\n\nnumerator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\ndenominator:\n  label: Sessions that viewed a product\n  aggregate: unique_sessions\n  event: product_viewed\n\nnoise:\n  type: binomial\n  min_denominator: 300\n  volume_unit: product-viewing sessions a week\n  typical: 0.1\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.108\n  volume: 372000\n  trend: 0.02\n  season: 0.5\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a theme update or a new cart drawer app stop product_added firing on some buttons?\n      yes: Orders and checkout starts hold while recorded adds fall, often from one template or device.\n    spiked:\n      check: Is product_added now firing on quantity changes, on both the drawer and the form, or on page load?\n      yes: Adds per session jump while checkout starts don't follow.\n  - id: price-and-offers\n    label: Prices, sales and the calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end, prices rise, or the free-shipping threshold move this week?\n      yes: Adds fall on the products whose price or offer changed, from the day it changed.\n    spiked:\n      check: Is a sale, a holiday or a new offer lifting adds, and do checkout starts follow?\n      yes: Adds rise on discounted products; if checkout starts don't rise with them, shoppers are comparing, not buying.\n  - id: stock\n    label: Stock and sizes\n    dropped:\n      check: Did best sellers or common sizes go out of stock?\n      yes: Views hold on the top products while their adds fall to near zero.\n    spiked:\n      check: Did a best seller or a missing size come back in stock?\n      yes: Adds jump on the restocked products from the restock day while the rest hold.\n  - id: page-release\n    label: Product page changes\n    dropped:\n      check: Did a release move the add-to-cart button, add a required option, slow the page or change photos or reviews?\n      yes: The drop starts on the release day across every traffic source.\n    spiked:\n      check: Did a release or test ship a clearer buy box, and is it the same for everyone?\n      yes: The rise starts on the release day; confirm the test isn't counting one add twice.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on mobile only, for example a sticky add-to-cart bar that stopped showing?\n      yes: Mobile falls while desktop holds, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release while the other holds.\n  - id: traffic-mix\n    label: Who is browsing\n    breakdown: utm_source\n    dropped:\n      check: Did more browsers arrive from a low-intent source, such as broad paid social or a gift guide?\n      yes: One source gains share of product views and adds far less often than the rest.\n    spiked:\n      check: Did a high-intent source grow, such as email or branded search?\n      yes: One source gains share of product views while each source's own rate holds.\n\ndiagnose_order: [tracking, price-and-offers, stock, page-release, device-split, traffic-mix]\n\nrelated: [product-view-rate, checkout-start-rate, cart-abandonment-rate, conversion-rate, aov]\n\nprose:\n  why_it_matters: >-\n    Add-to-cart rate is where price, photos, reviews and stock show up first, before checkout\n    can help or hurt. On 372,000 product-viewing sessions a week, one point is about 3,700\n    carts, and with a third of carts becoming orders that is roughly 1,200 orders a week.\n  pitfalls:\n    - Shopify's dashboard divides adds by all sessions, not product-viewing sessions, so the same store reads about 6.7% there and 10.8% here. Compare like with like.\n    - Quick-add buttons on collection pages and upsells add to cart without a product view, so heavy quick-add stores see this rate drift up with no change in product pages.\n    - Counting add events instead of sessions rewards quantity buttons; three taps on plus are one shopper. This spec counts sessions.\n    - Adding to cart is cheap intent. A rise that checkout starts don't follow is usually a promotion, a tracking change or price comparison, not better product pages.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"add-to-cart-rate","name":"Add-to-cart rate","aliases":["ATC rate","Add to cart conversion rate","Cart addition rate"],"family":"conversion","catalog_id":"add_to_cart_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that viewed a product and added something to the cart, the store's clearest read on product pages.","formula":"Sessions that added to cart ÷ sessions that viewed a product"},"events":[{"name":"product_viewed","description":"A product detail page rendered with its product, once per view.","also_called":["view_item","Product Viewed","product_viewed"],"properties":[{"name":"product_id","description":"The product shown."}]},{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."},{"name":"quantity","description":"Units added in this action."},{"name":"price","description":"Unit price at the time of adding, before discounts."}]}],"numerator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"denominator":{"label":"Sessions that viewed a product","aggregate":"unique_sessions","event":"product_viewed"},"noise":{"type":"binomial","min_denominator":300,"volume_unit":"product-viewing sessions a week","typical":0.1,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.108,"volume":372000,"trend":0.02,"season":0.5},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a theme update or a new cart drawer app stop product_added firing on some buttons?","yes":"Orders and checkout starts hold while recorded adds fall, often from one template or device."},"spiked":{"check":"Is product_added now firing on quantity changes, on both the drawer and the form, or on page load?","yes":"Adds per session jump while checkout starts don't follow."}},{"id":"price-and-offers","label":"Prices, sales and the calendar","feed":"shopping","dropped":{"check":"Did a sale end, prices rise, or the free-shipping threshold move this week?","yes":"Adds fall on the products whose price or offer changed, from the day it changed."},"spiked":{"check":"Is a sale, a holiday or a new offer lifting adds, and do checkout starts follow?","yes":"Adds rise on discounted products; if checkout starts don't rise with them, shoppers are comparing, not buying."}},{"id":"stock","label":"Stock and sizes","dropped":{"check":"Did best sellers or common sizes go out of stock?","yes":"Views hold on the top products while their adds fall to near zero."},"spiked":{"check":"Did a best seller or a missing size come back in stock?","yes":"Adds jump on the restocked products from the restock day while the rest hold."}},{"id":"page-release","label":"Product page changes","dropped":{"check":"Did a release move the add-to-cart button, add a required option, slow the page or change photos or reviews?","yes":"The drop starts on the release day across every traffic source."},"spiked":{"check":"Did a release or test ship a clearer buy box, and is it the same for everyone?","yes":"The rise starts on the release day; confirm the test isn't counting one add twice."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on mobile only, for example a sticky add-to-cart bar that stopped showing?","yes":"Mobile falls while desktop holds, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release while the other holds."}},{"id":"traffic-mix","label":"Who is browsing","breakdown":"utm_source","dropped":{"check":"Did more browsers arrive from a low-intent source, such as broad paid social or a gift guide?","yes":"One source gains share of product views and adds far less often than the rest."},"spiked":{"check":"Did a high-intent source grow, such as email or branded search?","yes":"One source gains share of product views while each source's own rate holds."}}],"diagnose_order":["tracking","price-and-offers","stock","page-release","device-split","traffic-mix"],"related":["product-view-rate","checkout-start-rate","cart-abandonment-rate","conversion-rate","aov"],"prose":{"why_it_matters":"Add-to-cart rate is where price, photos, reviews and stock show up first, before checkout can help or hurt. On 372,000 product-viewing sessions a week, one point is about 3,700 carts, and with a third of carts becoming orders that is roughly 1,200 orders a week.","pitfalls":["Shopify's dashboard divides adds by all sessions, not product-viewing sessions, so the same store reads about 6.7% there and 10.8% here. Compare like with like.","Quick-add buttons on collection pages and upsells add to cart without a product view, so heavy quick-add stores see this rate drift up with no change in product pages.","Counting add events instead of sessions rewards quantity buttons; three taps on plus are one shopper. This spec counts sessions.","Adding to cart is cheap intent. A rise that checkout starts don't follow is usually a promotion, a tracking change or price comparison, not better product pages."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "aov": { yaml: "id: aov\nname: Average order value\naliases:\n  - Average order value\n  - Average basket value\n  - Average transaction value\n  - Average purchase revenue\nfamily: revenue\ncatalog_id: aov\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The average paid order's value after discounts, before tax, shipping and refunds.\n  formula: Order revenue after discounts ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: mean\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 90\n\nexample:\n  business: store\n  level: 97\n  volume: 13300\n  trend: 0.1\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did $0 orders, such as replacements, gifts or influencer seeding, start recording as paid orders?\n      yes: A cluster of orders at or near $0 appears from one day.\n    spiked:\n      check: Did order totals start including tax or shipping, or did one currency arrive unconverted?\n      yes: Totals jump for one country or channel from one day while subtotals hold.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Is a sale running, when discounts and cheaper gift items pull the average down?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a gifting week, or did a sale that lowered the average just end?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: discounts\n    label: Discounts\n    metric: discount-rate\n    dropped:\n      check: Did the share of sales given away in discounts rise?\n      yes: Discount rate rises while items per order hold, and the average falls by about the extra discount.\n    spiked:\n      check: Did a promotion end, so orders carry less discount?\n      yes: Discount rate falls by about as much as the average rises.\n  - id: basket-size\n    label: Items per order\n    metric: units-per-order\n    dropped:\n      check: Did orders carry fewer items, after a bundle ended or the free-shipping threshold fell?\n      yes: Units per order fall while the price per unit holds.\n    spiked:\n      check: Did a bundle, a multi-buy offer or a higher free-shipping threshold add items to orders?\n      yes: Units per order rise from the day the offer started.\n  - id: price-and-mix\n    label: Prices and product mix\n    dropped:\n      check: Did sales shift toward cheaper products, such as a low-priced launch or an entry product in ads?\n      yes: The price per unit falls while items per order hold.\n    spiked:\n      check: Did prices rise, a premium product launch, or did a handful of very large orders land?\n      yes: The price per unit rises, or the ten largest orders explain most of the jump.\n  - id: first-orders\n    label: First vs repeat orders\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders, which are usually smaller, take a larger share of orders?\n      yes: Each group's average holds and only the mix moved.\n    spiked:\n      check: Did repeat customers take a larger share, or did first orders grow in size?\n      yes: The mix moved toward repeat orders, or first orders' average rose on its own.\n\ndiagnose_order: [tracking, calendar, discounts, basket-size, price-and-mix, first-orders]\n\nrelated: [net-revenue, orders, units-per-order, discount-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Revenue is orders × AOV, so AOV separates \"fewer people bought\" from \"people bought less\".\n    It moves with prices, discounts, basket size and who is buying, not with traffic. At\n    Northwind, $1 of AOV across 13,300 orders is $13,300 a week, the same revenue as about 135\n    more orders.\n  pitfalls:\n    - Averages follow large orders. A few wholesale or bulk orders can lift a small store's AOV 10% in a week; check the median order beside it.\n    - Dividing net revenue after refunds by orders makes AOV move with refunds on earlier weeks' orders. This spec divides the week's own order revenue by its order count and reads refunds in refund rate.\n    - Including tax and shipping makes AOV move with tax rules, destinations and carrier prices. Keep both out.\n    - A promotion that lowers AOV can still raise revenue. Judge AOV with orders beside it, never alone.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"aov","name":"Average order value","aliases":["Average order value","Average basket value","Average transaction value","Average purchase revenue"],"family":"revenue","catalog_id":"aov","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The average paid order's value after discounts, before tax, shipping and refunds.","formula":"Order revenue after discounts ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"mean","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":90},"example":{"business":"store","level":97,"volume":13300,"trend":0.1,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did $0 orders, such as replacements, gifts or influencer seeding, start recording as paid orders?","yes":"A cluster of orders at or near $0 appears from one day."},"spiked":{"check":"Did order totals start including tax or shipping, or did one currency arrive unconverted?","yes":"Totals jump for one country or channel from one day while subtotals hold."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Is a sale running, when discounts and cheaper gift items pull the average down?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a gifting week, or did a sale that lowered the average just end?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"discounts","label":"Discounts","metric":"discount-rate","dropped":{"check":"Did the share of sales given away in discounts rise?","yes":"Discount rate rises while items per order hold, and the average falls by about the extra discount."},"spiked":{"check":"Did a promotion end, so orders carry less discount?","yes":"Discount rate falls by about as much as the average rises."}},{"id":"basket-size","label":"Items per order","metric":"units-per-order","dropped":{"check":"Did orders carry fewer items, after a bundle ended or the free-shipping threshold fell?","yes":"Units per order fall while the price per unit holds."},"spiked":{"check":"Did a bundle, a multi-buy offer or a higher free-shipping threshold add items to orders?","yes":"Units per order rise from the day the offer started."}},{"id":"price-and-mix","label":"Prices and product mix","dropped":{"check":"Did sales shift toward cheaper products, such as a low-priced launch or an entry product in ads?","yes":"The price per unit falls while items per order hold."},"spiked":{"check":"Did prices rise, a premium product launch, or did a handful of very large orders land?","yes":"The price per unit rises, or the ten largest orders explain most of the jump."}},{"id":"first-orders","label":"First vs repeat orders","breakdown":"is_first_order","dropped":{"check":"Did first orders, which are usually smaller, take a larger share of orders?","yes":"Each group's average holds and only the mix moved."},"spiked":{"check":"Did repeat customers take a larger share, or did first orders grow in size?","yes":"The mix moved toward repeat orders, or first orders' average rose on its own."}}],"diagnose_order":["tracking","calendar","discounts","basket-size","price-and-mix","first-orders"],"related":["net-revenue","orders","units-per-order","discount-rate","revenue-per-session"],"prose":{"why_it_matters":"Revenue is orders × AOV, so AOV separates \"fewer people bought\" from \"people bought less\". It moves with prices, discounts, basket size and who is buying, not with traffic. At Northwind, $1 of AOV across 13,300 orders is $13,300 a week, the same revenue as about 135 more orders.","pitfalls":["Averages follow large orders. A few wholesale or bulk orders can lift a small store's AOV 10% in a week; check the median order beside it.","Dividing net revenue after refunds by orders makes AOV move with refunds on earlier weeks' orders. This spec divides the week's own order revenue by its order count and reads refunds in refund rate.","Including tax and shipping makes AOV move with tax rules, destinations and carrier prices. Keep both out.","A promotion that lowers AOV can still raise revenue. Judge AOV with orders beside it, never alone."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "blended-cac": { yaml: "id: blended-cac\nname: Blended customer acquisition cost\naliases:\n  - CAC\n  - Customer acquisition cost\n  - Blended CAC\n  - Cost to acquire a customer\nfamily: acquisition\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: Acquisition spend in the week divided by every new paying customer won that week, whether they came from ads or not.\n  formula: Acquisition spend ÷ customers whose first paid subscription started this week\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the reporting currency.\n      - name: channel\n        description: The platform or cost line (google, linkedin, meta, sales, agency).\n  - name: subscription_started\n    description: A subscription's first paid period began, after any free trial.\n    also_called: [customer.subscription.created, Subscription Started, subscription_activated]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: Monthly amount of the new subscription, after discounts, before tax.\n      - name: plan\n        description: The plan the customer started on.\n\nnumerator:\n  label: Acquisition spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: New paying customers\n  aggregate: first_time_users\n  event: subscription_started\n\nnoise:\n  type: process\n  min_denominator: 10\n  volume_unit: new paying customers a week\n  typical: 1000\n\nexample:\n  business: saas\n  level: 1150\n  volume: 24\n  trend: 0.1\n\ndrivers:\n  - id: data\n    label: Spend and billing data\n    dropped:\n      check: Is a channel's spend missing, or are migrated or duplicate subscriptions counting as new customers?\n      yes: Spend shows gaps for one channel, or new customers jump on one day with no matching signups.\n    spiked:\n      check: Is spend synced twice, or did a billing change stop new subscriptions being recorded?\n      yes: One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a quarter-end or a promotion bring forward deals that were already in the pipeline?\n      yes: New customers jump in the last week of a quarter or a promotion while spend holds.\n    spiked:\n      check: Is this a holiday week, when buyers are away but campaigns keep spending?\n      yes: New customers fall in holiday weeks and the same weeks last year show it.\n  - id: new-customers\n    label: New paying customers\n    metric: new-paid-accounts\n    dropped:\n      check: Did more customers start paying at steady spend?\n      yes: New paid accounts rise by about as much as CAC falls.\n    spiked:\n      check: Did fewer customers start paying at steady spend?\n      yes: New paid accounts fall by about as much as CAC rises; look at the trial and signup steps next.\n  - id: spend\n    label: Acquisition spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall while new customers held?\n      yes: Spend falls on channels that were not producing customers this week.\n    spiked:\n      check: Did a new channel, a budget increase or a conference add cost before it adds customers?\n      yes: Spend rises on one channel or line; customers from it, if any, arrive weeks later.\n  - id: trial-conversion\n    label: Trial conversion\n    metric: trial-conversion-rate\n    dropped:\n      check: Did a larger share of trials turn into paying customers?\n      yes: Trial conversion rises while trial starts hold.\n    spiked:\n      check: Did fewer trials convert, from an onboarding, pricing or payment change?\n      yes: Trial conversion falls while trial starts hold.\n  - id: signups\n    label: Signups\n    metric: signups\n    dropped:\n      check: Did signups rise a few weeks ago, and are those cohorts paying now?\n      yes: A signup rise four to eight weeks back lines up with this week's new customers.\n    spiked:\n      check: Did signups fall a few weeks ago, so fewer trials are converting now?\n      yes: A signup drop four to eight weeks back lines up with this week's fall in new customers.\n\ndiagnose_order: [data, calendar, new-customers, spend, trial-conversion, signups]\n\nrelated: [ncac, cac-payback, ltv-to-cac, ad-spend, new-paid-accounts, new-mrr]\n\nprose:\n  why_it_matters: >-\n    CAC is what a new customer costs, and with the revenue they bring it decides how fast the\n    business can grow on its own cash. Blended CAC divides all acquisition spend by all new\n    customers, so it can't be flattered by an attribution model. At $1,150 per customer and\n    $126 a month in revenue, the spend takes about a year of gross margin to earn back.\n  pitfalls:\n    - Fully loaded CAC also includes sales and marketing salaries, agency fees and tools. Synced ad spend alone is media CAC, often less than half the full figure in sales-led B2B; add the other costs as their own channel to blend them in.\n    - Spend and customers don't land in the same week. A B2B sale can take one to three months from first click, so weekly CAC swings; read the trailing 13 weeks for planning and the weekly number for direction.\n    - Blended CAC improves when organic signups grow, even if every paid channel got worse. Read paid CAC by channel before raising budgets.\n    - Count customers, not subscriptions. A customer adding a second workspace is expansion, not a new customer.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"blended-cac","name":"Blended customer acquisition cost","aliases":["CAC","Customer acquisition cost","Blended CAC","Cost to acquire a customer"],"family":"acquisition","kind":"currency","polarity":"down-is-good","definition":{"one_line":"Acquisition spend in the week divided by every new paying customer won that week, whether they came from ads or not.","formula":"Acquisition spend ÷ customers whose first paid subscription started this week"},"events":[{"name":"ad_spend","description":"One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the reporting currency."},{"name":"channel","description":"The platform or cost line (google, linkedin, meta, sales, agency)."}]},{"name":"subscription_started","description":"A subscription's first paid period began, after any free trial.","also_called":["customer.subscription.created","Subscription Started","subscription_activated"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"Monthly amount of the new subscription, after discounts, before tax."},{"name":"plan","description":"The plan the customer started on."}]}],"numerator":{"label":"Acquisition spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"New paying customers","aggregate":"first_time_users","event":"subscription_started"},"noise":{"type":"process","min_denominator":10,"volume_unit":"new paying customers a week","typical":1000},"example":{"business":"saas","level":1150,"volume":24,"trend":0.1},"drivers":[{"id":"data","label":"Spend and billing data","dropped":{"check":"Is a channel's spend missing, or are migrated or duplicate subscriptions counting as new customers?","yes":"Spend shows gaps for one channel, or new customers jump on one day with no matching signups."},"spiked":{"check":"Is spend synced twice, or did a billing change stop new subscriptions being recorded?","yes":"One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a quarter-end or a promotion bring forward deals that were already in the pipeline?","yes":"New customers jump in the last week of a quarter or a promotion while spend holds."},"spiked":{"check":"Is this a holiday week, when buyers are away but campaigns keep spending?","yes":"New customers fall in holiday weeks and the same weeks last year show it."}},{"id":"new-customers","label":"New paying customers","metric":"new-paid-accounts","dropped":{"check":"Did more customers start paying at steady spend?","yes":"New paid accounts rise by about as much as CAC falls."},"spiked":{"check":"Did fewer customers start paying at steady spend?","yes":"New paid accounts fall by about as much as CAC rises; look at the trial and signup steps next."}},{"id":"spend","label":"Acquisition spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall while new customers held?","yes":"Spend falls on channels that were not producing customers this week."},"spiked":{"check":"Did a new channel, a budget increase or a conference add cost before it adds customers?","yes":"Spend rises on one channel or line; customers from it, if any, arrive weeks later."}},{"id":"trial-conversion","label":"Trial conversion","metric":"trial-conversion-rate","dropped":{"check":"Did a larger share of trials turn into paying customers?","yes":"Trial conversion rises while trial starts hold."},"spiked":{"check":"Did fewer trials convert, from an onboarding, pricing or payment change?","yes":"Trial conversion falls while trial starts hold."}},{"id":"signups","label":"Signups","metric":"signups","dropped":{"check":"Did signups rise a few weeks ago, and are those cohorts paying now?","yes":"A signup rise four to eight weeks back lines up with this week's new customers."},"spiked":{"check":"Did signups fall a few weeks ago, so fewer trials are converting now?","yes":"A signup drop four to eight weeks back lines up with this week's fall in new customers."}}],"diagnose_order":["data","calendar","new-customers","spend","trial-conversion","signups"],"related":["ncac","cac-payback","ltv-to-cac","ad-spend","new-paid-accounts","new-mrr"],"prose":{"why_it_matters":"CAC is what a new customer costs, and with the revenue they bring it decides how fast the business can grow on its own cash. Blended CAC divides all acquisition spend by all new customers, so it can't be flattered by an attribution model. At $1,150 per customer and $126 a month in revenue, the spend takes about a year of gross margin to earn back.","pitfalls":["Fully loaded CAC also includes sales and marketing salaries, agency fees and tools. Synced ad spend alone is media CAC, often less than half the full figure in sales-led B2B; add the other costs as their own channel to blend them in.","Spend and customers don't land in the same week. A B2B sale can take one to three months from first click, so weekly CAC swings; read the trailing 13 weeks for planning and the weekly number for direction.","Blended CAC improves when organic signups grow, even if every paid channel got worse. Read paid CAC by channel before raising budgets.","Count customers, not subscriptions. A customer adding a second workspace is expansion, not a new customer."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "bounce-rate": { yaml: "id: bounce-rate\nname: Bounce rate\naliases:\n  - Website bounce rate\n  - Bounced sessions\n  - Single-page session rate\nfamily: traffic\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of sessions that view one page, take no action and leave within 10 seconds.\n  formula: Sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; ties every event in a visit together.\n      - name: $pathname\n        description: The landing page path, for finding the page that bounces.\n  - name: $autocapture\n    description: A click, form change or submit captured automatically by PostHog. Counts as engagement.\n    also_called: [click, user_engagement]\n  - name: $pageleave\n    description: Sent when the visitor leaves a page; its timestamp gives time on the last page.\n    also_called: [page_leave]\n\nnumerator:\n  label: Bounced sessions\n  aggregate: unique_sessions\n  event: $pageview\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nqueries:\n  hogql: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\n    SELECT week, numerator, denominator, if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM (\n      SELECT\n        week,\n        countIf(pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n        count() AS denominator\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(min(timestamp)) AS week,\n          countIf(event = '$pageview') AS pageviews,\n          countIf(event IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n          dateDiff('second', min(timestamp), max(timestamp)) AS seconds\n        FROM events\n        WHERE $session_id IS NOT NULL\n          AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n          AND timestamp < toStartOfWeek(now(), 1)\n        GROUP BY session_id\n        HAVING pageviews > 0\n      )\n      GROUP BY week\n    )\n    ORDER BY week\n  postgres: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\n    WITH visits AS (\n      SELECT\n        session_id,\n        date_trunc('week', min(occurred_at))::date AS week,\n        count(*) FILTER (WHERE event_name = '$pageview') AS pageviews,\n        count(*) FILTER (\n          WHERE event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')\n        ) AS actions,\n        extract(epoch FROM max(occurred_at) - min(occurred_at)) AS seconds\n      FROM events\n      WHERE session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY session_id\n    )\n    SELECT\n      week,\n      count(*) FILTER (WHERE pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n      count(*) AS denominator,\n      (count(*) FILTER (WHERE pageviews = 1 AND actions = 0 AND seconds < 10))::numeric / nullif(count(*), 0) AS value\n    FROM visits\n    WHERE pageviews > 0\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\n    WITH visits AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(MIN(occurred_at)), ISOWEEK) AS week,\n        COUNTIF(event_name = '$pageview') AS pageviews,\n        COUNTIF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n        TIMESTAMP_DIFF(MAX(occurred_at), MIN(occurred_at), SECOND) AS seconds\n      FROM events\n      WHERE session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY session_id\n    )\n    SELECT\n      week,\n      COUNTIF(pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n      COUNT(*) AS denominator,\n      SAFE_DIVIDE(COUNTIF(pageviews = 1 AND actions = 0 AND seconds < 10), COUNT(*)) AS value\n    FROM visits\n    WHERE pageviews > 0\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\n    -- Assumes WEEK_START = 1 (Monday).\n    WITH visits AS (\n      SELECT\n        session_id,\n        DATE_TRUNC('week', MIN(occurred_at))::date AS week,\n        COUNT_IF(event_name = '$pageview') AS pageviews,\n        COUNT_IF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n        DATEDIFF('second', MIN(occurred_at), MAX(occurred_at)) AS seconds\n      FROM events\n      WHERE session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY session_id\n    )\n    SELECT\n      week,\n      COUNT_IF(pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n      COUNT(*) AS denominator,\n      DIV0NULL(COUNT_IF(pageviews = 1 AND actions = 0 AND seconds < 10), COUNT(*)) AS value\n    FROM visits\n    WHERE pageviews > 0\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: sessions a week\n  typical: 0.4\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.38\n  volume: 520000\n  trend: -0.02\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Is a page view or click event now firing twice, so single-page visits no longer look like bounces?\n      yes: Bounce rate falls by many points overnight, page views per session jump, and orders don't move.\n    spiked:\n      check: Did a release stop route changes, clicks or page-leave events being recorded?\n      yes: Bounce rises on the day of a release while orders hold and page views per session fall.\n  - id: bots\n    label: Bots and junk traffic\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did a bot or spam source that always bounced stop?\n      yes: One country, browser or referrer that bounced nearly every time has disappeared.\n    spiked:\n      check: Is a crawler, uptime checker or spam referrer adding one-page visits?\n      yes: The extra sessions come from one country, browser or data-centre network, last zero seconds and never order.\n  - id: site-speed\n    label: Site speed and errors\n    feed: cloudflare\n    dropped:\n      check: Did a slow or broken period last week end?\n      yes: Bounce returns to its usual level once load times recover.\n    spiked:\n      check: Did pages load slowly, error or fail to render, from an outage or a heavy release?\n      yes: Bounce rises in the hours of an incident, or on one device or browser after a release.\n  - id: traffic-mix\n    label: Who arrived\n    metric: paid-sessions\n    breakdown: utm_source\n    dropped:\n      check: Did low-intent traffic, such as broad prospecting or a viral link, shrink?\n      yes: The source that bounced most sends fewer sessions while each source's own bounce rate holds.\n    spiked:\n      check: Did a campaign, social post or press link bring visitors who leave at once?\n      yes: One source grows and bounces far above the rest; every other source holds its rate.\n  - id: landing-pages\n    label: Landing pages\n    breakdown: $pathname\n    dropped:\n      check: Did a landing page get faster, clearer, or start matching its ad better?\n      yes: Bounce falls on that page from the day it changed.\n    spiked:\n      check: Is a sold-out product, a 404 or a changed page catching traffic from an ad or search result?\n      yes: One landing path accounts for most of the extra bounces.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the fall on one device only, after a layout change?\n      yes: One device improves while the others hold.\n    spiked:\n      check: Is the rise on one device only?\n      yes: Mobile bounce jumps after a release, which points at a layout or pop-up problem.\n\ndiagnose_order: [tracking, bots, site-speed, traffic-mix, landing-pages, device-split]\n\nrelated: [sessions, pages-per-session, product-view-rate, conversion-rate, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    Bounce rate is the cheapest early warning a store has: it moves within hours of a broken\n    page, a slow release or a campaign sending the wrong people, long before orders are counted.\n    On 520,000 sessions a week, two extra points of bounce is about 10,000 visits that never see\n    a product, which at a 2.5% conversion rate is about 250 orders.\n  pitfalls:\n    - Bounce rates from different tools don't compare. Universal Analytics counted any one-page visit, GA4 reports one minus engagement rate, and this spec follows PostHog's rule of one page, no click and under 10 seconds.\n    - A bounce rate under 15% almost always means a page view or event fires twice, not a great site. Check the tags before celebrating.\n    - Without a page-leave event or click tracking, the 10-second rule can't fire and every one-page visit counts as a bounce, so the rate reads 10 to 20 points high.\n    - A single-page blog post or a store-locator page that answers the question bounces by design. Read bounce by landing page, not as one number.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"bounce-rate","name":"Bounce rate","aliases":["Website bounce rate","Bounced sessions","Single-page session rate"],"family":"traffic","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of sessions that view one page, take no action and leave within 10 seconds.","formula":"Sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; ties every event in a visit together."},{"name":"$pathname","description":"The landing page path, for finding the page that bounces."}]},{"name":"$autocapture","description":"A click, form change or submit captured automatically by PostHog. Counts as engagement.","also_called":["click","user_engagement"]},{"name":"$pageleave","description":"Sent when the visitor leaves a page; its timestamp gives time on the last page.","also_called":["page_leave"]}],"numerator":{"label":"Bounced sessions","aggregate":"unique_sessions","event":"$pageview"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"queries":{"hogql":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\nSELECT week, numerator, denominator, if(denominator > 0, numerator / denominator, NULL) AS value\nFROM (\n  SELECT\n    week,\n    countIf(pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n    count() AS denominator\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(min(timestamp)) AS week,\n      countIf(event = '$pageview') AS pageviews,\n      countIf(event IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n      dateDiff('second', min(timestamp), max(timestamp)) AS seconds\n    FROM events\n    WHERE $session_id IS NOT NULL\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY session_id\n    HAVING pageviews > 0\n  )\n  GROUP BY week\n)\nORDER BY week","postgres":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\nWITH visits AS (\n  SELECT\n    session_id,\n    date_trunc('week', min(occurred_at))::date AS week,\n    count(*) FILTER (WHERE event_name = '$pageview') AS pageviews,\n    count(*) FILTER (\n      WHERE event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')\n    ) AS actions,\n    extract(epoch FROM max(occurred_at) - min(occurred_at)) AS seconds\n  FROM events\n  WHERE session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY session_id\n)\nSELECT\n  week,\n  count(*) FILTER (WHERE pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n  count(*) AS denominator,\n  (count(*) FILTER (WHERE pageviews = 1 AND actions = 0 AND seconds < 10))::numeric / nullif(count(*), 0) AS value\nFROM visits\nWHERE pageviews > 0\nGROUP BY week\nORDER BY week;","bigquery":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\nWITH visits AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(MIN(occurred_at)), ISOWEEK) AS week,\n    COUNTIF(event_name = '$pageview') AS pageviews,\n    COUNTIF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n    TIMESTAMP_DIFF(MAX(occurred_at), MIN(occurred_at), SECOND) AS seconds\n  FROM events\n  WHERE session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY session_id\n)\nSELECT\n  week,\n  COUNTIF(pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n  COUNT(*) AS denominator,\n  SAFE_DIVIDE(COUNTIF(pageviews = 1 AND actions = 0 AND seconds < 10), COUNT(*)) AS value\nFROM visits\nWHERE pageviews > 0\nGROUP BY week\nORDER BY week;","snowflake":"-- Bounce rate per week: sessions with one page view, no click or key action and under 10 seconds ÷ sessions with a page view.\n-- Assumes WEEK_START = 1 (Monday).\nWITH visits AS (\n  SELECT\n    session_id,\n    DATE_TRUNC('week', MIN(occurred_at))::date AS week,\n    COUNT_IF(event_name = '$pageview') AS pageviews,\n    COUNT_IF(event_name IN ('$autocapture', 'product_added', 'product_searched', 'checkout_started', 'signed_up', 'order_completed')) AS actions,\n    DATEDIFF('second', MIN(occurred_at), MAX(occurred_at)) AS seconds\n  FROM events\n  WHERE session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY session_id\n)\nSELECT\n  week,\n  COUNT_IF(pageviews = 1 AND actions = 0 AND seconds < 10) AS numerator,\n  COUNT(*) AS denominator,\n  DIV0NULL(COUNT_IF(pageviews = 1 AND actions = 0 AND seconds < 10), COUNT(*)) AS value\nFROM visits\nWHERE pageviews > 0\nGROUP BY week\nORDER BY week;"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"sessions a week","typical":0.4,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.38,"volume":520000,"trend":-0.02},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Is a page view or click event now firing twice, so single-page visits no longer look like bounces?","yes":"Bounce rate falls by many points overnight, page views per session jump, and orders don't move."},"spiked":{"check":"Did a release stop route changes, clicks or page-leave events being recorded?","yes":"Bounce rises on the day of a release while orders hold and page views per session fall."}},{"id":"bots","label":"Bots and junk traffic","breakdown":"$geoip_country_code","dropped":{"check":"Did a bot or spam source that always bounced stop?","yes":"One country, browser or referrer that bounced nearly every time has disappeared."},"spiked":{"check":"Is a crawler, uptime checker or spam referrer adding one-page visits?","yes":"The extra sessions come from one country, browser or data-centre network, last zero seconds and never order."}},{"id":"site-speed","label":"Site speed and errors","feed":"cloudflare","dropped":{"check":"Did a slow or broken period last week end?","yes":"Bounce returns to its usual level once load times recover."},"spiked":{"check":"Did pages load slowly, error or fail to render, from an outage or a heavy release?","yes":"Bounce rises in the hours of an incident, or on one device or browser after a release."}},{"id":"traffic-mix","label":"Who arrived","metric":"paid-sessions","breakdown":"utm_source","dropped":{"check":"Did low-intent traffic, such as broad prospecting or a viral link, shrink?","yes":"The source that bounced most sends fewer sessions while each source's own bounce rate holds."},"spiked":{"check":"Did a campaign, social post or press link bring visitors who leave at once?","yes":"One source grows and bounces far above the rest; every other source holds its rate."}},{"id":"landing-pages","label":"Landing pages","breakdown":"$pathname","dropped":{"check":"Did a landing page get faster, clearer, or start matching its ad better?","yes":"Bounce falls on that page from the day it changed."},"spiked":{"check":"Is a sold-out product, a 404 or a changed page catching traffic from an ad or search result?","yes":"One landing path accounts for most of the extra bounces."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the fall on one device only, after a layout change?","yes":"One device improves while the others hold."},"spiked":{"check":"Is the rise on one device only?","yes":"Mobile bounce jumps after a release, which points at a layout or pop-up problem."}}],"diagnose_order":["tracking","bots","site-speed","traffic-mix","landing-pages","device-split"],"related":["sessions","pages-per-session","product-view-rate","conversion-rate","paid-sessions"],"prose":{"why_it_matters":"Bounce rate is the cheapest early warning a store has: it moves within hours of a broken page, a slow release or a campaign sending the wrong people, long before orders are counted. On 520,000 sessions a week, two extra points of bounce is about 10,000 visits that never see a product, which at a 2.5% conversion rate is about 250 orders.","pitfalls":["Bounce rates from different tools don't compare. Universal Analytics counted any one-page visit, GA4 reports one minus engagement rate, and this spec follows PostHog's rule of one page, no click and under 10 seconds.","A bounce rate under 15% almost always means a page view or event fires twice, not a great site. Check the tags before celebrating.","Without a page-leave event or click tracking, the 10-second rule can't fire and every one-page visit counts as a bounce, so the rate reads 10 to 20 points high.","A single-page blog post or a store-locator page that answers the question bounces by design. Read bounce by landing page, not as one number."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cac-payback": { yaml: "id: cac-payback\nname: CAC payback period\naliases:\n  - Payback period\n  - CAC payback months\n  - Months to recover CAC\nfamily: acquisition\nkind: duration\nduration_unit: months\npolarity: down-is-good\n\ndefinition:\n  one_line: How many months of gross margin from the week's new customers it takes to earn back what was spent to win them.\n  formula: Acquisition spend ÷ (new MRR from first subscriptions × gross margin)\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the reporting currency.\n  - name: subscription_started\n    description: A subscription's first paid period began, after any free trial.\n    also_called: [customer.subscription.created, Subscription Started, subscription_activated]\n    properties:\n      - name: mrr\n        description: Monthly amount of the new subscription, after discounts, before tax. Annual plans divided by twelve.\n      - name: plan\n        description: The plan the customer started on.\n\nnumerator:\n  label: Acquisition spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: New MRR × gross margin\n  aggregate: sum\n  event: subscription_started\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    SELECT\n      s.week AS week,\n      s.spend AS numerator,\n      coalesce(n.new_mrr, 0) * 0.80 AS denominator,\n      if(coalesce(n.new_mrr, 0) > 0, s.spend / (n.new_mrr * 0.80), NULL) AS value\n    FROM (\n      SELECT toMonday(timestamp) AS week, sum(toFloat(properties.spend)) AS spend\n      FROM events\n      WHERE event = 'ad_spend'\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY week\n    ) AS s\n    LEFT JOIN (\n      SELECT toMonday(timestamp) AS week, sum(toFloat(properties.mrr)) AS new_mrr\n      FROM events\n      WHERE event = 'subscription_started'\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY week\n    ) AS n ON n.week = s.week\n    ORDER BY week\n  postgres: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    WITH spend AS (\n      SELECT date_trunc('week', occurred_at)::date AS week, sum((properties->>'spend')::numeric) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY 1\n    ),\n    new_mrr AS (\n      SELECT date_trunc('week', occurred_at)::date AS week, sum((properties->>'mrr')::numeric) AS new_mrr\n      FROM events\n      WHERE event_name = 'subscription_started'\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY 1\n    )\n    SELECT\n      s.week,\n      s.spend AS numerator,\n      coalesce(n.new_mrr, 0) * 0.80 AS denominator,\n      s.spend / nullif(coalesce(n.new_mrr, 0) * 0.80, 0) AS value\n    FROM spend AS s\n    LEFT JOIN new_mrr AS n ON n.week = s.week\n    ORDER BY s.week;\n  bigquery: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n    -- Gross margin is set to 0.80 below; replace it with your own.\n    WITH spend AS (\n      SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY 1\n    ),\n    new_mrr AS (\n      SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64)) AS new_mrr\n      FROM events\n      WHERE event_name = 'subscription_started'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY 1\n    )\n    SELECT\n      s.week,\n      s.spend AS numerator,\n      COALESCE(n.new_mrr, 0) * 0.80 AS denominator,\n      SAFE_DIVIDE(s.spend, COALESCE(n.new_mrr, 0) * 0.80) AS value\n    FROM spend AS s\n    LEFT JOIN new_mrr AS n ON n.week = s.week\n    ORDER BY s.week;\n  snowflake: |-\n    -- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n    -- Gross margin is set to 0.80 below; replace it with your own. Assumes WEEK_START = 1 (Monday).\n    WITH spend AS (\n      SELECT DATE_TRUNC('week', occurred_at)::date AS week, SUM(properties:\"spend\"::float) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY 1\n    ),\n    new_mrr AS (\n      SELECT DATE_TRUNC('week', occurred_at)::date AS week, SUM(properties:\"mrr\"::float) AS new_mrr\n      FROM events\n      WHERE event_name = 'subscription_started'\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY 1\n    )\n    SELECT\n      s.week,\n      s.spend AS numerator,\n      COALESCE(n.new_mrr, 0) * 0.80 AS denominator,\n      DIV0NULL(s.spend, COALESCE(n.new_mrr, 0) * 0.80) AS value\n    FROM spend AS s\n    LEFT JOIN new_mrr AS n ON n.week = s.week\n    ORDER BY s.week;\n\nnoise:\n  type: process\n  min_denominator: 10\n  volume_unit: new subscriptions a week\n  typical: 12\n\nexample:\n  business: saas\n  level: 11.5\n  volume: 24\n  trend: 0.06\n\ndrivers:\n  - id: data\n    label: Spend and billing data\n    dropped:\n      check: Are migrated, reactivated or duplicate subscriptions counting as new MRR, or is spend missing?\n      yes: New MRR jumps on one day with no matching signups, or one channel's spend has gaps.\n    spiked:\n      check: Is spend synced twice, or did a billing change stop new subscriptions being recorded?\n      yes: One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a quarter-end push or an annual-plan promotion bring a cluster of new subscriptions?\n      yes: New MRR jumps in the last week of a quarter or a promotion while spend holds.\n    spiked:\n      check: Is this a holiday week, when buyers are away but campaigns keep spending?\n      yes: New MRR falls in holiday weeks and the same weeks last year show it.\n  - id: cac\n    label: Cost per new customer\n    metric: blended-cac\n    dropped:\n      check: Did each new customer cost less, from cheaper channels or better trial conversion?\n      yes: Blended CAC falls by about as much as payback does, while new-customer revenue holds.\n    spiked:\n      check: Did each new customer cost more, from a new channel, a budget increase or fewer conversions?\n      yes: Blended CAC rises by about as much as payback does, while new-customer revenue holds.\n  - id: new-mrr\n    label: New MRR per customer\n    metric: new-mrr\n    breakdown: plan\n    dropped:\n      check: Did new customers start on bigger plans, more seats or annual contracts?\n      yes: New MRR per new customer rises; the plan mix shifts toward higher tiers.\n    spiked:\n      check: Did new customers start on smaller plans, or did a discount lower first-year prices?\n      yes: New MRR per new customer falls; the plan mix shifts toward entry tiers or discounted prices.\n  - id: spend-timing\n    label: Spend ahead of customers\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall while customers from earlier weeks' pipeline kept arriving?\n      yes: Spend falls this week while new MRR holds; expect payback to rise again when those deals run out.\n    spiked:\n      check: Did a budget increase, an event or a new channel add cost before the customers it will bring?\n      yes: Spend rises on one channel or line while new MRR holds; judge it again in four to eight weeks.\n\ndiagnose_order: [data, calendar, spend-timing, cac, new-mrr]\n\nrelated: [blended-cac, ltv-to-cac, new-mrr, arpa, gross-margin, net-revenue-retention]\n\nprose:\n  why_it_matters: >-\n    Payback is how long the business waits to get its acquisition money back, which sets how\n    fast it can grow without raising more. Under 12 months is strong for SMB SaaS and 18 to 24\n    months is common in mid-market and enterprise. At 11.5 months, a dollar spent this week\n    comes back in just under a year and can then be spent again.\n  pitfalls:\n    - Payback without gross margin overstates how fast money comes back. On 80% margin, revenue-based payback reads 20% too short.\n    - Weekly payback swings with deal timing, because spend leads new customers by weeks or months. Plan on the trailing quarter and read the weekly number for direction only.\n    - It assumes customers stay long enough to pay it back. With 3% monthly logo churn, a fifth of a cohort is gone before month 8; read it with net revenue retention.\n    - Media spend alone gives a flattering number. Sales salaries, agency fees and tools belong in the spend for a fully loaded payback.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cac-payback","name":"CAC payback period","aliases":["Payback period","CAC payback months","Months to recover CAC"],"family":"acquisition","kind":"duration","duration_unit":"months","polarity":"down-is-good","definition":{"one_line":"How many months of gross margin from the week's new customers it takes to earn back what was spent to win them.","formula":"Acquisition spend ÷ (new MRR from first subscriptions × gross margin)"},"events":[{"name":"ad_spend","description":"One row per channel per day of acquisition cost. Ad platforms sync their media spend; other costs can be added as their own channel.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the reporting currency."}]},{"name":"subscription_started","description":"A subscription's first paid period began, after any free trial.","also_called":["customer.subscription.created","Subscription Started","subscription_activated"],"properties":[{"name":"mrr","description":"Monthly amount of the new subscription, after discounts, before tax. Annual plans divided by twelve."},{"name":"plan","description":"The plan the customer started on."}]}],"numerator":{"label":"Acquisition spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"New MRR × gross margin","aggregate":"sum","event":"subscription_started","property":"mrr"},"queries":{"hogql":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n-- Gross margin is set to 0.80 below; replace it with your own.\nSELECT\n  s.week AS week,\n  s.spend AS numerator,\n  coalesce(n.new_mrr, 0) * 0.80 AS denominator,\n  if(coalesce(n.new_mrr, 0) > 0, s.spend / (n.new_mrr * 0.80), NULL) AS value\nFROM (\n  SELECT toMonday(timestamp) AS week, sum(toFloat(properties.spend)) AS spend\n  FROM events\n  WHERE event = 'ad_spend'\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY week\n) AS s\nLEFT JOIN (\n  SELECT toMonday(timestamp) AS week, sum(toFloat(properties.mrr)) AS new_mrr\n  FROM events\n  WHERE event = 'subscription_started'\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY week\n) AS n ON n.week = s.week\nORDER BY week","postgres":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n-- Gross margin is set to 0.80 below; replace it with your own.\nWITH spend AS (\n  SELECT date_trunc('week', occurred_at)::date AS week, sum((properties->>'spend')::numeric) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY 1\n),\nnew_mrr AS (\n  SELECT date_trunc('week', occurred_at)::date AS week, sum((properties->>'mrr')::numeric) AS new_mrr\n  FROM events\n  WHERE event_name = 'subscription_started'\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY 1\n)\nSELECT\n  s.week,\n  s.spend AS numerator,\n  coalesce(n.new_mrr, 0) * 0.80 AS denominator,\n  s.spend / nullif(coalesce(n.new_mrr, 0) * 0.80, 0) AS value\nFROM spend AS s\nLEFT JOIN new_mrr AS n ON n.week = s.week\nORDER BY s.week;","bigquery":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n-- Gross margin is set to 0.80 below; replace it with your own.\nWITH spend AS (\n  SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY 1\n),\nnew_mrr AS (\n  SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, SUM(CAST(JSON_VALUE(properties, '$.mrr') AS FLOAT64)) AS new_mrr\n  FROM events\n  WHERE event_name = 'subscription_started'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY 1\n)\nSELECT\n  s.week,\n  s.spend AS numerator,\n  COALESCE(n.new_mrr, 0) * 0.80 AS denominator,\n  SAFE_DIVIDE(s.spend, COALESCE(n.new_mrr, 0) * 0.80) AS value\nFROM spend AS s\nLEFT JOIN new_mrr AS n ON n.week = s.week\nORDER BY s.week;","snowflake":"-- CAC payback per week, in months: acquisition spend ÷ (new MRR from first subscriptions × gross margin).\n-- Gross margin is set to 0.80 below; replace it with your own. Assumes WEEK_START = 1 (Monday).\nWITH spend AS (\n  SELECT DATE_TRUNC('week', occurred_at)::date AS week, SUM(properties:\"spend\"::float) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY 1\n),\nnew_mrr AS (\n  SELECT DATE_TRUNC('week', occurred_at)::date AS week, SUM(properties:\"mrr\"::float) AS new_mrr\n  FROM events\n  WHERE event_name = 'subscription_started'\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY 1\n)\nSELECT\n  s.week,\n  s.spend AS numerator,\n  COALESCE(n.new_mrr, 0) * 0.80 AS denominator,\n  DIV0NULL(s.spend, COALESCE(n.new_mrr, 0) * 0.80) AS value\nFROM spend AS s\nLEFT JOIN new_mrr AS n ON n.week = s.week\nORDER BY s.week;"},"noise":{"type":"process","min_denominator":10,"volume_unit":"new subscriptions a week","typical":12},"example":{"business":"saas","level":11.5,"volume":24,"trend":0.06},"drivers":[{"id":"data","label":"Spend and billing data","dropped":{"check":"Are migrated, reactivated or duplicate subscriptions counting as new MRR, or is spend missing?","yes":"New MRR jumps on one day with no matching signups, or one channel's spend has gaps."},"spiked":{"check":"Is spend synced twice, or did a billing change stop new subscriptions being recorded?","yes":"One channel's spend doubles for a day, or new subscriptions in the billing system exceed those recorded."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a quarter-end push or an annual-plan promotion bring a cluster of new subscriptions?","yes":"New MRR jumps in the last week of a quarter or a promotion while spend holds."},"spiked":{"check":"Is this a holiday week, when buyers are away but campaigns keep spending?","yes":"New MRR falls in holiday weeks and the same weeks last year show it."}},{"id":"cac","label":"Cost per new customer","metric":"blended-cac","dropped":{"check":"Did each new customer cost less, from cheaper channels or better trial conversion?","yes":"Blended CAC falls by about as much as payback does, while new-customer revenue holds."},"spiked":{"check":"Did each new customer cost more, from a new channel, a budget increase or fewer conversions?","yes":"Blended CAC rises by about as much as payback does, while new-customer revenue holds."}},{"id":"new-mrr","label":"New MRR per customer","metric":"new-mrr","breakdown":"plan","dropped":{"check":"Did new customers start on bigger plans, more seats or annual contracts?","yes":"New MRR per new customer rises; the plan mix shifts toward higher tiers."},"spiked":{"check":"Did new customers start on smaller plans, or did a discount lower first-year prices?","yes":"New MRR per new customer falls; the plan mix shifts toward entry tiers or discounted prices."}},{"id":"spend-timing","label":"Spend ahead of customers","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall while customers from earlier weeks' pipeline kept arriving?","yes":"Spend falls this week while new MRR holds; expect payback to rise again when those deals run out."},"spiked":{"check":"Did a budget increase, an event or a new channel add cost before the customers it will bring?","yes":"Spend rises on one channel or line while new MRR holds; judge it again in four to eight weeks."}}],"diagnose_order":["data","calendar","spend-timing","cac","new-mrr"],"related":["blended-cac","ltv-to-cac","new-mrr","arpa","gross-margin","net-revenue-retention"],"prose":{"why_it_matters":"Payback is how long the business waits to get its acquisition money back, which sets how fast it can grow without raising more. Under 12 months is strong for SMB SaaS and 18 to 24 months is common in mid-market and enterprise. At 11.5 months, a dollar spent this week comes back in just under a year and can then be spent again.","pitfalls":["Payback without gross margin overstates how fast money comes back. On 80% margin, revenue-based payback reads 20% too short.","Weekly payback swings with deal timing, because spend leads new customers by weeks or months. Plan on the trailing quarter and read the weekly number for direction only.","It assumes customers stay long enough to pay it back. With 3% monthly logo churn, a fifth of a cohort is gone before month 8; read it with net revenue retention.","Media spend alone gives a flattering number. Sales salaries, agency fees and tools belong in the spend for a fully loaded payback."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cart-abandonment-rate": { yaml: "id: cart-abandonment-rate\nname: Cart abandonment rate\naliases:\n  - Cart abandonment\n  - Shopping cart abandonment rate\n  - Abandoned cart rate\nfamily: conversion\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of shopping carts that never become a paid order, by Baymard's definition of one minus orders over carts.\n  formula: 1 − sessions with a paid order ÷ sessions that added to cart, both counted in the same week\n\nevents:\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n      - name: quantity\n        description: Units added in this action.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\nsubtract:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: carts a week\n  typical: 0.7\n  reference_volumes: [500, 2000, 10000, 40000]\n\nexample:\n  business: store\n  level: 0.67\n  volume: 40000\n  trend: -0.03\n  season: -0.5\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Is a duplicate order event, or a missing add-to-cart event on one platform, shrinking the gap?\n      yes: Orders recorded exceed orders in the payment processor, or adds fall on one device while orders hold.\n    spiked:\n      check: Did an add-to-cart event start firing twice, or did order events stop being recorded?\n      yes: Carts rise without checkout starts following, or recorded orders fall below the processor's count.\n  - id: calendar\n    label: Sale calendar\n    feed: shopping\n    dropped:\n      check: Is this a sale week, when carts that were parked the week before finally convert?\n      yes: Orders rise faster than carts, and the same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is it the week before a sale, when shoppers fill carts and wait for the discount?\n      yes: Carts rise while orders hold, and the same week last year shows the same rise.\n  - id: cart-to-checkout\n    label: Cart to checkout\n    metric: checkout-start-rate\n    dropped:\n      check: Did more carts move on to checkout, after a cart page or shipping message change?\n      yes: Checkout start rate rises by about as much as abandonment falls.\n    spiked:\n      check: Did fewer carts reach checkout, from a cart page change, a surprise cost or a broken button?\n      yes: Checkout start rate falls while checkout completion holds.\n  - id: checkout-completion\n    label: Checkout completion\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did more started checkouts finish, after a checkout fix or a payment method launch?\n      yes: Checkout conversion rises while checkout starts hold.\n    spiked:\n      check: Did more checkouts fail at shipping, account creation or payment?\n      yes: Checkout conversion falls while checkout starts hold; one step or one payment method explains most of it.\n  - id: extra-costs\n    label: Shipping, tax and fees\n    dropped:\n      check: Did a free-shipping offer, a lower threshold or a clearer delivery date go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n    spiked:\n      check: Did shipping prices, thresholds, duties or fees shown late in checkout change?\n      yes: Exits concentrate on the shipping step, starting the day the change shipped.\n  - id: device-mix\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Did desktop take a larger share of carts, or did mobile abandonment fall?\n      yes: Each device's rate holds and the mix moved, or mobile falls after a release.\n    spiked:\n      check: Did mobile take a larger share of carts, or did mobile abandonment rise on its own?\n      yes: Each device's rate holds and only the mix moved, or mobile rises while desktop holds.\n\ndiagnose_order: [tracking, calendar, cart-to-checkout, checkout-completion, extra-costs, device-mix]\n\nrelated: [checkout-start-rate, checkout-conversion, add-to-cart-rate, conversion-rate, payment-success-rate]\n\nprose:\n  why_it_matters: >-\n    About 70 of every 100 carts are abandoned on the average store, by Baymard Institute's\n    average of dozens of studies, and most of them were never going to buy. The part a store\n    can win back is the rest: extra costs shown late, forced accounts, slow delivery and\n    checkouts that ask too much. At Northwind, with 40,000 carts a week, one point of\n    abandonment is about 400 orders.\n  pitfalls:\n    - Cart abandonment is not checkout abandonment. One minus checkout conversion counts only shoppers who started checkout and reads far lower; comparing either with the other's benchmark is the most common mistake with this number.\n    - This spec compares carts and orders in aggregate, as Baymard does, so a shopper who adds on Monday and buys on Thursday in a new session counts once on each side and nets out.\n    - Orders placed without an add-to-cart, such as buy-now buttons, reorder links and subscription renewals, pull the rate down. Send product_added for them or exclude them.\n    - Mobile carts are abandoned more often than desktop carts, so a rise in mobile share lifts the rate with no change in the store. Split by device before blaming checkout.\n    - The week before a big sale people fill carts and wait. Compare that week with the same week last year, not the week before.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cart-abandonment-rate","name":"Cart abandonment rate","aliases":["Cart abandonment","Shopping cart abandonment rate","Abandoned cart rate"],"family":"conversion","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of shopping carts that never become a paid order, by Baymard's definition of one minus orders over carts.","formula":"1 − sessions with a paid order ÷ sessions that added to cart, both counted in the same week"},"events":[{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."},{"name":"quantity","description":"Units added in this action."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"subtract":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"carts a week","typical":0.7,"reference_volumes":[500,2000,10000,40000]},"example":{"business":"store","level":0.67,"volume":40000,"trend":-0.03,"season":-0.5},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Is a duplicate order event, or a missing add-to-cart event on one platform, shrinking the gap?","yes":"Orders recorded exceed orders in the payment processor, or adds fall on one device while orders hold."},"spiked":{"check":"Did an add-to-cart event start firing twice, or did order events stop being recorded?","yes":"Carts rise without checkout starts following, or recorded orders fall below the processor's count."}},{"id":"calendar","label":"Sale calendar","feed":"shopping","dropped":{"check":"Is this a sale week, when carts that were parked the week before finally convert?","yes":"Orders rise faster than carts, and the same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is it the week before a sale, when shoppers fill carts and wait for the discount?","yes":"Carts rise while orders hold, and the same week last year shows the same rise."}},{"id":"cart-to-checkout","label":"Cart to checkout","metric":"checkout-start-rate","dropped":{"check":"Did more carts move on to checkout, after a cart page or shipping message change?","yes":"Checkout start rate rises by about as much as abandonment falls."},"spiked":{"check":"Did fewer carts reach checkout, from a cart page change, a surprise cost or a broken button?","yes":"Checkout start rate falls while checkout completion holds."}},{"id":"checkout-completion","label":"Checkout completion","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did more started checkouts finish, after a checkout fix or a payment method launch?","yes":"Checkout conversion rises while checkout starts hold."},"spiked":{"check":"Did more checkouts fail at shipping, account creation or payment?","yes":"Checkout conversion falls while checkout starts hold; one step or one payment method explains most of it."}},{"id":"extra-costs","label":"Shipping, tax and fees","dropped":{"check":"Did a free-shipping offer, a lower threshold or a clearer delivery date go live?","yes":"Fewer exits at the shipping step from the day it launched."},"spiked":{"check":"Did shipping prices, thresholds, duties or fees shown late in checkout change?","yes":"Exits concentrate on the shipping step, starting the day the change shipped."}},{"id":"device-mix","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Did desktop take a larger share of carts, or did mobile abandonment fall?","yes":"Each device's rate holds and the mix moved, or mobile falls after a release."},"spiked":{"check":"Did mobile take a larger share of carts, or did mobile abandonment rise on its own?","yes":"Each device's rate holds and only the mix moved, or mobile rises while desktop holds."}}],"diagnose_order":["tracking","calendar","cart-to-checkout","checkout-completion","extra-costs","device-mix"],"related":["checkout-start-rate","checkout-conversion","add-to-cart-rate","conversion-rate","payment-success-rate"],"prose":{"why_it_matters":"About 70 of every 100 carts are abandoned on the average store, by Baymard Institute's average of dozens of studies, and most of them were never going to buy. The part a store can win back is the rest: extra costs shown late, forced accounts, slow delivery and checkouts that ask too much. At Northwind, with 40,000 carts a week, one point of abandonment is about 400 orders.","pitfalls":["Cart abandonment is not checkout abandonment. One minus checkout conversion counts only shoppers who started checkout and reads far lower; comparing either with the other's benchmark is the most common mistake with this number.","This spec compares carts and orders in aggregate, as Baymard does, so a shopper who adds on Monday and buys on Thursday in a new session counts once on each side and nets out.","Orders placed without an add-to-cart, such as buy-now buttons, reorder links and subscription renewals, pull the rate down. Send product_added for them or exclude them.","Mobile carts are abandoned more often than desktop carts, so a rise in mobile share lifts the rate with no change in the store. Split by device before blaming checkout.","The week before a big sale people fill carts and wait. Compare that week with the same week last year, not the week before."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "checkout-conversion": { yaml: "id: checkout-conversion\nname: Checkout conversion\naliases:\n  - Checkout completion rate\n  - Checkout conversion rate\n  - Checkout success rate\nfamily: conversion\ncatalog_id: checkout_completion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of started checkouts that become a paid order in the same week.\n  formula: Paid orders ÷ checkouts started\n\nevents:\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: checkouts started a week\n  typical: 0.62\n\nexample:\n  business: store\n  level: 0.63\n  volume: 20900\n  trend: 0.02\n  season: 0.5\n\ndrivers:\n  - id: payment-failures\n    label: Payment failures\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did payment success fall, and is it one gateway, card brand or wallet?\n      yes: Declines or errors rise for one processor or method while the others hold.\n    spiked:\n      check: Did a payment problem from the week before just clear?\n      yes: Payment success returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls several points while desktop is flat, which points at a release or layout bug.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n  - id: shipping-and-fees\n    label: Shipping cost and delivery dates\n    dropped:\n      check: Did shipping prices, thresholds or delivery promises change this week?\n      yes: Drop-off concentrates on the shipping step, starting the day the change shipped.\n    spiked:\n      check: Did a free-shipping threshold or faster delivery promise go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n  - id: discount-codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    dropped:\n      check: Did a popular code expire, or did a coupon site start listing codes that fail?\n      yes: More sessions enter a code field and leave after an invalid-code message.\n    spiked:\n      check: Is a sale or a leaked code pushing people through?\n      yes: Code usage jumps and order value per order falls.\n  - id: traffic-mix\n    label: Who reached checkout\n    metric: checkout-start-rate\n    breakdown: utm_source\n    dropped:\n      check: Did more low-intent visitors reach checkout, for example from a new campaign?\n      yes: Checkout starts rise from one source whose completion is far below the rest.\n    spiked:\n      check: Did fewer but more committed visitors reach checkout?\n      yes: Checkout starts fall while completion rises; orders barely move.\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did an event, consent banner or tag manager change stop orders being recorded?\n      yes: Orders in the payment processor hold steady while recorded orders fall.\n    spiked:\n      check: Is a duplicate order event or a missing checkout event inflating the rate?\n      yes: Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform.\n\ndiagnose_order: [tracking, payment-failures, device-split, shipping-and-fees, discount-codes, traffic-mix]\n\nrelated: [checkout-start-rate, payment-success-rate, conversion-rate, cart-abandonment-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout is the last step a store controls, so a change here is rarely about demand and\n    almost always about something the team shipped, a partner that broke, or a price the\n    shopper saw late. A one-point drop on a store that starts 10,000 checkouts a week is\n    about 100 lost orders, every week, until someone finds it.\n  pitfalls:\n    - Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.\n    - Mixing checkout attempts and sessions in one ratio. Pick one unit for both sides; this spec uses sessions.\n    - Reading a week-over-week move without the volume. Below about 1,000 checkouts a week, a two-point swing is often chance.\n    - Comparing Black Friday week with the week before. Intent is different; compare with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-conversion","name":"Checkout conversion","aliases":["Checkout completion rate","Checkout conversion rate","Checkout success rate"],"family":"conversion","catalog_id":"checkout_completion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of started checkouts that become a paid order in the same week.","formula":"Paid orders ÷ checkouts started"},"events":[{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"checkouts started a week","typical":0.62},"example":{"business":"store","level":0.63,"volume":20900,"trend":0.02,"season":0.5},"drivers":[{"id":"payment-failures","label":"Payment failures","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did payment success fall, and is it one gateway, card brand or wallet?","yes":"Declines or errors rise for one processor or method while the others hold."},"spiked":{"check":"Did a payment problem from the week before just clear?","yes":"Payment success returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls several points while desktop is flat, which points at a release or layout bug."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}},{"id":"shipping-and-fees","label":"Shipping cost and delivery dates","dropped":{"check":"Did shipping prices, thresholds or delivery promises change this week?","yes":"Drop-off concentrates on the shipping step, starting the day the change shipped."},"spiked":{"check":"Did a free-shipping threshold or faster delivery promise go live?","yes":"Fewer exits at the shipping step from the day it launched."}},{"id":"discount-codes","label":"Discount codes","metric":"promo-code-usage-rate","dropped":{"check":"Did a popular code expire, or did a coupon site start listing codes that fail?","yes":"More sessions enter a code field and leave after an invalid-code message."},"spiked":{"check":"Is a sale or a leaked code pushing people through?","yes":"Code usage jumps and order value per order falls."}},{"id":"traffic-mix","label":"Who reached checkout","metric":"checkout-start-rate","breakdown":"utm_source","dropped":{"check":"Did more low-intent visitors reach checkout, for example from a new campaign?","yes":"Checkout starts rise from one source whose completion is far below the rest."},"spiked":{"check":"Did fewer but more committed visitors reach checkout?","yes":"Checkout starts fall while completion rises; orders barely move."}},{"id":"tracking","label":"Tracking change","dropped":{"check":"Did an event, consent banner or tag manager change stop orders being recorded?","yes":"Orders in the payment processor hold steady while recorded orders fall."},"spiked":{"check":"Is a duplicate order event or a missing checkout event inflating the rate?","yes":"Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform."}}],"diagnose_order":["tracking","payment-failures","device-split","shipping-and-fees","discount-codes","traffic-mix"],"related":["checkout-start-rate","payment-success-rate","conversion-rate","cart-abandonment-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Checkout is the last step a store controls, so a change here is rarely about demand and almost always about something the team shipped, a partner that broke, or a price the shopper saw late. A one-point drop on a store that starts 10,000 checkouts a week is about 100 lost orders, every week, until someone finds it.","pitfalls":["Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.","Mixing checkout attempts and sessions in one ratio. Pick one unit for both sides; this spec uses sessions.","Reading a week-over-week move without the volume. Below about 1,000 checkouts a week, a two-point swing is often chance.","Comparing Black Friday week with the week before. Intent is different; compare with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "checkout-start-rate": { yaml: "id: checkout-start-rate\nname: Checkout start rate\naliases:\n  - Checkout initiation rate\n  - Cart to checkout rate\n  - Reached checkout rate\nfamily: conversion\ncatalog_id: checkout_start_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions with a cart that went on to start checkout, the step where a cart becomes a decision to buy.\n  formula: Sessions that started checkout ÷ sessions that added to cart\n\nevents:\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n\nnumerator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\ndenominator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: carts a week\n  typical: 0.5\n  reference_volumes: [500, 2000, 10000, 40000]\n\nexample:\n  business: store\n  level: 0.52\n  volume: 40000\n  trend: 0.01\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a checkout app, domain or express-pay change stop checkout_started firing for some shoppers?\n      yes: Orders hold while checkout starts fall, often for one wallet or one device.\n    spiked:\n      check: Is checkout_started firing twice, or when the cart drawer opens rather than when checkout loads?\n      yes: Checkout starts rise while orders don't, or starts per session jump on a release day.\n  - id: calendar\n    label: Sale calendar\n    feed: shopping\n    dropped:\n      check: Is it the week before a sale, when shoppers park items in the cart and wait?\n      yes: Carts rise while checkout starts hold, and the same week last year shows the same dip.\n    spiked:\n      check: Is this a sale or holiday week, when parked carts move to checkout?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: cart-intent\n    label: How easily people add to cart\n    metric: add-to-cart-rate\n    dropped:\n      check: Did add-to-cart rate jump from looser intent, such as a quick-add launch or a free gift for adding?\n      yes: Carts rise while checkout starts hold, so the rate falls with no loss of orders.\n    spiked:\n      check: Did add-to-cart rate fall, leaving only the most committed carts?\n      yes: Carts fall while checkout starts hold; check orders before celebrating.\n  - id: cart-costs\n    label: Costs shown in the cart\n    dropped:\n      check: Did the cart start showing shipping costs, a minimum order or a higher free-shipping threshold?\n      yes: The drop starts on the day the cart message changed, on every device.\n    spiked:\n      check: Did a free-shipping offer or a lower threshold go live in the cart?\n      yes: The rise starts on the launch day and orders follow.\n  - id: express-checkout\n    label: Express and wallet buttons\n    dropped:\n      check: Did Shop Pay, Apple Pay or PayPal buttons disappear from the cart or move below the fold?\n      yes: Wallet checkouts fall while card checkouts hold, from the day of a theme or app change.\n    spiked:\n      check: Did express buttons start sending shoppers from product pages straight to checkout?\n      yes: Sessions start checkout without an add-to-cart event, so the rate rises with no change in carts.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, such as a checkout button hidden on small screens?\n      yes: Mobile falls several points while desktop is flat, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, cart-intent, cart-costs, express-checkout, device-split]\n\nrelated: [add-to-cart-rate, checkout-conversion, cart-abandonment-rate, conversion-rate, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout start rate shows whether a cart turns into a decision to buy. It is where surprise\n    costs, a cart that buries its button or a missing wallet show up, well before payment. At\n    Northwind, with about 40,000 carts a week, one point is 400 checkouts and roughly 250 orders.\n  pitfalls:\n    - Express buttons on product pages skip the cart, so those sessions start checkout without an add-to-cart and lift the rate. Track them as an add or read them separately.\n    - Cart drawers make views of the cart page meaningless; this spec uses the add-to-cart and checkout events, never page views of /cart.\n    - Counting checkout starts instead of sessions double counts shoppers who go back to edit the cart and start again. This spec counts sessions on both sides.\n    - A rise in add-to-cart rate often lowers this rate with no harm done. Read the two together and judge them by orders.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-start-rate","name":"Checkout start rate","aliases":["Checkout initiation rate","Cart to checkout rate","Reached checkout rate"],"family":"conversion","catalog_id":"checkout_start_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions with a cart that went on to start checkout, the step where a cart becomes a decision to buy.","formula":"Sessions that started checkout ÷ sessions that added to cart"},"events":[{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."}]},{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]}],"numerator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"denominator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"carts a week","typical":0.5,"reference_volumes":[500,2000,10000,40000]},"example":{"business":"store","level":0.52,"volume":40000,"trend":0.01},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a checkout app, domain or express-pay change stop checkout_started firing for some shoppers?","yes":"Orders hold while checkout starts fall, often for one wallet or one device."},"spiked":{"check":"Is checkout_started firing twice, or when the cart drawer opens rather than when checkout loads?","yes":"Checkout starts rise while orders don't, or starts per session jump on a release day."}},{"id":"calendar","label":"Sale calendar","feed":"shopping","dropped":{"check":"Is it the week before a sale, when shoppers park items in the cart and wait?","yes":"Carts rise while checkout starts hold, and the same week last year shows the same dip."},"spiked":{"check":"Is this a sale or holiday week, when parked carts move to checkout?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"cart-intent","label":"How easily people add to cart","metric":"add-to-cart-rate","dropped":{"check":"Did add-to-cart rate jump from looser intent, such as a quick-add launch or a free gift for adding?","yes":"Carts rise while checkout starts hold, so the rate falls with no loss of orders."},"spiked":{"check":"Did add-to-cart rate fall, leaving only the most committed carts?","yes":"Carts fall while checkout starts hold; check orders before celebrating."}},{"id":"cart-costs","label":"Costs shown in the cart","dropped":{"check":"Did the cart start showing shipping costs, a minimum order or a higher free-shipping threshold?","yes":"The drop starts on the day the cart message changed, on every device."},"spiked":{"check":"Did a free-shipping offer or a lower threshold go live in the cart?","yes":"The rise starts on the launch day and orders follow."}},{"id":"express-checkout","label":"Express and wallet buttons","dropped":{"check":"Did Shop Pay, Apple Pay or PayPal buttons disappear from the cart or move below the fold?","yes":"Wallet checkouts fall while card checkouts hold, from the day of a theme or app change."},"spiked":{"check":"Did express buttons start sending shoppers from product pages straight to checkout?","yes":"Sessions start checkout without an add-to-cart event, so the rate rises with no change in carts."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, such as a checkout button hidden on small screens?","yes":"Mobile falls several points while desktop is flat, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","cart-intent","cart-costs","express-checkout","device-split"],"related":["add-to-cart-rate","checkout-conversion","cart-abandonment-rate","conversion-rate","promo-code-usage-rate"],"prose":{"why_it_matters":"Checkout start rate shows whether a cart turns into a decision to buy. It is where surprise costs, a cart that buries its button or a missing wallet show up, well before payment. At Northwind, with about 40,000 carts a week, one point is 400 checkouts and roughly 250 orders.","pitfalls":["Express buttons on product pages skip the cart, so those sessions start checkout without an add-to-cart and lift the rate. Track them as an add or read them separately.","Cart drawers make views of the cart page meaningless; this spec uses the add-to-cart and checkout events, never page views of /cart.","Counting checkout starts instead of sessions double counts shoppers who go back to edit the cart and start again. This spec counts sessions on both sides.","A rise in add-to-cart rate often lowers this rate with no harm done. Read the two together and judge them by orders."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "contribution-margin": { yaml: "id: contribution-margin\nname: Contribution margin\naliases:\n  - Contribution profit\n  - Contribution after marketing\n  - CM3\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: What is left of the week's net revenue after the cost of the goods sold and the ad spend that sold them.\n  formula: Net revenue − cost of goods − ad spend, by week (subtract fulfilment and payment fees too when you record them)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: The landed cost of the order's items, purchase price plus inbound freight and duties.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: ad_spend\n    description: Spend synced from each ad platform, one row per channel per day.\n    also_called: [ad insights, campaign cost data, cost import]\n    properties:\n      - name: channel\n        description: The platform or channel, such as meta, google or tiktok.\n      - name: spend\n        description: Spend for the day, in the store's currency.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nqueries:\n  hogql: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    SELECT\n      toMonday(timestamp) AS week,\n      sumIf(toFloat(properties.total), event = 'order_completed') - sumIf(toFloat(properties.amount), event = 'order_refunded') AS net_revenue,\n      sumIf(toFloat(properties.cost_of_goods), event = 'order_completed') AS cost_of_goods,\n      sumIf(toFloat(properties.spend), event = 'ad_spend') AS ad_spend,\n      net_revenue - cost_of_goods - ad_spend AS value\n    FROM events\n    WHERE event IN ('order_completed', 'order_refunded', 'ad_spend')\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    -- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH weekly AS (\n      SELECT\n        date_trunc('week', occurred_at)::date AS week,\n        coalesce(sum((properties->>'total')::numeric) FILTER (WHERE event_name = 'order_completed'), 0)\n          - coalesce(sum((properties->>'amount')::numeric) FILTER (WHERE event_name = 'order_refunded'), 0) AS net_revenue,\n        coalesce(sum((properties->>'cost_of_goods')::numeric) FILTER (WHERE event_name = 'order_completed'), 0) AS cost_of_goods,\n        coalesce(sum((properties->>'spend')::numeric) FILTER (WHERE event_name = 'ad_spend'), 0) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY 1\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM weekly\n    ORDER BY week;\n  bigquery: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    -- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH weekly AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.total') AS FLOAT64), NULL)), 0)\n          - COALESCE(SUM(IF(event_name = 'order_refunded', SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64), NULL)), 0) AS net_revenue,\n        COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.cost_of_goods') AS FLOAT64), NULL)), 0) AS cost_of_goods,\n        COALESCE(SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)), 0) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM weekly\n    ORDER BY week;\n  snowflake: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    -- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\n    WITH weekly AS (\n      SELECT\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"total\"::float, NULL)), 0)\n          - COALESCE(SUM(IFF(event_name = 'order_refunded', properties:\"amount\"::float, NULL)), 0) AS net_revenue,\n        COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"cost_of_goods\"::float, NULL)), 0) AS cost_of_goods,\n        COALESCE(SUM(IFF(event_name = 'ad_spend', properties:\"spend\"::float, NULL)), 0) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY 1\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM weekly\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 100000\n\nexample:\n  business: store\n  level: 291000\n  volume: 13300\n  trend: 0.15\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Spend and cost data\n    dropped:\n      check: Did ad spend sync twice for a platform, or did cost_of_goods change basis?\n      yes: One channel's spend doubles with no change in its ads manager, or cost per unit jumps on one date.\n    spiked:\n      check: Did an ad platform's spend sync fail, or did products start selling without a recorded cost?\n      yes: One channel shows no spend for some days, or orders with no cost_of_goods appear. Fix the data before celebrating.\n  - id: ad-spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did ad spend rise faster than the revenue it brought, from a budget increase or a new campaign?\n      yes: Spend rises while net revenue rises less, so each extra dollar of spend returns less than a dollar of margin.\n    spiked:\n      check: Did spend fall, from a budget cut, a paused campaign or an ad account problem?\n      yes: Spend falls while revenue holds this week; watch whether new customers fall in the weeks after.\n  - id: net-revenue\n    label: Net revenue\n    metric: net-revenue\n    feed: shopping\n    dropped:\n      check: Did net revenue fall, from fewer orders, smaller orders or more refunds?\n      yes: Net revenue falls while spend and margin hold.\n    spiked:\n      check: Is this a sale or holiday week, or did revenue rise for a reason that will last?\n      yes: Net revenue rises while spend holds; the same week last year shows whether it's the calendar.\n  - id: gross-margin\n    label: Gross margin\n    metric: gross-margin\n    dropped:\n      check: Did discounts, product mix or unit costs lower gross margin?\n      yes: Gross margin falls while revenue and spend hold.\n    spiked:\n      check: Did a sale end or a price rise lift gross margin?\n      yes: Gross margin rises while revenue and spend hold.\n  - id: efficiency\n    label: Marketing efficiency\n    metric: mer\n    dropped:\n      check: Did each ad dollar bring in less revenue, from rising CPMs or tired creative?\n      yes: MER falls while spend holds.\n    spiked:\n      check: Did each ad dollar bring in more revenue, or did a sale lift revenue on the same spend?\n      yes: MER rises while spend holds; check the calendar before crediting the ads.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds jump, after a big sale, a bad batch or a delivery problem?\n      yes: Refund rate rises while gross sales and spend hold.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refund rate returns to its usual level and margin recovers with it.\n\ndiagnose_order: [tracking, ad-spend, net-revenue, gross-margin, efficiency, refunds]\n\nrelated: [net-revenue, gross-margin, ad-spend, mer, refund-rate, ncac]\n\nprose:\n  why_it_matters: >-\n    Revenue can grow while the business earns less; contribution margin is the check. It takes\n    away what the goods cost and what the ads that sold them cost, leaving the money that pays\n    for salaries, rent and profit. At Northwind about $1.29M of net revenue leaves roughly\n    $345,000 after $560,000 of goods and $380,000 of ads, so a 10% rise in ad spend with flat\n    revenue cuts it by 11%.\n  pitfalls:\n    - Shipping labels, packaging, fulfilment and payment fees are variable costs too, often 10–15% of revenue. Leaving them out overstates contribution margin; add them as a per-order estimate if you don't record them.\n    - Ad spend is booked on the day it's spent, but the orders it drives can land days later, so a launch week reads low and the next week high. Use two-week sums when spend moves a lot.\n    - When one platform's spend sync fails, contribution margin jumps by that platform's spend. Check every channel reported spend before celebrating.\n    - Some teams stop before marketing and call that contribution margin. This spec takes ad spend out because that is the number that says whether growth pays.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"contribution-margin","name":"Contribution margin","aliases":["Contribution profit","Contribution after marketing","CM3"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"What is left of the week's net revenue after the cost of the goods sold and the ad spend that sold them.","formula":"Net revenue − cost of goods − ad spend, by week (subtract fulfilment and payment fees too when you record them)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"The landed cost of the order's items, purchase price plus inbound freight and duties."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"ad_spend","description":"Spend synced from each ad platform, one row per channel per day.","also_called":["ad insights","campaign cost data","cost import"],"properties":[{"name":"channel","description":"The platform or channel, such as meta, google or tiktok."},{"name":"spend","description":"Spend for the day, in the store's currency."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"queries":{"hogql":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\nSELECT\n  toMonday(timestamp) AS week,\n  sumIf(toFloat(properties.total), event = 'order_completed') - sumIf(toFloat(properties.amount), event = 'order_refunded') AS net_revenue,\n  sumIf(toFloat(properties.cost_of_goods), event = 'order_completed') AS cost_of_goods,\n  sumIf(toFloat(properties.spend), event = 'ad_spend') AS ad_spend,\n  net_revenue - cost_of_goods - ad_spend AS value\nFROM events\nWHERE event IN ('order_completed', 'order_refunded', 'ad_spend')\n  AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n  AND timestamp < toStartOfWeek(now(), 1)\nGROUP BY week\nORDER BY week","postgres":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n-- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH weekly AS (\n  SELECT\n    date_trunc('week', occurred_at)::date AS week,\n    coalesce(sum((properties->>'total')::numeric) FILTER (WHERE event_name = 'order_completed'), 0)\n      - coalesce(sum((properties->>'amount')::numeric) FILTER (WHERE event_name = 'order_refunded'), 0) AS net_revenue,\n    coalesce(sum((properties->>'cost_of_goods')::numeric) FILTER (WHERE event_name = 'order_completed'), 0) AS cost_of_goods,\n    coalesce(sum((properties->>'spend')::numeric) FILTER (WHERE event_name = 'ad_spend'), 0) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY 1\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM weekly\nORDER BY week;","bigquery":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n-- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH weekly AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.total') AS FLOAT64), NULL)), 0)\n      - COALESCE(SUM(IF(event_name = 'order_refunded', SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64), NULL)), 0) AS net_revenue,\n    COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.cost_of_goods') AS FLOAT64), NULL)), 0) AS cost_of_goods,\n    COALESCE(SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)), 0) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM weekly\nORDER BY week;","snowflake":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n-- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\nWITH weekly AS (\n  SELECT\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"total\"::float, NULL)), 0)\n      - COALESCE(SUM(IFF(event_name = 'order_refunded', properties:\"amount\"::float, NULL)), 0) AS net_revenue,\n    COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"cost_of_goods\"::float, NULL)), 0) AS cost_of_goods,\n    COALESCE(SUM(IFF(event_name = 'ad_spend', properties:\"spend\"::float, NULL)), 0) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY 1\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM weekly\nORDER BY week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":100000},"example":{"business":"store","level":291000,"volume":13300,"trend":0.15,"season":1},"drivers":[{"id":"tracking","label":"Spend and cost data","dropped":{"check":"Did ad spend sync twice for a platform, or did cost_of_goods change basis?","yes":"One channel's spend doubles with no change in its ads manager, or cost per unit jumps on one date."},"spiked":{"check":"Did an ad platform's spend sync fail, or did products start selling without a recorded cost?","yes":"One channel shows no spend for some days, or orders with no cost_of_goods appear. Fix the data before celebrating."}},{"id":"ad-spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did ad spend rise faster than the revenue it brought, from a budget increase or a new campaign?","yes":"Spend rises while net revenue rises less, so each extra dollar of spend returns less than a dollar of margin."},"spiked":{"check":"Did spend fall, from a budget cut, a paused campaign or an ad account problem?","yes":"Spend falls while revenue holds this week; watch whether new customers fall in the weeks after."}},{"id":"net-revenue","label":"Net revenue","metric":"net-revenue","feed":"shopping","dropped":{"check":"Did net revenue fall, from fewer orders, smaller orders or more refunds?","yes":"Net revenue falls while spend and margin hold."},"spiked":{"check":"Is this a sale or holiday week, or did revenue rise for a reason that will last?","yes":"Net revenue rises while spend holds; the same week last year shows whether it's the calendar."}},{"id":"gross-margin","label":"Gross margin","metric":"gross-margin","dropped":{"check":"Did discounts, product mix or unit costs lower gross margin?","yes":"Gross margin falls while revenue and spend hold."},"spiked":{"check":"Did a sale end or a price rise lift gross margin?","yes":"Gross margin rises while revenue and spend hold."}},{"id":"efficiency","label":"Marketing efficiency","metric":"mer","dropped":{"check":"Did each ad dollar bring in less revenue, from rising CPMs or tired creative?","yes":"MER falls while spend holds."},"spiked":{"check":"Did each ad dollar bring in more revenue, or did a sale lift revenue on the same spend?","yes":"MER rises while spend holds; check the calendar before crediting the ads."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds jump, after a big sale, a bad batch or a delivery problem?","yes":"Refund rate rises while gross sales and spend hold."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refund rate returns to its usual level and margin recovers with it."}}],"diagnose_order":["tracking","ad-spend","net-revenue","gross-margin","efficiency","refunds"],"related":["net-revenue","gross-margin","ad-spend","mer","refund-rate","ncac"],"prose":{"why_it_matters":"Revenue can grow while the business earns less; contribution margin is the check. It takes away what the goods cost and what the ads that sold them cost, leaving the money that pays for salaries, rent and profit. At Northwind about $1.29M of net revenue leaves roughly $345,000 after $560,000 of goods and $380,000 of ads, so a 10% rise in ad spend with flat revenue cuts it by 11%.","pitfalls":["Shipping labels, packaging, fulfilment and payment fees are variable costs too, often 10–15% of revenue. Leaving them out overstates contribution margin; add them as a per-order estimate if you don't record them.","Ad spend is booked on the day it's spent, but the orders it drives can land days later, so a launch week reads low and the next week high. Use two-week sums when spend moves a lot.","When one platform's spend sync fails, contribution margin jumps by that platform's spend. Check every channel reported spend before celebrating.","Some teams stop before marketing and call that contribution margin. This spec takes ad spend out because that is the number that says whether growth pays."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "conversion-rate": { yaml: "id: conversion-rate\nname: Conversion rate\naliases:\n  - Ecommerce conversion rate\n  - Store conversion rate\n  - Online store conversion rate\n  - Session conversion rate\n  - Purchase conversion rate\nfamily: conversion\ncatalog_id: conversion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that end in a paid order, the whole store funnel in one number.\n  formula: Sessions with a paid order ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: $session_id\n        description: The session the order was placed in, passed from the browser to the server.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: sessions a week\n  typical: 0.02\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.0206\n  volume: 600000\n  trend: 0.01\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a consent banner, tag manager or checkout change stop orders, or their session ids, being recorded?\n      yes: Orders in the store platform or payment processor hold while orders recorded in analytics fall.\n    spiked:\n      check: Did page views stop being recorded somewhere, shrinking sessions while orders kept recording?\n      yes: Sessions fall with no matching fall in ad clicks or server logs, often on one browser or after a consent change.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week, or is this the week before one when shoppers wait?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week? Compare with the same week last year before crediting the site.\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: traffic-mix\n    label: Who arrived\n    breakdown: utm_source\n    feed: cloudflare\n    dropped:\n      check: Did sessions grow from a low-intent source or from bots, such as broad paid social, a viral post or a crawler?\n      yes: Sessions jump from one source whose conversion is a fraction of the rest, while orders barely move.\n    spiked:\n      check: Did a low-intent source or a bot wave shrink, lifting the rate without more orders?\n      yes: Sessions fall while orders hold. Check orders before celebrating.\n  - id: add-to-cart\n    label: Product pages and carts\n    metric: add-to-cart-rate\n    dropped:\n      check: Did fewer product viewers add to cart, from price, stock or a product page change?\n      yes: Add-to-cart rate falls by about as much as conversion while checkout steps hold.\n    spiked:\n      check: Did more product viewers add to cart, from a sale, a restock or a page change?\n      yes: Add-to-cart rate rises and checkout starts follow it.\n  - id: checkout\n    label: Checkout and payment\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did more started checkouts fail, at shipping, payment or account creation?\n      yes: Checkout conversion falls while add-to-cart holds; one step or one payment method explains most of it.\n    spiked:\n      check: Did a checkout or payment problem from the week before clear?\n      yes: Checkout conversion returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls while desktop is flat, which points at a release, a layout bug or a browser update.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, traffic-mix, add-to-cart, checkout, device-split]\n\nrelated: [sessions, add-to-cart-rate, checkout-conversion, mobile-conversion-rate, revenue-per-session, product-view-rate]\n\nprose:\n  why_it_matters: >-\n    Conversion rate turns traffic into orders, so almost every change to the store shows up in\n    it eventually. At 600,000 sessions a week, a tenth of a point is 600 orders, about $60,000 a\n    week at a $100 order. It moves with who arrives as much as with the store, so read it\n    beside the traffic mix before crediting or blaming the site.\n  pitfalls:\n    - Orders sent from the server often carry no session id and fall out of the numerator. Pass the browser's session id onto the order event or conversion reads low.\n    - Orders ÷ sessions and sessions with an order ÷ sessions differ when shoppers place two orders in one visit. This spec counts sessions, like Shopify's online store conversion rate.\n    - A new low-intent channel lowers conversion while adding orders. Never judge a move without orders and sessions beside it.\n    - Channel splits need the session's landing source on every event, including the order; otherwise orders land in an unattributed bucket and every channel looks worse.\n    - Comparing Black Friday week with the week before mixes intent. Compare with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"conversion-rate","name":"Conversion rate","aliases":["Ecommerce conversion rate","Store conversion rate","Online store conversion rate","Session conversion rate","Purchase conversion rate"],"family":"conversion","catalog_id":"conversion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that end in a paid order, the whole store funnel in one number.","formula":"Sessions with a paid order ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"$session_id","description":"The session the order was placed in, passed from the browser to the server."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"sessions a week","typical":0.02,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.0206,"volume":600000,"trend":0.01,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a consent banner, tag manager or checkout change stop orders, or their session ids, being recorded?","yes":"Orders in the store platform or payment processor hold while orders recorded in analytics fall."},"spiked":{"check":"Did page views stop being recorded somewhere, shrinking sessions while orders kept recording?","yes":"Sessions fall with no matching fall in ad clicks or server logs, often on one browser or after a consent change."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week, or is this the week before one when shoppers wait?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week? Compare with the same week last year before crediting the site.","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"traffic-mix","label":"Who arrived","breakdown":"utm_source","feed":"cloudflare","dropped":{"check":"Did sessions grow from a low-intent source or from bots, such as broad paid social, a viral post or a crawler?","yes":"Sessions jump from one source whose conversion is a fraction of the rest, while orders barely move."},"spiked":{"check":"Did a low-intent source or a bot wave shrink, lifting the rate without more orders?","yes":"Sessions fall while orders hold. Check orders before celebrating."}},{"id":"add-to-cart","label":"Product pages and carts","metric":"add-to-cart-rate","dropped":{"check":"Did fewer product viewers add to cart, from price, stock or a product page change?","yes":"Add-to-cart rate falls by about as much as conversion while checkout steps hold."},"spiked":{"check":"Did more product viewers add to cart, from a sale, a restock or a page change?","yes":"Add-to-cart rate rises and checkout starts follow it."}},{"id":"checkout","label":"Checkout and payment","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did more started checkouts fail, at shipping, payment or account creation?","yes":"Checkout conversion falls while add-to-cart holds; one step or one payment method explains most of it."},"spiked":{"check":"Did a checkout or payment problem from the week before clear?","yes":"Checkout conversion returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls while desktop is flat, which points at a release, a layout bug or a browser update."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","traffic-mix","add-to-cart","checkout","device-split"],"related":["sessions","add-to-cart-rate","checkout-conversion","mobile-conversion-rate","revenue-per-session","product-view-rate"],"prose":{"why_it_matters":"Conversion rate turns traffic into orders, so almost every change to the store shows up in it eventually. At 600,000 sessions a week, a tenth of a point is 600 orders, about $60,000 a week at a $100 order. It moves with who arrives as much as with the store, so read it beside the traffic mix before crediting or blaming the site.","pitfalls":["Orders sent from the server often carry no session id and fall out of the numerator. Pass the browser's session id onto the order event or conversion reads low.","Orders ÷ sessions and sessions with an order ÷ sessions differ when shoppers place two orders in one visit. This spec counts sessions, like Shopify's online store conversion rate.","A new low-intent channel lowers conversion while adding orders. Never judge a move without orders and sessions beside it.","Channel splits need the session's landing source on every event, including the order; otherwise orders land in an unattributed bucket and every channel looks worse.","Comparing Black Friday week with the week before mixes intent. Compare with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cpc": { yaml: "id: cpc\nname: Cost per click\naliases:\n  - Average CPC\n  - Avg CPC\n  - Cost per link click\nfamily: acquisition\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: What the store paid, on average, for one ad click in the week, across every synced ad platform.\n  formula: Ad spend ÷ ad clicks\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n      - name: clicks\n        description: Link clicks that day. Use link clicks, not all clicks, where the platform offers both.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n      - name: campaign\n        description: The campaign name or id on that platform.\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: Ad clicks\n  aggregate: sum\n  event: ad_spend\n  property: clicks\n\nnoise:\n  type: process\n  min_denominator: 200\n  volume_unit: ad clicks a week\n  typical: 1.1\n\nexample:\n  business: store\n  level: 1.25\n  volume: 240000\n  trend: 0.06\n\ndrivers:\n  - id: sync\n    label: Click and spend sync\n    breakdown: channel\n    dropped:\n      check: Is a channel syncing all clicks instead of link clicks, or clicks without their spend?\n      yes: One channel's clicks jump while the sessions it sends hold, or its spend is missing for some days.\n    spiked:\n      check: Is a channel syncing spend without its clicks, or did it switch to link clicks only?\n      yes: One channel's clicks fall to near zero or change definition while its spend holds.\n  - id: cpm\n    label: Price of impressions\n    metric: cpm\n    feed: shopping\n    dropped:\n      check: Did impressions get cheaper across platforms?\n      yes: CPM falls by about as much as CPC, and click-through rate holds.\n    spiked:\n      check: Did impressions get more expensive, as they do in Q4 and around Black Friday?\n      yes: CPM rises by about as much as CPC, and click-through rate holds.\n  - id: ctr\n    label: Click-through rate\n    metric: ctr\n    dropped:\n      check: Did more people click each ad, from new creative or a stronger offer?\n      yes: Click-through rate rises by about as much as CPC falls, at a steady CPM.\n    spiked:\n      check: Did fewer people click, from tired creative or a weaker offer?\n      yes: Click-through rate falls by about as much as CPC rises, at a steady CPM.\n  - id: channel-mix\n    label: Channel mix\n    metric: ad-spend\n    breakdown: channel\n    dropped:\n      check: Did budget move toward cheap-click channels such as broad social or display?\n      yes: Each channel's CPC holds but the cheaper channels took a bigger share of spend.\n    spiked:\n      check: Did budget move toward expensive-click channels such as non-brand search or LinkedIn?\n      yes: Each channel's CPC holds but the expensive channels took a bigger share of spend.\n  - id: bidding\n    label: Bidding and competition\n    feed: ad-platforms\n    dropped:\n      check: Did a competitor leave the auction, or a bid cap or target start holding prices down?\n      yes: CPC falls on search campaigns while impression share holds or rises.\n    spiked:\n      check: Did a bid strategy change, a new competitor arrive, or a platform raise its floor prices?\n      yes: CPC rises on the campaigns that changed strategy, or on search terms where a new competitor appears.\n\ndiagnose_order: [sync, cpm, ctr, channel-mix, bidding]\n\nrelated: [cpm, ctr, ad-spend, paid-sessions, paid-conversion-rate]\n\nprose:\n  why_it_matters: >-\n    CPC is what a visitor from an ad costs before they do anything, and it splits into two\n    numbers that move for different reasons: CPC = CPM ÷ (CTR × 1,000). A $1.25 click\n    converting at 2% means $62.50 of media per order, so a 20% rise in CPC adds $12.50 to every\n    paid order unless conversion rises with it.\n  pitfalls:\n    - Clicks are not visits. Platform clicks run 10 to 25% above sessions recorded on the site, so cost per paid session is always higher than CPC.\n    - A blended CPC moves with the budget mix. Non-brand search can cost ten times a social click; split by channel before reading a change.\n    - A cheap click that never converts is expensive. Read CPC with paid conversion rate, never alone.\n    - Meta's \"cost per click (all)\" divides by every click, including likes and profile taps. Use cost per link click to match this spec.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cpc","name":"Cost per click","aliases":["Average CPC","Avg CPC","Cost per link click"],"family":"acquisition","kind":"currency","polarity":"down-is-good","definition":{"one_line":"What the store paid, on average, for one ad click in the week, across every synced ad platform.","formula":"Ad spend ÷ ad clicks"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."},{"name":"clicks","description":"Link clicks that day. Use link clicks, not all clicks, where the platform offers both."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."},{"name":"campaign","description":"The campaign name or id on that platform."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"Ad clicks","aggregate":"sum","event":"ad_spend","property":"clicks"},"noise":{"type":"process","min_denominator":200,"volume_unit":"ad clicks a week","typical":1.1},"example":{"business":"store","level":1.25,"volume":240000,"trend":0.06},"drivers":[{"id":"sync","label":"Click and spend sync","breakdown":"channel","dropped":{"check":"Is a channel syncing all clicks instead of link clicks, or clicks without their spend?","yes":"One channel's clicks jump while the sessions it sends hold, or its spend is missing for some days."},"spiked":{"check":"Is a channel syncing spend without its clicks, or did it switch to link clicks only?","yes":"One channel's clicks fall to near zero or change definition while its spend holds."}},{"id":"cpm","label":"Price of impressions","metric":"cpm","feed":"shopping","dropped":{"check":"Did impressions get cheaper across platforms?","yes":"CPM falls by about as much as CPC, and click-through rate holds."},"spiked":{"check":"Did impressions get more expensive, as they do in Q4 and around Black Friday?","yes":"CPM rises by about as much as CPC, and click-through rate holds."}},{"id":"ctr","label":"Click-through rate","metric":"ctr","dropped":{"check":"Did more people click each ad, from new creative or a stronger offer?","yes":"Click-through rate rises by about as much as CPC falls, at a steady CPM."},"spiked":{"check":"Did fewer people click, from tired creative or a weaker offer?","yes":"Click-through rate falls by about as much as CPC rises, at a steady CPM."}},{"id":"channel-mix","label":"Channel mix","metric":"ad-spend","breakdown":"channel","dropped":{"check":"Did budget move toward cheap-click channels such as broad social or display?","yes":"Each channel's CPC holds but the cheaper channels took a bigger share of spend."},"spiked":{"check":"Did budget move toward expensive-click channels such as non-brand search or LinkedIn?","yes":"Each channel's CPC holds but the expensive channels took a bigger share of spend."}},{"id":"bidding","label":"Bidding and competition","feed":"ad-platforms","dropped":{"check":"Did a competitor leave the auction, or a bid cap or target start holding prices down?","yes":"CPC falls on search campaigns while impression share holds or rises."},"spiked":{"check":"Did a bid strategy change, a new competitor arrive, or a platform raise its floor prices?","yes":"CPC rises on the campaigns that changed strategy, or on search terms where a new competitor appears."}}],"diagnose_order":["sync","cpm","ctr","channel-mix","bidding"],"related":["cpm","ctr","ad-spend","paid-sessions","paid-conversion-rate"],"prose":{"why_it_matters":"CPC is what a visitor from an ad costs before they do anything, and it splits into two numbers that move for different reasons: CPC = CPM ÷ (CTR × 1,000). A $1.25 click converting at 2% means $62.50 of media per order, so a 20% rise in CPC adds $12.50 to every paid order unless conversion rises with it.","pitfalls":["Clicks are not visits. Platform clicks run 10 to 25% above sessions recorded on the site, so cost per paid session is always higher than CPC.","A blended CPC moves with the budget mix. Non-brand search can cost ten times a social click; split by channel before reading a change.","A cheap click that never converts is expensive. Read CPC with paid conversion rate, never alone.","Meta's \"cost per click (all)\" divides by every click, including likes and profile taps. Use cost per link click to match this spec."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cpm": { yaml: "id: cpm\nname: Cost per thousand impressions\naliases:\n  - Cost per mille\n  - Cost per thousand\n  - Cost per 1000 impressions\nfamily: acquisition\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: What the ad platforms charged, on average, to show the ads a thousand times in the week.\n  formula: Ad spend ÷ impressions × 1,000\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n      - name: impressions\n        description: Ads shown that day, as the platform counts them.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: Impressions\n  aggregate: sum\n  event: ad_spend\n  property: impressions\n\nqueries:\n  hogql: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\n    SELECT week, numerator, denominator, if(denominator > 0, numerator / denominator * 1000, NULL) AS value\n    FROM (\n      SELECT\n        toMonday(timestamp) AS week,\n        sum(toFloat(properties.spend)) AS numerator,\n        sum(toFloat(properties.impressions)) AS denominator\n      FROM events\n      WHERE event = 'ad_spend'\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY week\n    )\n    ORDER BY week\n  postgres: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\n    SELECT\n      date_trunc('week', occurred_at)::date AS week,\n      sum((properties->>'spend')::numeric) AS numerator,\n      sum((properties->>'impressions')::numeric) AS denominator,\n      sum((properties->>'spend')::numeric) / nullif(sum((properties->>'impressions')::numeric), 0) * 1000 AS value\n    FROM events\n    WHERE event_name = 'ad_spend'\n      AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n      AND occurred_at < date_trunc('week', now())\n    GROUP BY 1\n    ORDER BY 1;\n  bigquery: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\n    SELECT\n      DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n      SUM(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS numerator,\n      SUM(CAST(JSON_VALUE(properties, '$.impressions') AS FLOAT64)) AS denominator,\n      SAFE_DIVIDE(SUM(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)), SUM(CAST(JSON_VALUE(properties, '$.impressions') AS FLOAT64))) * 1000 AS value\n    FROM events\n    WHERE event_name = 'ad_spend'\n      AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n      AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\n    -- Assumes WEEK_START = 1 (Monday).\n    SELECT\n      DATE_TRUNC('week', occurred_at)::date AS week,\n      SUM(properties:\"spend\"::float) AS numerator,\n      SUM(properties:\"impressions\"::float) AS denominator,\n      DIV0NULL(SUM(properties:\"spend\"::float), SUM(properties:\"impressions\"::float)) * 1000 AS value\n    FROM events\n    WHERE event_name = 'ad_spend'\n      AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n      AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n    GROUP BY 1\n    ORDER BY 1;\n\nnoise:\n  type: process\n  min_denominator: 10000\n  volume_unit: impressions a week\n  typical: 12\n\nexample:\n  business: store\n  level: 14.5\n  volume: 21000000\n  trend: 0.08\n\ndrivers:\n  - id: sync\n    label: Impression and spend sync\n    dropped:\n      check: Is a channel syncing impressions without its spend, or spend that was missing last week?\n      yes: One channel's impressions and spend no longer move together for some days.\n    spiked:\n      check: Is a channel syncing spend without its impressions, or did a platform change how it counts an impression?\n      yes: One channel's impressions fall to near zero or change definition while its spend holds.\n  - id: auction-season\n    label: Auction season\n    feed: shopping\n    dropped:\n      check: Did a high-demand period end, such as the last weeks of Q4?\n      yes: CPMs fall across every platform in the first weeks of January or after a peak.\n    spiked:\n      check: Is this a week when every advertiser bids up, such as Black Friday, Cyber Monday or the run-up to Christmas?\n      yes: CPMs rise across every platform at once; the same weeks last year show the same rise.\n  - id: platform-changes\n    label: Platform changes\n    feed: ad-platforms\n    dropped:\n      check: Did a platform release new inventory or change its auction?\n      yes: CPM falls on one platform only, from a dated change.\n    spiked:\n      check: Did a platform outage, policy change or measurement change limit cheap inventory?\n      yes: CPM rises on one platform only, from a dated change.\n  - id: channel-mix\n    label: Channel and placement mix\n    metric: ad-spend\n    dropped:\n      check: Did budget shift toward cheap inventory such as display, Audience Network or broad video?\n      yes: Each channel's CPM holds but the share of spend on the cheapest placements grew.\n    spiked:\n      check: Did budget shift toward expensive inventory such as search, LinkedIn or retargeting?\n      yes: Each channel's CPM holds but the share of spend on the most expensive placements grew.\n  - id: targeting-and-creative\n    label: Audience and creative\n    dropped:\n      check: Did a broader audience or a fresh creative with strong engagement lower the price per impression?\n      yes: CPM falls on the campaigns that changed, often with higher click-through.\n    spiked:\n      check: Did audiences narrow, frequency climb, or a tired creative lose its quality ranking?\n      yes: CPM rises on campaigns whose frequency is above 3 or whose ads ran unchanged for weeks.\n\ndiagnose_order: [sync, auction-season, platform-changes, channel-mix, targeting-and-creative]\n\nrelated: [ad-spend, ctr, cpc, ncac, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    CPM is the price of attention, set by an auction the store doesn't control. It explains\n    most of the week-to-week swing in acquisition cost: a store paying $14.50 per thousand\n    impressions in October can pay $25 or more in Black Friday week for the same audience, and\n    every metric downstream gets more expensive with it.\n  pitfalls:\n    - A blended CPM across platforms moves with the budget mix. Search, LinkedIn and retargeting cost several times what broad social and display do; split by channel before reading a change.\n    - Platforms count impressions differently. Meta counts an ad that enters the screen and Google counts a served ad, so CPMs across platforms don't compare directly.\n    - A falling CPM is not always good news. Cheap placements such as in-app display and Audience Network buy impressions few people notice; read CPM with click-through rate.\n    - Ad-platform days follow the ad account's time zone. Summed into UTC weeks, a little spend and a few impressions land in the neighbouring week.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cpm","name":"Cost per thousand impressions","aliases":["Cost per mille","Cost per thousand","Cost per 1000 impressions"],"family":"acquisition","kind":"currency","polarity":"down-is-good","definition":{"one_line":"What the ad platforms charged, on average, to show the ads a thousand times in the week.","formula":"Ad spend ÷ impressions × 1,000"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."},{"name":"impressions","description":"Ads shown that day, as the platform counts them."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"Impressions","aggregate":"sum","event":"ad_spend","property":"impressions"},"queries":{"hogql":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\nSELECT week, numerator, denominator, if(denominator > 0, numerator / denominator * 1000, NULL) AS value\nFROM (\n  SELECT\n    toMonday(timestamp) AS week,\n    sum(toFloat(properties.spend)) AS numerator,\n    sum(toFloat(properties.impressions)) AS denominator\n  FROM events\n  WHERE event = 'ad_spend'\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY week\n)\nORDER BY week","postgres":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\nSELECT\n  date_trunc('week', occurred_at)::date AS week,\n  sum((properties->>'spend')::numeric) AS numerator,\n  sum((properties->>'impressions')::numeric) AS denominator,\n  sum((properties->>'spend')::numeric) / nullif(sum((properties->>'impressions')::numeric), 0) * 1000 AS value\nFROM events\nWHERE event_name = 'ad_spend'\n  AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n  AND occurred_at < date_trunc('week', now())\nGROUP BY 1\nORDER BY 1;","bigquery":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\nSELECT\n  DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n  SUM(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS numerator,\n  SUM(CAST(JSON_VALUE(properties, '$.impressions') AS FLOAT64)) AS denominator,\n  SAFE_DIVIDE(SUM(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)), SUM(CAST(JSON_VALUE(properties, '$.impressions') AS FLOAT64))) * 1000 AS value\nFROM events\nWHERE event_name = 'ad_spend'\n  AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n  AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\nGROUP BY week\nORDER BY week;","snowflake":"-- CPM per week: ad spend ÷ impressions × 1,000, across every synced ad channel.\n-- Assumes WEEK_START = 1 (Monday).\nSELECT\n  DATE_TRUNC('week', occurred_at)::date AS week,\n  SUM(properties:\"spend\"::float) AS numerator,\n  SUM(properties:\"impressions\"::float) AS denominator,\n  DIV0NULL(SUM(properties:\"spend\"::float), SUM(properties:\"impressions\"::float)) * 1000 AS value\nFROM events\nWHERE event_name = 'ad_spend'\n  AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n  AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\nGROUP BY 1\nORDER BY 1;"},"noise":{"type":"process","min_denominator":10000,"volume_unit":"impressions a week","typical":12},"example":{"business":"store","level":14.5,"volume":21000000,"trend":0.08},"drivers":[{"id":"sync","label":"Impression and spend sync","dropped":{"check":"Is a channel syncing impressions without its spend, or spend that was missing last week?","yes":"One channel's impressions and spend no longer move together for some days."},"spiked":{"check":"Is a channel syncing spend without its impressions, or did a platform change how it counts an impression?","yes":"One channel's impressions fall to near zero or change definition while its spend holds."}},{"id":"auction-season","label":"Auction season","feed":"shopping","dropped":{"check":"Did a high-demand period end, such as the last weeks of Q4?","yes":"CPMs fall across every platform in the first weeks of January or after a peak."},"spiked":{"check":"Is this a week when every advertiser bids up, such as Black Friday, Cyber Monday or the run-up to Christmas?","yes":"CPMs rise across every platform at once; the same weeks last year show the same rise."}},{"id":"platform-changes","label":"Platform changes","feed":"ad-platforms","dropped":{"check":"Did a platform release new inventory or change its auction?","yes":"CPM falls on one platform only, from a dated change."},"spiked":{"check":"Did a platform outage, policy change or measurement change limit cheap inventory?","yes":"CPM rises on one platform only, from a dated change."}},{"id":"channel-mix","label":"Channel and placement mix","metric":"ad-spend","dropped":{"check":"Did budget shift toward cheap inventory such as display, Audience Network or broad video?","yes":"Each channel's CPM holds but the share of spend on the cheapest placements grew."},"spiked":{"check":"Did budget shift toward expensive inventory such as search, LinkedIn or retargeting?","yes":"Each channel's CPM holds but the share of spend on the most expensive placements grew."}},{"id":"targeting-and-creative","label":"Audience and creative","dropped":{"check":"Did a broader audience or a fresh creative with strong engagement lower the price per impression?","yes":"CPM falls on the campaigns that changed, often with higher click-through."},"spiked":{"check":"Did audiences narrow, frequency climb, or a tired creative lose its quality ranking?","yes":"CPM rises on campaigns whose frequency is above 3 or whose ads ran unchanged for weeks."}}],"diagnose_order":["sync","auction-season","platform-changes","channel-mix","targeting-and-creative"],"related":["ad-spend","ctr","cpc","ncac","paid-sessions"],"prose":{"why_it_matters":"CPM is the price of attention, set by an auction the store doesn't control. It explains most of the week-to-week swing in acquisition cost: a store paying $14.50 per thousand impressions in October can pay $25 or more in Black Friday week for the same audience, and every metric downstream gets more expensive with it.","pitfalls":["A blended CPM across platforms moves with the budget mix. Search, LinkedIn and retargeting cost several times what broad social and display do; split by channel before reading a change.","Platforms count impressions differently. Meta counts an ad that enters the screen and Google counts a served ad, so CPMs across platforms don't compare directly.","A falling CPM is not always good news. Cheap placements such as in-app display and Audience Network buy impressions few people notice; read CPM with click-through rate.","Ad-platform days follow the ad account's time zone. Summed into UTC weeks, a little spend and a few impressions land in the neighbouring week."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "ctr": { yaml: "id: ctr\nname: Click-through rate\naliases:\n  - Ad click-through rate\n  - Ad CTR\n  - Clickthrough rate\n  - Link click-through rate\nfamily: acquisition\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of ad impressions in the week that led to a click, across every synced ad platform.\n  formula: Ad clicks ÷ ad impressions\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: clicks\n        description: Link clicks that day. Use link clicks, not all clicks, where the platform offers both.\n      - name: impressions\n        description: Ads shown that day, as the platform counts them.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n      - name: campaign\n        description: The campaign name or id on that platform.\n\nnumerator:\n  label: Ad clicks\n  aggregate: sum\n  event: ad_spend\n  property: clicks\ndenominator:\n  label: Impressions\n  aggregate: sum\n  event: ad_spend\n  property: impressions\n\nnoise:\n  type: binomial\n  min_denominator: 10000\n  volume_unit: impressions a week\n  typical: 0.011\n  reference_volumes: [10000, 100000, 1000000, 10000000]\n\nexample:\n  business: store\n  level: 0.0115\n  volume: 21000000\n  trend: -0.05\n\ndrivers:\n  - id: sync\n    label: Click and impression sync\n    breakdown: channel\n    dropped:\n      check: Did a sync miss clicks for some days, or switch one channel from all clicks to link clicks?\n      yes: One channel's clicks fall sharply from one day while its spend and the sessions it sends hold.\n    spiked:\n      check: Is a channel syncing all clicks (likes, profile taps, expands) instead of link clicks, or missing impressions?\n      yes: One channel's CTR jumps several times over while the sessions it sends barely move.\n  - id: channel-mix\n    label: Channel and placement mix\n    breakdown: channel\n    dropped:\n      check: Did budget shift toward low-CTR inventory such as display, video or Audience Network?\n      yes: Each channel's CTR holds but low-CTR placements took a bigger share of impressions.\n    spiked:\n      check: Did budget shift toward high-CTR inventory such as branded search or retargeting?\n      yes: Each channel's CTR holds but high-CTR placements took a bigger share of impressions.\n  - id: creative-fatigue\n    label: Creative fatigue\n    breakdown: campaign\n    dropped:\n      check: Have the same ads run for weeks to the same people?\n      yes: CTR falls steadily on long-running campaigns as frequency climbs past 3.\n    spiked:\n      check: Did new creative, a new offer or a new hook go live?\n      yes: CTR rises on the campaigns that changed from the day they launched.\n  - id: calendar\n    label: Calendar and offers\n    feed: shopping\n    dropped:\n      check: Did a sale end, so ads lost the offer people were clicking for?\n      yes: The same weeks last year show the same fall after the sale.\n    spiked:\n      check: Is a sale, holiday or launch giving people a reason to click?\n      yes: CTR rises across campaigns that mention the offer, and the same week last year shows it too.\n  - id: invalid-clicks\n    label: Bots and accidental clicks\n    metric: bounce-rate\n    dropped:\n      check: Did a platform start filtering invalid clicks, or did an accidental-tap placement stop serving?\n      yes: Clicks fall on one placement while orders from paid traffic hold.\n    spiked:\n      check: Is a bot, click farm or accidental-tap placement adding clicks?\n      yes: Clicks jump on one placement or app, and those visits bounce almost every time.\n\ndiagnose_order: [sync, channel-mix, creative-fatigue, calendar, invalid-clicks]\n\nrelated: [cpm, cpc, paid-sessions, ad-spend, paid-conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Click-through rate is how well the ads earn attention, and with CPM it sets the price of a\n    click: CPC is CPM ÷ (CTR × 1,000). A fall from 1.2% to 1.0% makes every click 20% more\n    expensive at the same CPM. It is also the earliest sign of creative fatigue, usually weeks\n    before cost per order moves.\n  pitfalls:\n    - Use link clicks, not all clicks. Meta's all-clicks include likes, comments and profile taps, and run two to three times the link-click rate.\n    - A blended CTR moves with the mix. Search ads run 3 to 6%, social 0.8 to 1.5% and display under 0.5%; split by channel before reading a change.\n    - A high CTR from an accidental-tap placement is worse than a low one. Check that clicks became sessions that stayed.\n    - At millions of impressions a week, chance barely moves CTR, so most moves are real. Real doesn't mean caused by you; check the platform and the mix first.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ctr","name":"Click-through rate","aliases":["Ad click-through rate","Ad CTR","Clickthrough rate","Link click-through rate"],"family":"acquisition","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of ad impressions in the week that led to a click, across every synced ad platform.","formula":"Ad clicks ÷ ad impressions"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"clicks","description":"Link clicks that day. Use link clicks, not all clicks, where the platform offers both."},{"name":"impressions","description":"Ads shown that day, as the platform counts them."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."},{"name":"campaign","description":"The campaign name or id on that platform."}]}],"numerator":{"label":"Ad clicks","aggregate":"sum","event":"ad_spend","property":"clicks"},"denominator":{"label":"Impressions","aggregate":"sum","event":"ad_spend","property":"impressions"},"noise":{"type":"binomial","min_denominator":10000,"volume_unit":"impressions a week","typical":0.011,"reference_volumes":[10000,100000,1000000,10000000]},"example":{"business":"store","level":0.0115,"volume":21000000,"trend":-0.05},"drivers":[{"id":"sync","label":"Click and impression sync","breakdown":"channel","dropped":{"check":"Did a sync miss clicks for some days, or switch one channel from all clicks to link clicks?","yes":"One channel's clicks fall sharply from one day while its spend and the sessions it sends hold."},"spiked":{"check":"Is a channel syncing all clicks (likes, profile taps, expands) instead of link clicks, or missing impressions?","yes":"One channel's CTR jumps several times over while the sessions it sends barely move."}},{"id":"channel-mix","label":"Channel and placement mix","breakdown":"channel","dropped":{"check":"Did budget shift toward low-CTR inventory such as display, video or Audience Network?","yes":"Each channel's CTR holds but low-CTR placements took a bigger share of impressions."},"spiked":{"check":"Did budget shift toward high-CTR inventory such as branded search or retargeting?","yes":"Each channel's CTR holds but high-CTR placements took a bigger share of impressions."}},{"id":"creative-fatigue","label":"Creative fatigue","breakdown":"campaign","dropped":{"check":"Have the same ads run for weeks to the same people?","yes":"CTR falls steadily on long-running campaigns as frequency climbs past 3."},"spiked":{"check":"Did new creative, a new offer or a new hook go live?","yes":"CTR rises on the campaigns that changed from the day they launched."}},{"id":"calendar","label":"Calendar and offers","feed":"shopping","dropped":{"check":"Did a sale end, so ads lost the offer people were clicking for?","yes":"The same weeks last year show the same fall after the sale."},"spiked":{"check":"Is a sale, holiday or launch giving people a reason to click?","yes":"CTR rises across campaigns that mention the offer, and the same week last year shows it too."}},{"id":"invalid-clicks","label":"Bots and accidental clicks","metric":"bounce-rate","dropped":{"check":"Did a platform start filtering invalid clicks, or did an accidental-tap placement stop serving?","yes":"Clicks fall on one placement while orders from paid traffic hold."},"spiked":{"check":"Is a bot, click farm or accidental-tap placement adding clicks?","yes":"Clicks jump on one placement or app, and those visits bounce almost every time."}}],"diagnose_order":["sync","channel-mix","creative-fatigue","calendar","invalid-clicks"],"related":["cpm","cpc","paid-sessions","ad-spend","paid-conversion-rate"],"prose":{"why_it_matters":"Click-through rate is how well the ads earn attention, and with CPM it sets the price of a click: CPC is CPM ÷ (CTR × 1,000). A fall from 1.2% to 1.0% makes every click 20% more expensive at the same CPM. It is also the earliest sign of creative fatigue, usually weeks before cost per order moves.","pitfalls":["Use link clicks, not all clicks. Meta's all-clicks include likes, comments and profile taps, and run two to three times the link-click rate.","A blended CTR moves with the mix. Search ads run 3 to 6%, social 0.8 to 1.5% and display under 0.5%; split by channel before reading a change.","A high CTR from an accidental-tap placement is worse than a low one. Check that clicks became sessions that stayed.","At millions of impressions a week, chance barely moves CTR, so most moves are real. Real doesn't mean caused by you; check the platform and the mix first."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "discount-rate": { yaml: "id: discount-rate\nname: Discount rate\naliases:\n  - Discount percentage\n  - Discounts as a share of sales\n  - Average discount rate\n  - Promotional discount rate\nfamily: revenue\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of gross sales given away as discounts at checkout, from codes, automatic offers and bundle deals.\n  formula: Discounts ÷ gross sales (order subtotals before discounts)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: subtotal\n        description: Price × quantity of every item, before discounts, tax and shipping.\n      - name: discount\n        description: The total discount taken off the subtotal, from codes and automatic offers; shipping discounts excluded.\n      - name: coupon\n        description: The code redeemed on the order, if any.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Discounts\n  aggregate: sum\n  event: order_completed\n  property: discount\ndenominator:\n  label: Gross sales\n  aggregate: sum\n  event: order_completed\n  property: subtotal\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.1\n\nexample:\n  business: store\n  level: 0.089\n  volume: 13300\n  trend: 0.05\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a new discount app or checkout stop sending the discount on the order event?\n      yes: Orders with a coupon but a zero discount appear from one day.\n    spiked:\n      check: Did discount start including shipping discounts, gift cards or tax, or subtotal change basis?\n      yes: The rate steps up on one release day with no new offer.\n  - id: calendar\n    label: Sales and the calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end, or was last week a sale week?\n      yes: The same week last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is a sale running, store-wide or on a code? Check orders rose with it.\n      yes: The rise matches the sale's dates, and the same week last year shows it too.\n  - id: codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    breakdown: coupon\n    dropped:\n      check: Did fewer orders use a code, because a code expired or a leaked one was disabled?\n      yes: Code usage falls by about as much as the discount rate.\n    spiked:\n      check: Did a code leak, or did an influencer or affiliate code take off?\n      yes: One code explains most of the rise, often on orders from channels it was never sent to.\n  - id: offer-depth\n    label: Depth of offers\n    dropped:\n      check: Did the offer get shallower, such as 15% off instead of 25%?\n      yes: The discount per discounted order falls while the number of discounted orders holds.\n    spiked:\n      check: Did a deeper offer run, or did two offers start stacking?\n      yes: The discount per discounted order rises; stacked orders carry both a code and an automatic offer.\n  - id: first-orders\n    label: Welcome offers\n    breakdown: is_first_order\n    dropped:\n      check: Did fewer first-time customers order with a welcome discount?\n      yes: The rate holds within each group and only the share of first orders moved.\n    spiked:\n      check: Did more first-time customers order with a welcome discount, or did the welcome offer grow?\n      yes: The rate on first orders rises, or first orders take a larger share.\n\ndiagnose_order: [tracking, calendar, codes, offer-depth, first-orders]\n\nrelated: [promo-code-usage-rate, gross-sales, gross-margin, aov, net-revenue]\n\nprose:\n  why_it_matters: >-\n    Discount rate is the price of the growth a store buys with promotions, and it creeps as\n    welcome codes, influencer codes, leaked codes and stacked offers each add a point nobody\n    chose. At Northwind, 8.5% of $1.45M of gross sales is about $123,000 a week, and each extra\n    point costs $14,500 of margin a week.\n  pitfalls:\n    - Markdowns made by lowering the product's price never show as discounts. A store that moves from codes to markdowns sees its discount rate fall while it gives away more.\n    - Free-shipping offers aren't in subtotal or discount. Track their cost separately or the price of a free-shipping promotion stays invisible.\n    - Discounts over gross sales measure cost, while the average discount on discounted orders measures offer depth. Don't compare one with the other's benchmark.\n    - Read it with orders. A sale that adds five points of discount and 30% more orders may be the best week of the quarter; the same five points with flat orders gave margin away.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"discount-rate","name":"Discount rate","aliases":["Discount percentage","Discounts as a share of sales","Average discount rate","Promotional discount rate"],"family":"revenue","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of gross sales given away as discounts at checkout, from codes, automatic offers and bundle deals.","formula":"Discounts ÷ gross sales (order subtotals before discounts)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"subtotal","description":"Price × quantity of every item, before discounts, tax and shipping."},{"name":"discount","description":"The total discount taken off the subtotal, from codes and automatic offers; shipping discounts excluded."},{"name":"coupon","description":"The code redeemed on the order, if any."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Discounts","aggregate":"sum","event":"order_completed","property":"discount"},"denominator":{"label":"Gross sales","aggregate":"sum","event":"order_completed","property":"subtotal"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.1},"example":{"business":"store","level":0.089,"volume":13300,"trend":0.05,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a new discount app or checkout stop sending the discount on the order event?","yes":"Orders with a coupon but a zero discount appear from one day."},"spiked":{"check":"Did discount start including shipping discounts, gift cards or tax, or subtotal change basis?","yes":"The rate steps up on one release day with no new offer."}},{"id":"calendar","label":"Sales and the calendar","feed":"shopping","dropped":{"check":"Did a sale end, or was last week a sale week?","yes":"The same week last year shows the same fall once aligned on the event."},"spiked":{"check":"Is a sale running, store-wide or on a code? Check orders rose with it.","yes":"The rise matches the sale's dates, and the same week last year shows it too."}},{"id":"codes","label":"Discount codes","metric":"promo-code-usage-rate","breakdown":"coupon","dropped":{"check":"Did fewer orders use a code, because a code expired or a leaked one was disabled?","yes":"Code usage falls by about as much as the discount rate."},"spiked":{"check":"Did a code leak, or did an influencer or affiliate code take off?","yes":"One code explains most of the rise, often on orders from channels it was never sent to."}},{"id":"offer-depth","label":"Depth of offers","dropped":{"check":"Did the offer get shallower, such as 15% off instead of 25%?","yes":"The discount per discounted order falls while the number of discounted orders holds."},"spiked":{"check":"Did a deeper offer run, or did two offers start stacking?","yes":"The discount per discounted order rises; stacked orders carry both a code and an automatic offer."}},{"id":"first-orders","label":"Welcome offers","breakdown":"is_first_order","dropped":{"check":"Did fewer first-time customers order with a welcome discount?","yes":"The rate holds within each group and only the share of first orders moved."},"spiked":{"check":"Did more first-time customers order with a welcome discount, or did the welcome offer grow?","yes":"The rate on first orders rises, or first orders take a larger share."}}],"diagnose_order":["tracking","calendar","codes","offer-depth","first-orders"],"related":["promo-code-usage-rate","gross-sales","gross-margin","aov","net-revenue"],"prose":{"why_it_matters":"Discount rate is the price of the growth a store buys with promotions, and it creeps as welcome codes, influencer codes, leaked codes and stacked offers each add a point nobody chose. At Northwind, 8.5% of $1.45M of gross sales is about $123,000 a week, and each extra point costs $14,500 of margin a week.","pitfalls":["Markdowns made by lowering the product's price never show as discounts. A store that moves from codes to markdowns sees its discount rate fall while it gives away more.","Free-shipping offers aren't in subtotal or discount. Track their cost separately or the price of a free-shipping promotion stays invisible.","Discounts over gross sales measure cost, while the average discount on discounted orders measures offer depth. Don't compare one with the other's benchmark.","Read it with orders. A sale that adds five points of discount and 30% more orders may be the best week of the quarter; the same five points with flat orders gave margin away."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "email-click-rate": { yaml: "id: email-click-rate\nname: Email click rate\naliases:\n  - Email CTR\n  - Email click-through rate\n  - Email unique click rate\n  - Newsletter click rate\nfamily: traffic\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of emails delivered in the week whose recipient clicked at least one link in them.\n  formula: Distinct recipient and campaign pairs with a click ÷ distinct recipient and campaign pairs delivered\n\nevents:\n  - name: email_delivered\n    description: The receiving server accepted the email. Bounced and suppressed sends are not deliveries.\n    also_called: [Email Delivered, Received Email, delivered]\n    properties:\n      - name: campaign_id\n        description: The campaign or automated flow message the email belongs to.\n  - name: email_clicked\n    description: A tracked link in the email was opened. One recipient can click many times.\n    also_called: [Email Link Clicked, Clicked Email, click]\n    properties:\n      - name: campaign_id\n        description: The campaign or automated flow message the click belongs to.\n\nnumerator:\n  label: Recipients who clicked\n  aggregate: unique_users\n  event: email_clicked\ndenominator:\n  label: Emails delivered\n  aggregate: count\n  event: email_delivered\n\nqueries:\n  hogql: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\n    SELECT week, numerator, denominator, if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM (\n      SELECT\n        toMonday(timestamp) AS week,\n        uniqIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_clicked') AS numerator,\n        uniqIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_delivered') AS denominator\n      FROM events\n      WHERE event IN ('email_delivered', 'email_clicked')\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY week\n    )\n    ORDER BY week\n  postgres: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\n    SELECT\n      date_trunc('week', occurred_at)::date AS week,\n      count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_clicked') AS numerator,\n      count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_delivered') AS denominator,\n      (count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_clicked'))::numeric\n        / nullif(count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_delivered'), 0) AS value\n    FROM events\n    WHERE event_name IN ('email_delivered', 'email_clicked')\n      AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n      AND occurred_at < date_trunc('week', now())\n    GROUP BY 1\n    ORDER BY 1;\n  bigquery: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\n    SELECT\n      week,\n      clicked AS numerator,\n      delivered AS denominator,\n      SAFE_DIVIDE(clicked, delivered) AS value\n    FROM (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COUNT(DISTINCT IF(event_name = 'email_clicked', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS clicked,\n        COUNT(DISTINCT IF(event_name = 'email_delivered', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS delivered\n      FROM events\n      WHERE event_name IN ('email_delivered', 'email_clicked')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    )\n    ORDER BY week;\n  snowflake: |-\n    -- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\n    -- Assumes WEEK_START = 1 (Monday).\n    SELECT\n      week,\n      clicked AS numerator,\n      delivered AS denominator,\n      DIV0NULL(clicked, delivered) AS value\n    FROM (\n      SELECT\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        COUNT(DISTINCT IFF(event_name = 'email_clicked', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS clicked,\n        COUNT(DISTINCT IFF(event_name = 'email_delivered', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS delivered\n      FROM events\n      WHERE event_name IN ('email_delivered', 'email_clicked')\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY 1\n    )\n    ORDER BY week;\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: emails delivered a week\n  typical: 0.02\n  reference_volumes: [5000, 20000, 100000, 500000]\n\nexample:\n  business: store\n  level: 0.019\n  volume: 240000\n  trend: -0.05\n  season: -0.5\n\ndrivers:\n  - id: tracking\n    label: Link tracking and sync\n    dropped:\n      check: Did the email platform's sync, the click-tracking domain or its certificate break?\n      yes: Clicks fall to near zero for some campaigns while email-driven sessions in analytics hold.\n    spiked:\n      check: Is a sync sending click events twice, or counting each click as a new recipient?\n      yes: Clicks per clicker jump and the rise is identical across every campaign.\n  - id: bot-clicks\n    label: Security scanners\n    dropped:\n      check: Did your email platform start filtering bot clicks?\n      yes: The fall starts on the day of a platform release, mostly on business email domains.\n    spiked:\n      check: Are corporate security scanners clicking every link seconds after delivery?\n      yes: Clicks land within a minute of delivery, hit every link in the email, and produce no sessions.\n  - id: calendar\n    label: Calendar and inbox competition\n    feed: shopping\n    dropped:\n      check: Is this a week when every brand is emailing, such as Black Friday or the week before Christmas?\n      yes: The same week last year shows the same dip in click rate even as revenue from email rises.\n    spiked:\n      check: Was last week a crowded inbox week that this week isn't?\n      yes: The same pair of weeks last year shows the same recovery.\n  - id: audience\n    label: Who was sent to\n    breakdown: campaign_id\n    dropped:\n      check: Did a send go to a larger, less engaged audience, such as the whole list or an old segment?\n      yes: Deliveries jump for one campaign whose click rate is far below the usual ones.\n    spiked:\n      check: Did the week's sends go only to engaged segments, or did a big unengaged send drop out?\n      yes: Deliveries fall while clicks hold, so the rate rises with no change in content.\n  - id: deliverability\n    label: Inbox placement\n    dropped:\n      check: Did emails start landing in spam or the Promotions tab, after a sending change or a spam complaint spike?\n      yes: Deliveries hold but clicks fall on Gmail or Outlook addresses only.\n    spiked:\n      check: Did a sending-domain or authentication fix move emails back to the inbox?\n      yes: Clicks recover on one mailbox provider from the day of the fix.\n  - id: offer\n    label: Offer and content\n    metric: promo-code-usage-rate\n    dropped:\n      check: Did this week's emails carry a weaker offer, no product news or fewer links?\n      yes: Click rate falls on campaigns while automated flows hold.\n    spiked:\n      check: Did a sale, a launch or a restock email go out?\n      yes: One campaign's click rate is several times the usual and accounts for the rise.\n\ndiagnose_order: [tracking, bot-clicks, calendar, audience, deliverability, offer]\n\nrelated: [sessions, new-visitor-share, repeat-purchase-rate, returning-customers, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Email is the cheapest repeat traffic a store has, and click rate is the first sign that a\n    list is tiring or a send is landing in spam. Opens stopped meaning much when Apple Mail\n    began pre-loading every email in 2021; clicks still need a person. On 240,000 deliveries a\n    week, half a point is 1,200 fewer people on the site from email.\n  pitfalls:\n    - Use unique clicks over delivered emails. Total clicks over sends counts one keen reader five times and counts bounced addresses as failures.\n    - Corporate security scanners click every link in an email within seconds of delivery. Without bot filtering, business-heavy lists show click rates two or three times the real one.\n    - Clicks are counted in the week they happen, so a Sunday send's clicks fall partly into the next week. Compare weeks with similar send schedules.\n    - Click-to-open rate is a different number. Apple Mail Privacy Protection inflates opens, so it falls for reasons that have nothing to do with the email.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"email-click-rate","name":"Email click rate","aliases":["Email CTR","Email click-through rate","Email unique click rate","Newsletter click rate"],"family":"traffic","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of emails delivered in the week whose recipient clicked at least one link in them.","formula":"Distinct recipient and campaign pairs with a click ÷ distinct recipient and campaign pairs delivered"},"events":[{"name":"email_delivered","description":"The receiving server accepted the email. Bounced and suppressed sends are not deliveries.","also_called":["Email Delivered","Received Email","delivered"],"properties":[{"name":"campaign_id","description":"The campaign or automated flow message the email belongs to."}]},{"name":"email_clicked","description":"A tracked link in the email was opened. One recipient can click many times.","also_called":["Email Link Clicked","Clicked Email","click"],"properties":[{"name":"campaign_id","description":"The campaign or automated flow message the click belongs to."}]}],"numerator":{"label":"Recipients who clicked","aggregate":"unique_users","event":"email_clicked"},"denominator":{"label":"Emails delivered","aggregate":"count","event":"email_delivered"},"queries":{"hogql":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\nSELECT week, numerator, denominator, if(denominator > 0, numerator / denominator, NULL) AS value\nFROM (\n  SELECT\n    toMonday(timestamp) AS week,\n    uniqIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_clicked') AS numerator,\n    uniqIf(concat(toString(person_id), ':', toString(properties.campaign_id)), event = 'email_delivered') AS denominator\n  FROM events\n  WHERE event IN ('email_delivered', 'email_clicked')\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY week\n)\nORDER BY week","postgres":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\nSELECT\n  date_trunc('week', occurred_at)::date AS week,\n  count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_clicked') AS numerator,\n  count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_delivered') AS denominator,\n  (count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_clicked'))::numeric\n    / nullif(count(DISTINCT user_id || ':' || (properties->>'campaign_id')) FILTER (WHERE event_name = 'email_delivered'), 0) AS value\nFROM events\nWHERE event_name IN ('email_delivered', 'email_clicked')\n  AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n  AND occurred_at < date_trunc('week', now())\nGROUP BY 1\nORDER BY 1;","bigquery":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\nSELECT\n  week,\n  clicked AS numerator,\n  delivered AS denominator,\n  SAFE_DIVIDE(clicked, delivered) AS value\nFROM (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COUNT(DISTINCT IF(event_name = 'email_clicked', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS clicked,\n    COUNT(DISTINCT IF(event_name = 'email_delivered', CONCAT(user_id, ':', JSON_VALUE(properties, '$.campaign_id')), NULL)) AS delivered\n  FROM events\n  WHERE event_name IN ('email_delivered', 'email_clicked')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n)\nORDER BY week;","snowflake":"-- Email click rate per week: distinct recipient and campaign pairs that clicked ÷ pairs delivered, each by the week it happened.\n-- Assumes WEEK_START = 1 (Monday).\nSELECT\n  week,\n  clicked AS numerator,\n  delivered AS denominator,\n  DIV0NULL(clicked, delivered) AS value\nFROM (\n  SELECT\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    COUNT(DISTINCT IFF(event_name = 'email_clicked', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS clicked,\n    COUNT(DISTINCT IFF(event_name = 'email_delivered', user_id || ':' || properties:\"campaign_id\"::string, NULL)) AS delivered\n  FROM events\n  WHERE event_name IN ('email_delivered', 'email_clicked')\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY 1\n)\nORDER BY week;"},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"emails delivered a week","typical":0.02,"reference_volumes":[5000,20000,100000,500000]},"example":{"business":"store","level":0.019,"volume":240000,"trend":-0.05,"season":-0.5},"drivers":[{"id":"tracking","label":"Link tracking and sync","dropped":{"check":"Did the email platform's sync, the click-tracking domain or its certificate break?","yes":"Clicks fall to near zero for some campaigns while email-driven sessions in analytics hold."},"spiked":{"check":"Is a sync sending click events twice, or counting each click as a new recipient?","yes":"Clicks per clicker jump and the rise is identical across every campaign."}},{"id":"bot-clicks","label":"Security scanners","dropped":{"check":"Did your email platform start filtering bot clicks?","yes":"The fall starts on the day of a platform release, mostly on business email domains."},"spiked":{"check":"Are corporate security scanners clicking every link seconds after delivery?","yes":"Clicks land within a minute of delivery, hit every link in the email, and produce no sessions."}},{"id":"calendar","label":"Calendar and inbox competition","feed":"shopping","dropped":{"check":"Is this a week when every brand is emailing, such as Black Friday or the week before Christmas?","yes":"The same week last year shows the same dip in click rate even as revenue from email rises."},"spiked":{"check":"Was last week a crowded inbox week that this week isn't?","yes":"The same pair of weeks last year shows the same recovery."}},{"id":"audience","label":"Who was sent to","breakdown":"campaign_id","dropped":{"check":"Did a send go to a larger, less engaged audience, such as the whole list or an old segment?","yes":"Deliveries jump for one campaign whose click rate is far below the usual ones."},"spiked":{"check":"Did the week's sends go only to engaged segments, or did a big unengaged send drop out?","yes":"Deliveries fall while clicks hold, so the rate rises with no change in content."}},{"id":"deliverability","label":"Inbox placement","dropped":{"check":"Did emails start landing in spam or the Promotions tab, after a sending change or a spam complaint spike?","yes":"Deliveries hold but clicks fall on Gmail or Outlook addresses only."},"spiked":{"check":"Did a sending-domain or authentication fix move emails back to the inbox?","yes":"Clicks recover on one mailbox provider from the day of the fix."}},{"id":"offer","label":"Offer and content","metric":"promo-code-usage-rate","dropped":{"check":"Did this week's emails carry a weaker offer, no product news or fewer links?","yes":"Click rate falls on campaigns while automated flows hold."},"spiked":{"check":"Did a sale, a launch or a restock email go out?","yes":"One campaign's click rate is several times the usual and accounts for the rise."}}],"diagnose_order":["tracking","bot-clicks","calendar","audience","deliverability","offer"],"related":["sessions","new-visitor-share","repeat-purchase-rate","returning-customers","promo-code-usage-rate"],"prose":{"why_it_matters":"Email is the cheapest repeat traffic a store has, and click rate is the first sign that a list is tiring or a send is landing in spam. Opens stopped meaning much when Apple Mail began pre-loading every email in 2021; clicks still need a person. On 240,000 deliveries a week, half a point is 1,200 fewer people on the site from email.","pitfalls":["Use unique clicks over delivered emails. Total clicks over sends counts one keen reader five times and counts bounced addresses as failures.","Corporate security scanners click every link in an email within seconds of delivery. Without bot filtering, business-heavy lists show click rates two or three times the real one.","Clicks are counted in the week they happen, so a Sunday send's clicks fall partly into the next week. Compare weeks with similar send schedules.","Click-to-open rate is a different number. Apple Mail Privacy Protection inflates opens, so it falls for reasons that have nothing to do with the email."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-margin": { yaml: "id: gross-margin\nname: Gross margin\naliases:\n  - Gross margin percentage\n  - Gross profit margin\n  - Product margin\nfamily: revenue\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of order revenue left after the cost of the goods sold, for orders paid this week.\n  formula: (Order revenue − cost of goods) ÷ order revenue, after discounts, before tax, shipping and refunds\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: The landed cost of the order's items, purchase price plus inbound freight and duties.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Cost of goods\n  aggregate: sum\n  event: order_completed\n  property: cost_of_goods\ndenominator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.55\n\nexample:\n  business: store\n  level: 0.532\n  volume: 13300\n  trend: -0.02\n\ndrivers:\n  - id: cost-data\n    label: Cost data\n    dropped:\n      check: Did cost_of_goods change basis, for example adding freight or loading a new supplier price list?\n      yes: Cost per unit jumps for many products on one date, with no new purchase order behind it.\n    spiked:\n      check: Are products selling without a recorded cost, counting as free?\n      yes: The share of orders with no cost_of_goods rises, usually on new products.\n  - id: discounts\n    label: Discounts and sales\n    metric: discount-rate\n    feed: shopping\n    dropped:\n      check: Did discounts rise, from a sale, a code or a stacked offer?\n      yes: Discount rate rises by about as much as margin falls.\n    spiked:\n      check: Did a sale end, so orders carry less discount?\n      yes: Discount rate falls by about as much as margin rises.\n  - id: product-mix\n    label: Product mix\n    dropped:\n      check: Did low-margin products, such as bundles, clearance or a new hero product, take a larger share of sales?\n      yes: Each product's own margin holds and only the mix moved.\n    spiked:\n      check: Did high-margin products take a larger share of sales?\n      yes: Each product's own margin holds and only the mix moved.\n  - id: landed-cost\n    label: Supplier, freight and duties\n    dropped:\n      check: Did supplier prices, freight or tariffs raise unit costs?\n      yes: Cost per unit rises on the same products, often when a new purchase order is received.\n    spiked:\n      check: Did a cheaper batch of stock start selling? Check it's not a cost data error first.\n      yes: Cost per unit falls on the products from one purchase order.\n  - id: pricing\n    label: Prices\n    dropped:\n      check: Did list prices fall, or did a price test lower them for some shoppers?\n      yes: Revenue per unit falls while cost per unit holds.\n    spiked:\n      check: Did a price rise take effect?\n      yes: Revenue per unit rises from the price change date while cost per unit holds.\n\ndiagnose_order: [cost-data, discounts, product-mix, landed-cost, pricing]\n\nrelated: [contribution-margin, discount-rate, net-revenue, aov, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Gross margin decides how much of each dollar of revenue is left for marketing, shipping and\n    everything else. A store at 58% margin that slips to 55% has lost about 5% of what it has to\n    spend with revenue unchanged; at Northwind that is about $40,000 a week.\n  pitfalls:\n    - Cost of goods should be the landed cost per unit, the purchase price plus inbound freight and duties. Supplier price alone overstates margin by several points for imported goods.\n    - Products without a recorded cost count as free and pull margin up. New products are the usual culprit.\n    - This spec matches each order's revenue to its own cost and leaves refunds out, because a refund event carries no cost. Read refund rate beside it.\n    - Shipping, packaging and payment fees aren't cost of goods. Including them mixes gross margin with contribution margin and breaks comparisons with industry figures.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-margin","name":"Gross margin","aliases":["Gross margin percentage","Gross profit margin","Product margin"],"family":"revenue","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of order revenue left after the cost of the goods sold, for orders paid this week.","formula":"(Order revenue − cost of goods) ÷ order revenue, after discounts, before tax, shipping and refunds"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"The landed cost of the order's items, purchase price plus inbound freight and duties."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Cost of goods","aggregate":"sum","event":"order_completed","property":"cost_of_goods"},"denominator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.55},"example":{"business":"store","level":0.532,"volume":13300,"trend":-0.02},"drivers":[{"id":"cost-data","label":"Cost data","dropped":{"check":"Did cost_of_goods change basis, for example adding freight or loading a new supplier price list?","yes":"Cost per unit jumps for many products on one date, with no new purchase order behind it."},"spiked":{"check":"Are products selling without a recorded cost, counting as free?","yes":"The share of orders with no cost_of_goods rises, usually on new products."}},{"id":"discounts","label":"Discounts and sales","metric":"discount-rate","feed":"shopping","dropped":{"check":"Did discounts rise, from a sale, a code or a stacked offer?","yes":"Discount rate rises by about as much as margin falls."},"spiked":{"check":"Did a sale end, so orders carry less discount?","yes":"Discount rate falls by about as much as margin rises."}},{"id":"product-mix","label":"Product mix","dropped":{"check":"Did low-margin products, such as bundles, clearance or a new hero product, take a larger share of sales?","yes":"Each product's own margin holds and only the mix moved."},"spiked":{"check":"Did high-margin products take a larger share of sales?","yes":"Each product's own margin holds and only the mix moved."}},{"id":"landed-cost","label":"Supplier, freight and duties","dropped":{"check":"Did supplier prices, freight or tariffs raise unit costs?","yes":"Cost per unit rises on the same products, often when a new purchase order is received."},"spiked":{"check":"Did a cheaper batch of stock start selling? Check it's not a cost data error first.","yes":"Cost per unit falls on the products from one purchase order."}},{"id":"pricing","label":"Prices","dropped":{"check":"Did list prices fall, or did a price test lower them for some shoppers?","yes":"Revenue per unit falls while cost per unit holds."},"spiked":{"check":"Did a price rise take effect?","yes":"Revenue per unit rises from the price change date while cost per unit holds."}}],"diagnose_order":["cost-data","discounts","product-mix","landed-cost","pricing"],"related":["contribution-margin","discount-rate","net-revenue","aov","refund-rate"],"prose":{"why_it_matters":"Gross margin decides how much of each dollar of revenue is left for marketing, shipping and everything else. A store at 58% margin that slips to 55% has lost about 5% of what it has to spend with revenue unchanged; at Northwind that is about $40,000 a week.","pitfalls":["Cost of goods should be the landed cost per unit, the purchase price plus inbound freight and duties. Supplier price alone overstates margin by several points for imported goods.","Products without a recorded cost count as free and pull margin up. New products are the usual culprit.","This spec matches each order's revenue to its own cost and leaves refunds out, because a refund event carries no cost. Read refund rate beside it.","Shipping, packaging and payment fees aren't cost of goods. Including them mixes gross margin with contribution margin and breaks comparisons with industry figures."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-sales": { yaml: "id: gross-sales\nname: Gross sales\naliases:\n  - Gross revenue\n  - Gross merchandise value\n  - GMV\n  - Sales before discounts\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The value of products sold this week at their selling price, before discounts, refunds, tax and shipping.\n  formula: Sum of order subtotals before discounts, excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: subtotal\n        description: Price × quantity of every item, before discounts, tax and shipping.\n      - name: discount\n        description: The total discount on the order, read in discount rate.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Gross sales\n  aggregate: sum\n  event: order_completed\n  property: subtotal\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 300000\n\nexample:\n  business: store\n  level: 1450000\n  volume: 13300\n  trend: 0.2\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did subtotal stop being sent, or change meaning, for example to after discounts?\n      yes: Subtotal ÷ order total jumps or falls on one release day with no change in offers.\n    spiked:\n      check: Did subtotal start including tax or shipping, or did one currency start arriving unconverted?\n      yes: Order subtotals jump for one country or channel from one day.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or gifting week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or gifting week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth before discounts?\n      yes: Orders fall by about as much as gross sales.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as gross sales.\n  - id: discounts\n    label: Promotions\n    metric: discount-rate\n    dropped:\n      check: Did a promotion end that had been pulling demand forward?\n      yes: Discount rate falls with gross sales while net revenue falls less.\n    spiked:\n      check: Is a promotion lifting gross sales while discounts eat the gain? Check net revenue before celebrating.\n      yes: Discount rate rises with gross sales, and net revenue grows far less.\n  - id: basket-size\n    label: Items per order\n    metric: units-per-order\n    dropped:\n      check: Did shoppers buy fewer items per order, after a bundle ended or a free-shipping threshold fell?\n      yes: Units per order fall while orders hold.\n    spiked:\n      check: Did a bundle, multi-buy offer or higher free-shipping threshold add items to orders?\n      yes: Units per order rise from the day the offer started.\n  - id: price-and-mix\n    label: Prices and product mix\n    dropped:\n      check: Did prices fall, or did sales shift toward cheaper products?\n      yes: Units hold while the average price per unit falls, often on a few products.\n    spiked:\n      check: Did prices rise, a premium product launch, or a few very large orders land?\n      yes: The average price per unit rises, or the largest orders explain most of the jump.\n\ndiagnose_order: [tracking, calendar, orders, discounts, basket-size, price-and-mix]\n\nrelated: [net-revenue, discount-rate, refund-rate, aov, units-per-order]\n\nprose:\n  why_it_matters: >-\n    Gross sales measure demand at full price, before the store decides what to give back.\n    Read beside net revenue, the gap is the cost of promotions and returns; at Northwind, $1.45M\n    of gross sales becomes $1.33M after discounts and about $1.29M after refunds. A promotion\n    that grows gross sales 20% while net revenue grows 5% bought most of its growth.\n  pitfalls:\n    - Shopify's gross sales is price × quantity before discounts, but some platforms' gross revenue includes tax and shipping. Say which one you report; this spec excludes both.\n    - Marking a price down on the product lowers gross sales itself, while a code adds a discount. Two sales of the same depth look different here, so know which kind each one was.\n    - Gross sales rise with every promotion that works on volume. Never report them without net revenue beside them.\n    - A few wholesale or bulk orders can move a small store's week by 10% or more. Check the order count and the largest orders before the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-sales","name":"Gross sales","aliases":["Gross revenue","Gross merchandise value","GMV","Sales before discounts"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The value of products sold this week at their selling price, before discounts, refunds, tax and shipping.","formula":"Sum of order subtotals before discounts, excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"subtotal","description":"Price × quantity of every item, before discounts, tax and shipping."},{"name":"discount","description":"The total discount on the order, read in discount rate."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Gross sales","aggregate":"sum","event":"order_completed","property":"subtotal"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":300000},"example":{"business":"store","level":1450000,"volume":13300,"trend":0.2,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did subtotal stop being sent, or change meaning, for example to after discounts?","yes":"Subtotal ÷ order total jumps or falls on one release day with no change in offers."},"spiked":{"check":"Did subtotal start including tax or shipping, or did one currency start arriving unconverted?","yes":"Order subtotals jump for one country or channel from one day."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or gifting week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or gifting week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth before discounts?","yes":"Orders fall by about as much as gross sales."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as gross sales."}},{"id":"discounts","label":"Promotions","metric":"discount-rate","dropped":{"check":"Did a promotion end that had been pulling demand forward?","yes":"Discount rate falls with gross sales while net revenue falls less."},"spiked":{"check":"Is a promotion lifting gross sales while discounts eat the gain? Check net revenue before celebrating.","yes":"Discount rate rises with gross sales, and net revenue grows far less."}},{"id":"basket-size","label":"Items per order","metric":"units-per-order","dropped":{"check":"Did shoppers buy fewer items per order, after a bundle ended or a free-shipping threshold fell?","yes":"Units per order fall while orders hold."},"spiked":{"check":"Did a bundle, multi-buy offer or higher free-shipping threshold add items to orders?","yes":"Units per order rise from the day the offer started."}},{"id":"price-and-mix","label":"Prices and product mix","dropped":{"check":"Did prices fall, or did sales shift toward cheaper products?","yes":"Units hold while the average price per unit falls, often on a few products."},"spiked":{"check":"Did prices rise, a premium product launch, or a few very large orders land?","yes":"The average price per unit rises, or the largest orders explain most of the jump."}}],"diagnose_order":["tracking","calendar","orders","discounts","basket-size","price-and-mix"],"related":["net-revenue","discount-rate","refund-rate","aov","units-per-order"],"prose":{"why_it_matters":"Gross sales measure demand at full price, before the store decides what to give back. Read beside net revenue, the gap is the cost of promotions and returns; at Northwind, $1.45M of gross sales becomes $1.33M after discounts and about $1.29M after refunds. A promotion that grows gross sales 20% while net revenue grows 5% bought most of its growth.","pitfalls":["Shopify's gross sales is price × quantity before discounts, but some platforms' gross revenue includes tax and shipping. Say which one you report; this spec excludes both.","Marking a price down on the product lowers gross sales itself, while a code adds a discount. Two sales of the same depth look different here, so know which kind each one was.","Gross sales rise with every promotion that works on volume. Never report them without net revenue beside them.","A few wholesale or bulk orders can move a small store's week by 10% or more. Check the order count and the largest orders before the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mer": { yaml: "id: mer\nname: Marketing efficiency ratio\naliases:\n  - Blended ROAS\n  - Media efficiency ratio\n  - Total ROAS\nfamily: acquisition\ncatalog_id: mer\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: All net revenue in the week for each dollar of ad spend, with no attribution to any channel.\n  formula: (Order revenue − refunds) ÷ ad spend, both by the week they happened\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\ndenominator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 3.5\n\nexample:\n  business: store\n  level: 4.3\n  volume: 13000\n  trend: -0.04\n\ndrivers:\n  - id: spend-sync\n    label: Spend sync\n    dropped:\n      check: Is a day of spend synced twice, or a currency recorded at the wrong rate?\n      yes: One channel's spend doubles for a day or jumps by an exchange rate, and MER falls by the same share.\n    spiked:\n      check: Is a channel's spend missing for some days?\n      yes: One channel shows zero or partial spend while its own dashboard shows the usual amount.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did budgets rise ahead of an event before the revenue arrived, or did a sale end?\n      yes: The same weeks last year show the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week, when demand rises faster than spend?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend rise faster than revenue?\n      yes: Spend rises more than revenue does; the extra budget is buying less than the average.\n    spiked:\n      check: Did spend fall while revenue held?\n      yes: Spend falls and revenue barely moves, so some of that spend was buying sales that would have happened anyway.\n  - id: revenue\n    label: Net revenue\n    metric: net-revenue\n    dropped:\n      check: Did revenue fall at steady spend, from conversion, stock, pricing or refunds?\n      yes: Revenue falls while spend holds; the revenue driver tree says which part moved.\n    spiked:\n      check: Did revenue rise at steady spend, from a launch, a press mention or a price rise?\n      yes: Revenue rises while spend holds, usually through organic, direct or email traffic.\n  - id: returning-demand\n    label: Returning customers\n    metric: repeat-order-share\n    dropped:\n      check: Did returning customers, who cost little to bring back, order less?\n      yes: Repeat orders fall while first orders hold.\n    spiked:\n      check: Did a restock, a launch or an email bring returning customers back in numbers?\n      yes: Repeat orders jump while first orders and spend hold.\n\ndiagnose_order: [spend-sync, calendar, spend, revenue, returning-demand]\n\nrelated: [roas, ad-spend, net-revenue, ncac, contribution-margin]\n\nprose:\n  why_it_matters: >-\n    MER is the one efficiency number no ad platform can inflate: total revenue over total\n    spend, with no attribution model in between. Platform ROAS can say every channel is\n    profitable while MER falls; when they disagree, MER is right about the business. A store at\n    a MER of 4.3 with a 60% gross margin makes $2.58 of gross margin per ad dollar, or $1.58\n    after paying for the ad, before any other cost.\n  pitfalls:\n    - MER credits ads with revenue they didn't cause, such as repeat customers, email and word of mouth. A store with a loyal base can show a high MER while new-customer acquisition loses money; read nCAC next to it.\n    - Revenue and spend both follow the calendar, but not in step. Budgets often rise before a sale and revenue lands after it, so compare weeks with the same week last year, not the week before.\n    - Ad spend here is media only. Agency fees, creative and tools make the real ratio lower.\n    - Gross revenue and net revenue give different ratios. This spec uses revenue after discounts and refunds, before tax and shipping, the same as net revenue.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mer","name":"Marketing efficiency ratio","aliases":["Blended ROAS","Media efficiency ratio","Total ROAS"],"family":"acquisition","catalog_id":"mer","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"All net revenue in the week for each dollar of ad spend, with no attribution to any channel.","formula":"(Order revenue − refunds) ÷ ad spend, both by the week they happened"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"denominator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":3.5},"example":{"business":"store","level":4.3,"volume":13000,"trend":-0.04},"drivers":[{"id":"spend-sync","label":"Spend sync","dropped":{"check":"Is a day of spend synced twice, or a currency recorded at the wrong rate?","yes":"One channel's spend doubles for a day or jumps by an exchange rate, and MER falls by the same share."},"spiked":{"check":"Is a channel's spend missing for some days?","yes":"One channel shows zero or partial spend while its own dashboard shows the usual amount."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did budgets rise ahead of an event before the revenue arrived, or did a sale end?","yes":"The same weeks last year show the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week, when demand rises faster than spend?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend rise faster than revenue?","yes":"Spend rises more than revenue does; the extra budget is buying less than the average."},"spiked":{"check":"Did spend fall while revenue held?","yes":"Spend falls and revenue barely moves, so some of that spend was buying sales that would have happened anyway."}},{"id":"revenue","label":"Net revenue","metric":"net-revenue","dropped":{"check":"Did revenue fall at steady spend, from conversion, stock, pricing or refunds?","yes":"Revenue falls while spend holds; the revenue driver tree says which part moved."},"spiked":{"check":"Did revenue rise at steady spend, from a launch, a press mention or a price rise?","yes":"Revenue rises while spend holds, usually through organic, direct or email traffic."}},{"id":"returning-demand","label":"Returning customers","metric":"repeat-order-share","dropped":{"check":"Did returning customers, who cost little to bring back, order less?","yes":"Repeat orders fall while first orders hold."},"spiked":{"check":"Did a restock, a launch or an email bring returning customers back in numbers?","yes":"Repeat orders jump while first orders and spend hold."}}],"diagnose_order":["spend-sync","calendar","spend","revenue","returning-demand"],"related":["roas","ad-spend","net-revenue","ncac","contribution-margin"],"prose":{"why_it_matters":"MER is the one efficiency number no ad platform can inflate: total revenue over total spend, with no attribution model in between. Platform ROAS can say every channel is profitable while MER falls; when they disagree, MER is right about the business. A store at a MER of 4.3 with a 60% gross margin makes $2.58 of gross margin per ad dollar, or $1.58 after paying for the ad, before any other cost.","pitfalls":["MER credits ads with revenue they didn't cause, such as repeat customers, email and word of mouth. A store with a loyal base can show a high MER while new-customer acquisition loses money; read nCAC next to it.","Revenue and spend both follow the calendar, but not in step. Budgets often rise before a sale and revenue lands after it, so compare weeks with the same week last year, not the week before.","Ad spend here is media only. Agency fees, creative and tools make the real ratio lower.","Gross revenue and net revenue give different ratios. This spec uses revenue after discounts and refunds, before tax and shipping, the same as net revenue."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mobile-conversion-rate": { yaml: "id: mobile-conversion-rate\nname: Mobile conversion rate\naliases:\n  - Mobile ecommerce conversion rate\n  - Mobile store conversion rate\n  - Mobile CVR\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions on phones that end in a paid order. Tablets are left out, as GA4 reports them separately.\n  formula: Mobile sessions with a paid order ÷ mobile sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet, from the browser's user agent.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id and device type.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: $device_type\n        description: The device the order was placed on, copied from the browser session.\n\nnumerator:\n  label: Mobile sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\ndenominator:\n  label: Mobile sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: mobile sessions a week\n  typical: 0.016\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.0204\n  volume: 408000\n  trend: 0.04\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Are orders losing their device type or session id, for example after moving the order event to the server?\n      yes: Orders with no device type rise while mobile orders fall by about as much.\n    spiked:\n      check: Did mobile page views stop recording somewhere, or did tablets start reporting as mobile?\n      yes: Mobile sessions fall with no matching fall in mobile ad clicks, or tablet sessions drop to near zero.\n  - id: os-and-browsers\n    label: iOS, Android and browser releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Did an iOS, Android, Safari or Chrome release this week break a payment sheet, autofill or a script?\n      yes: The drop concentrates on one operating system or browser version, from its release date.\n    spiked:\n      check: Did a platform update or your own fix clear a problem from an earlier release?\n      yes: The affected system returns to its usual rate and the others never moved.\n  - id: mobile-release\n    label: Mobile site release\n    dropped:\n      check: Did a release change the mobile product page, menu, sticky add-to-cart bar or checkout layout?\n      yes: The drop starts on the release day and desktop conversion holds.\n    spiked:\n      check: Did a mobile release or test ship, and is it on for everyone?\n      yes: The rise starts on the release day; confirm it isn't a tracking change before crediting it.\n  - id: traffic-mix\n    label: Social and in-app traffic\n    breakdown: utm_source\n    dropped:\n      check: Did more mobile traffic come from social ads that open in Instagram or TikTok's in-app browser?\n      yes: Sessions from one social source grow, and those sessions convert at a fraction of the mobile web.\n    spiked:\n      check: Did a social campaign pause, or did email and branded search take a larger share of mobile visits?\n      yes: Each source's own rate holds and only the mix moved.\n  - id: wallets\n    label: Wallets and payment sheets\n    feed: stripe\n    dropped:\n      check: Did Apple Pay, Google Pay or Shop Pay drop out of mobile checkout or start failing?\n      yes: Wallet payments on mobile fall while card payments hold.\n    spiked:\n      check: Did a wallet button launch on product pages or in the cart?\n      yes: Wallet orders rise from the launch day and mobile checkouts get shorter.\n\ndiagnose_order: [tracking, os-and-browsers, mobile-release, traffic-mix, wallets]\n\nrelated: [conversion-rate, mobile-session-share, checkout-conversion, payment-success-rate, bounce-rate]\n\nprose:\n  why_it_matters: >-\n    Phones bring about two thirds of store sessions but convert well below desktop; at\n    Northwind, 1.9% against 2.9%. Mobile is where a store loses the most orders to small things,\n    such as a hidden button, a slow page or a payment sheet that doesn't open. Closing a fifth\n    of the gap on 408,000 mobile sessions a week is about 800 orders.\n  pitfalls:\n    - Orders sent from the server carry no device type, so mobile conversion reads near zero. Copy the device type and session id from the browser onto the order event.\n    - Tablets convert closer to desktop than to phones. This spec leaves them out; including them reads higher and isn't comparable.\n    - In-app browsers from Instagram and TikTok count as mobile sessions but convert far below the mobile web, so a social campaign lowers the rate without anything breaking.\n    - A shopper who browses on a phone and buys on a laptop counts as a lost mobile session and a desktop order. Read mobile conversion for change over time, not as what mobile is worth.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mobile-conversion-rate","name":"Mobile conversion rate","aliases":["Mobile ecommerce conversion rate","Mobile store conversion rate","Mobile CVR"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions on phones that end in a paid order. Tablets are left out, as GA4 reports them separately.","formula":"Mobile sessions with a paid order ÷ mobile sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."},{"name":"$device_type","description":"Mobile, Desktop or Tablet, from the browser's user agent."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id and device type.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"$device_type","description":"The device the order was placed on, copied from the browser session."}]}],"numerator":{"label":"Mobile sessions with a paid order","aggregate":"unique_sessions","event":"order_completed","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"denominator":{"label":"Mobile sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"mobile sessions a week","typical":0.016,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.0204,"volume":408000,"trend":0.04,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Are orders losing their device type or session id, for example after moving the order event to the server?","yes":"Orders with no device type rise while mobile orders fall by about as much."},"spiked":{"check":"Did mobile page views stop recording somewhere, or did tablets start reporting as mobile?","yes":"Mobile sessions fall with no matching fall in mobile ad clicks, or tablet sessions drop to near zero."}},{"id":"os-and-browsers","label":"iOS, Android and browser releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Did an iOS, Android, Safari or Chrome release this week break a payment sheet, autofill or a script?","yes":"The drop concentrates on one operating system or browser version, from its release date."},"spiked":{"check":"Did a platform update or your own fix clear a problem from an earlier release?","yes":"The affected system returns to its usual rate and the others never moved."}},{"id":"mobile-release","label":"Mobile site release","dropped":{"check":"Did a release change the mobile product page, menu, sticky add-to-cart bar or checkout layout?","yes":"The drop starts on the release day and desktop conversion holds."},"spiked":{"check":"Did a mobile release or test ship, and is it on for everyone?","yes":"The rise starts on the release day; confirm it isn't a tracking change before crediting it."}},{"id":"traffic-mix","label":"Social and in-app traffic","breakdown":"utm_source","dropped":{"check":"Did more mobile traffic come from social ads that open in Instagram or TikTok's in-app browser?","yes":"Sessions from one social source grow, and those sessions convert at a fraction of the mobile web."},"spiked":{"check":"Did a social campaign pause, or did email and branded search take a larger share of mobile visits?","yes":"Each source's own rate holds and only the mix moved."}},{"id":"wallets","label":"Wallets and payment sheets","feed":"stripe","dropped":{"check":"Did Apple Pay, Google Pay or Shop Pay drop out of mobile checkout or start failing?","yes":"Wallet payments on mobile fall while card payments hold."},"spiked":{"check":"Did a wallet button launch on product pages or in the cart?","yes":"Wallet orders rise from the launch day and mobile checkouts get shorter."}}],"diagnose_order":["tracking","os-and-browsers","mobile-release","traffic-mix","wallets"],"related":["conversion-rate","mobile-session-share","checkout-conversion","payment-success-rate","bounce-rate"],"prose":{"why_it_matters":"Phones bring about two thirds of store sessions but convert well below desktop; at Northwind, 1.9% against 2.9%. Mobile is where a store loses the most orders to small things, such as a hidden button, a slow page or a payment sheet that doesn't open. Closing a fifth of the gap on 408,000 mobile sessions a week is about 800 orders.","pitfalls":["Orders sent from the server carry no device type, so mobile conversion reads near zero. Copy the device type and session id from the browser onto the order event.","Tablets convert closer to desktop than to phones. This spec leaves them out; including them reads higher and isn't comparable.","In-app browsers from Instagram and TikTok count as mobile sessions but convert far below the mobile web, so a social campaign lowers the rate without anything breaking.","A shopper who browses on a phone and buys on a laptop counts as a lost mobile session and a desktop order. Read mobile conversion for change over time, not as what mobile is worth."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mobile-session-share": { yaml: "id: mobile-session-share\nname: Mobile session share\naliases:\n  - Mobile traffic share\n  - Mobile share of traffic\n  - Mobile traffic percentage\n  - Mobile sessions\nfamily: traffic\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of the week's sessions that happened on a phone, not counting tablets.\n  formula: Sessions on a mobile device ÷ all sessions\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $device_type\n        description: Mobile, Desktop or Tablet, parsed from the user agent.\n      - name: $session_id\n        description: Set by the analytics SDK; ties the page view to a visit.\n      - name: utm_source\n        description: The campaign source from the landing URL (google, facebook, tiktok).\n\nnumerator:\n  label: Mobile sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: sessions a week\n  typical: 0.7\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: app\n  level: 0.78\n  volume: 150000\n  trend: 0.02\n\ndrivers:\n  - id: tracking\n    label: Device detection and bots\n    breakdown: $browser\n    dropped:\n      check: Is a desktop bot or crawler adding sessions, or did a user-agent change reclassify phones?\n      yes: Desktop sessions jump from one browser or data-centre network that never orders.\n    spiked:\n      check: Did an in-app browser, a tracking fix or a mobile bot start counting more phone sessions?\n      yes: Mobile sessions rise from one browser or app webview while orders hold.\n  - id: calendar\n    label: Calendar\n    feed: holidays\n    dropped:\n      check: Did a holiday or long weekend end, sending people back to desks?\n      yes: The same weeks last year show the same shift back to desktop.\n    spiked:\n      check: Is this a holiday or vacation week, when people browse from phones?\n      yes: The same week last year shows the same rise in mobile share.\n  - id: paid-social\n    label: Paid social\n    metric: paid-sessions\n    breakdown: utm_source\n    dropped:\n      check: Did paid social spend, which is almost all mobile, fall or pause?\n      yes: Sessions from Meta, TikTok or Snap fall and the mobile share falls with them.\n    spiked:\n      check: Did a paid social campaign or creator push start?\n      yes: Sessions from a social source jump and nearly all of them are on phones.\n  - id: email-and-sms\n    label: Email and SMS sends\n    breakdown: utm_medium\n    dropped:\n      check: Did fewer email or SMS sends go out this week?\n      yes: Email and SMS sessions, mostly on phones, fall by enough to explain the shift.\n    spiked:\n      check: Did a big email or SMS campaign go out?\n      yes: Sessions tagged email or sms jump on the send days, mostly on phones.\n  - id: desktop-sources\n    label: Desktop-heavy sources\n    metric: organic-sessions\n    dropped:\n      check: Did search, B2B or work-hours traffic, which skews desktop, grow?\n      yes: Desktop sessions rise from search or one referrer while mobile holds.\n    spiked:\n      check: Did desktop-heavy sources such as search or a partner site shrink?\n      yes: Desktop sessions fall from one source while mobile holds.\n\ndiagnose_order: [tracking, calendar, paid-social, email-and-sms, desktop-sources]\n\nrelated: [sessions, mobile-conversion-rate, conversion-rate, bounce-rate, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    Phones bring most store visits but convert at about half the desktop rate, so the device\n    mix moves store conversion with no change to the site. When mobile share rises from 70% to\n    75%, a store converting 1.8% on mobile and 3.6% on desktop loses about 0.09 points of\n    conversion from the mix alone. Check this before blaming checkout.\n  pitfalls:\n    - Tablets are not mobile here. Tools that fold tablets into mobile read 3 to 8 points higher.\n    - Device type comes from the user agent. Browser changes such as reduced user-agent strings and in-app webviews can move sessions between devices without anyone changing what they use.\n    - The share can rise because desktop fell. Read it with mobile and desktop session counts side by side.\n    - Bots usually announce a desktop user agent, so a bot wave lowers mobile share. Rule that out before reading a falling share as a change in shoppers.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mobile-session-share","name":"Mobile session share","aliases":["Mobile traffic share","Mobile share of traffic","Mobile traffic percentage","Mobile sessions"],"family":"traffic","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of the week's sessions that happened on a phone, not counting tablets.","formula":"Sessions on a mobile device ÷ all sessions"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$device_type","description":"Mobile, Desktop or Tablet, parsed from the user agent."},{"name":"$session_id","description":"Set by the analytics SDK; ties the page view to a visit."},{"name":"utm_source","description":"The campaign source from the landing URL (google, facebook, tiktok)."}]}],"numerator":{"label":"Mobile sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"sessions a week","typical":0.7,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"app","level":0.78,"volume":150000,"trend":0.02},"drivers":[{"id":"tracking","label":"Device detection and bots","breakdown":"$browser","dropped":{"check":"Is a desktop bot or crawler adding sessions, or did a user-agent change reclassify phones?","yes":"Desktop sessions jump from one browser or data-centre network that never orders."},"spiked":{"check":"Did an in-app browser, a tracking fix or a mobile bot start counting more phone sessions?","yes":"Mobile sessions rise from one browser or app webview while orders hold."}},{"id":"calendar","label":"Calendar","feed":"holidays","dropped":{"check":"Did a holiday or long weekend end, sending people back to desks?","yes":"The same weeks last year show the same shift back to desktop."},"spiked":{"check":"Is this a holiday or vacation week, when people browse from phones?","yes":"The same week last year shows the same rise in mobile share."}},{"id":"paid-social","label":"Paid social","metric":"paid-sessions","breakdown":"utm_source","dropped":{"check":"Did paid social spend, which is almost all mobile, fall or pause?","yes":"Sessions from Meta, TikTok or Snap fall and the mobile share falls with them."},"spiked":{"check":"Did a paid social campaign or creator push start?","yes":"Sessions from a social source jump and nearly all of them are on phones."}},{"id":"email-and-sms","label":"Email and SMS sends","breakdown":"utm_medium","dropped":{"check":"Did fewer email or SMS sends go out this week?","yes":"Email and SMS sessions, mostly on phones, fall by enough to explain the shift."},"spiked":{"check":"Did a big email or SMS campaign go out?","yes":"Sessions tagged email or sms jump on the send days, mostly on phones."}},{"id":"desktop-sources","label":"Desktop-heavy sources","metric":"organic-sessions","dropped":{"check":"Did search, B2B or work-hours traffic, which skews desktop, grow?","yes":"Desktop sessions rise from search or one referrer while mobile holds."},"spiked":{"check":"Did desktop-heavy sources such as search or a partner site shrink?","yes":"Desktop sessions fall from one source while mobile holds."}}],"diagnose_order":["tracking","calendar","paid-social","email-and-sms","desktop-sources"],"related":["sessions","mobile-conversion-rate","conversion-rate","bounce-rate","paid-sessions"],"prose":{"why_it_matters":"Phones bring most store visits but convert at about half the desktop rate, so the device mix moves store conversion with no change to the site. When mobile share rises from 70% to 75%, a store converting 1.8% on mobile and 3.6% on desktop loses about 0.09 points of conversion from the mix alone. Check this before blaming checkout.","pitfalls":["Tablets are not mobile here. Tools that fold tablets into mobile read 3 to 8 points higher.","Device type comes from the user agent. Browser changes such as reduced user-agent strings and in-app webviews can move sessions between devices without anyone changing what they use.","The share can rise because desktop fell. Read it with mobile and desktop session counts side by side.","Bots usually announce a desktop user agent, so a bot wave lowers mobile share. Rule that out before reading a falling share as a change in shoppers."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mrr": { yaml: "id: mrr\nname: Monthly recurring revenue\naliases:\n  - MRR\n  - Monthly recurring revenue (MRR)\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.\n  formula: Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR at week end\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- MRR at the end of each of the last 26 weeks: each subscription's latest state before the week closed.\n    SELECT toString(week) AS week, sum(mrr) AS value\n    FROM (\n      SELECT\n        w.week AS week,\n        e.subscription_id AS subscription_id,\n        argMax(e.mrr, e.ts) AS mrr,\n        argMax(e.status, e.ts) AS status\n      FROM (\n        SELECT arrayJoin(arrayMap(i -> toMonday(now()) - toIntervalWeek(i), range(1, 27))) AS week\n      ) AS w\n      CROSS JOIN (\n        SELECT\n          toString(properties.subscription_id) AS subscription_id,\n          toFloat(properties.mrr) AS mrr,\n          toString(properties.status) AS status,\n          timestamp AS ts\n        FROM events\n        WHERE event = 'subscription_updated'\n      ) AS e\n      WHERE e.ts < w.week + toIntervalWeek(1)\n      GROUP BY week, subscription_id\n    )\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- MRR at the end of each week from a subscription change log.\n    WITH weeks AS (\n      SELECT generate_series(\n        date_trunc('week', now() - interval '26 weeks'),\n        date_trunc('week', now()) - interval '1 week',\n        interval '1 week'\n      ) AS week\n    ),\n    latest AS (\n      SELECT DISTINCT ON (w.week, e.properties->>'subscription_id')\n        w.week,\n        (e.properties->>'mrr')::numeric AS mrr,\n        e.properties->>'status' AS status\n      FROM weeks w\n      JOIN events e\n        ON e.event_name = 'subscription_updated'\n       AND e.occurred_at < w.week + interval '1 week'\n      ORDER BY w.week, e.properties->>'subscription_id', e.occurred_at DESC\n    )\n    SELECT week::date AS week, sum(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- MRR at the end of each week from a subscription change log.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(\n        DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 26 WEEK), ISOWEEK),\n        DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK),\n        INTERVAL 1 WEEK\n      )) AS week\n    ),\n    latest AS (\n      SELECT\n        w.week,\n        JSON_VALUE(e.properties, '$.subscription_id') AS subscription_id,\n        CAST(JSON_VALUE(e.properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(e.properties, '$.status') AS status\n      FROM weeks AS w\n      JOIN events AS e\n        ON e.event_name = 'subscription_updated'\n       AND DATE(e.occurred_at) < DATE_ADD(w.week, INTERVAL 1 WEEK)\n      QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY w.week, JSON_VALUE(e.properties, '$.subscription_id')\n        ORDER BY e.occurred_at DESC\n      ) = 1\n    )\n    SELECT week, SUM(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- MRR at the end of each week from a subscription change log. Assumes WEEK_START = 1 (Monday).\n    WITH weeks AS (\n      SELECT DATEADD(week, -SEQ4(), DATE_TRUNC('week', DATEADD(week, -1, CURRENT_DATE()))) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    latest AS (\n      SELECT\n        w.week,\n        e.properties:subscription_id::string AS subscription_id,\n        e.properties:mrr::float AS mrr,\n        e.properties:status::string AS status\n      FROM weeks AS w\n      JOIN events AS e\n        ON e.event_name = 'subscription_updated'\n       AND e.occurred_at < DATEADD(week, 1, w.week)\n      QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY w.week, e.properties:subscription_id::string\n        ORDER BY e.occurred_at DESC\n      ) = 1\n    )\n    SELECT week, SUM(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: active subscriptions\n  typical: 180000\n\nexample:\n  business: saas\n  level: 240000\n  volume: 1900\n  trend: 0.35\n\ndrivers:\n  - id: new-mrr\n    label: New MRR\n    metric: new-mrr\n    dropped:\n      check: Did fewer new customers start paying, or start on smaller plans?\n      yes: New MRR falls below its usual range while churn holds.\n    spiked:\n      check: Did a launch, a sales push or one large deal add new MRR?\n      yes: New MRR jumps; check whether one customer accounts for most of it.\n  - id: expansion\n    label: Expansion\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow?\n      yes: Expansion MRR falls while new and churned MRR hold.\n    spiked:\n      check: Did a price change or a usage limit push customers to upgrade?\n      yes: Expansion MRR jumps in the week the change shipped.\n  - id: churn\n    label: Churned and contracted MRR\n    metric: churned-mrr\n    feed: stripe\n    dropped:\n      check: Did cancellations, downgrades or failed renewals rise?\n      yes: Churned MRR rises; failed payments or one large account explain most of it.\n    spiked:\n      check: Did churn fall unusually low, or did failed payments recover?\n      yes: Churned MRR falls and recovered dunning payments appear.\n  - id: billing-calendar\n    label: Billing calendar\n    dropped:\n      check: Did a cohort of annual plans come up for renewal this week?\n      yes: A cluster of renewals dated one year after a big signup month.\n    spiked:\n      check: Is a migration or a currency revaluation changing amounts without customers acting?\n      yes: Many subscriptions change amount on the same day with no plan change.\n\ndiagnose_order: [billing-calendar, churn, new-mrr, expansion]\n\nrelated: [new-mrr, expansion-mrr, churned-mrr, net-new-mrr, arpa]\n\nprose:\n  why_it_matters: >-\n    MRR is the stock that every other subscription number flows into: new and expansion MRR\n    add to it, churn and contraction take from it. Because it is a stock, it barely moves week\n    to week, which is exactly why a small move matters. Read its flows to see why it moved;\n    read MRR itself to see whether the business is growing.\n  pitfalls:\n    - Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.\n    - Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.\n    - Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.\n    - A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mrr","name":"Monthly recurring revenue","aliases":["MRR","Monthly recurring revenue (MRR)"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.","formula":"Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR at week end","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- MRR at the end of each of the last 26 weeks: each subscription's latest state before the week closed.\nSELECT toString(week) AS week, sum(mrr) AS value\nFROM (\n  SELECT\n    w.week AS week,\n    e.subscription_id AS subscription_id,\n    argMax(e.mrr, e.ts) AS mrr,\n    argMax(e.status, e.ts) AS status\n  FROM (\n    SELECT arrayJoin(arrayMap(i -> toMonday(now()) - toIntervalWeek(i), range(1, 27))) AS week\n  ) AS w\n  CROSS JOIN (\n    SELECT\n      toString(properties.subscription_id) AS subscription_id,\n      toFloat(properties.mrr) AS mrr,\n      toString(properties.status) AS status,\n      timestamp AS ts\n    FROM events\n    WHERE event = 'subscription_updated'\n  ) AS e\n  WHERE e.ts < w.week + toIntervalWeek(1)\n  GROUP BY week, subscription_id\n)\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week","postgres":"-- MRR at the end of each week from a subscription change log.\nWITH weeks AS (\n  SELECT generate_series(\n    date_trunc('week', now() - interval '26 weeks'),\n    date_trunc('week', now()) - interval '1 week',\n    interval '1 week'\n  ) AS week\n),\nlatest AS (\n  SELECT DISTINCT ON (w.week, e.properties->>'subscription_id')\n    w.week,\n    (e.properties->>'mrr')::numeric AS mrr,\n    e.properties->>'status' AS status\n  FROM weeks w\n  JOIN events e\n    ON e.event_name = 'subscription_updated'\n   AND e.occurred_at < w.week + interval '1 week'\n  ORDER BY w.week, e.properties->>'subscription_id', e.occurred_at DESC\n)\nSELECT week::date AS week, sum(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;","bigquery":"-- MRR at the end of each week from a subscription change log.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(\n    DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 26 WEEK), ISOWEEK),\n    DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK),\n    INTERVAL 1 WEEK\n  )) AS week\n),\nlatest AS (\n  SELECT\n    w.week,\n    JSON_VALUE(e.properties, '$.subscription_id') AS subscription_id,\n    CAST(JSON_VALUE(e.properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(e.properties, '$.status') AS status\n  FROM weeks AS w\n  JOIN events AS e\n    ON e.event_name = 'subscription_updated'\n   AND DATE(e.occurred_at) < DATE_ADD(w.week, INTERVAL 1 WEEK)\n  QUALIFY ROW_NUMBER() OVER (\n    PARTITION BY w.week, JSON_VALUE(e.properties, '$.subscription_id')\n    ORDER BY e.occurred_at DESC\n  ) = 1\n)\nSELECT week, SUM(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;","snowflake":"-- MRR at the end of each week from a subscription change log. Assumes WEEK_START = 1 (Monday).\nWITH weeks AS (\n  SELECT DATEADD(week, -SEQ4(), DATE_TRUNC('week', DATEADD(week, -1, CURRENT_DATE()))) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nlatest AS (\n  SELECT\n    w.week,\n    e.properties:subscription_id::string AS subscription_id,\n    e.properties:mrr::float AS mrr,\n    e.properties:status::string AS status\n  FROM weeks AS w\n  JOIN events AS e\n    ON e.event_name = 'subscription_updated'\n   AND e.occurred_at < DATEADD(week, 1, w.week)\n  QUALIFY ROW_NUMBER() OVER (\n    PARTITION BY w.week, e.properties:subscription_id::string\n    ORDER BY e.occurred_at DESC\n  ) = 1\n)\nSELECT week, SUM(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;"},"noise":{"type":"process","min_denominator":20,"volume_unit":"active subscriptions","typical":180000},"example":{"business":"saas","level":240000,"volume":1900,"trend":0.35},"drivers":[{"id":"new-mrr","label":"New MRR","metric":"new-mrr","dropped":{"check":"Did fewer new customers start paying, or start on smaller plans?","yes":"New MRR falls below its usual range while churn holds."},"spiked":{"check":"Did a launch, a sales push or one large deal add new MRR?","yes":"New MRR jumps; check whether one customer accounts for most of it."}},{"id":"expansion","label":"Expansion","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow?","yes":"Expansion MRR falls while new and churned MRR hold."},"spiked":{"check":"Did a price change or a usage limit push customers to upgrade?","yes":"Expansion MRR jumps in the week the change shipped."}},{"id":"churn","label":"Churned and contracted MRR","metric":"churned-mrr","feed":"stripe","dropped":{"check":"Did cancellations, downgrades or failed renewals rise?","yes":"Churned MRR rises; failed payments or one large account explain most of it."},"spiked":{"check":"Did churn fall unusually low, or did failed payments recover?","yes":"Churned MRR falls and recovered dunning payments appear."}},{"id":"billing-calendar","label":"Billing calendar","dropped":{"check":"Did a cohort of annual plans come up for renewal this week?","yes":"A cluster of renewals dated one year after a big signup month."},"spiked":{"check":"Is a migration or a currency revaluation changing amounts without customers acting?","yes":"Many subscriptions change amount on the same day with no plan change."}}],"diagnose_order":["billing-calendar","churn","new-mrr","expansion"],"related":["new-mrr","expansion-mrr","churned-mrr","net-new-mrr","arpa"],"prose":{"why_it_matters":"MRR is the stock that every other subscription number flows into: new and expansion MRR add to it, churn and contraction take from it. Because it is a stock, it barely moves week to week, which is exactly why a small move matters. Read its flows to see why it moved; read MRR itself to see whether the business is growing.","pitfalls":["Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.","Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.","Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.","A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "ncac": { yaml: "id: ncac\nname: New customer acquisition cost\naliases:\n  - nCAC\n  - NCPA\n  - New customer CPA\n  - Cost per new customer\nfamily: acquisition\ncatalog_id: ncac\nkind: currency\npolarity: down-is-good\n\ndefinition:\n  one_line: Ad spend in the week divided by the customers who placed their first ever order that week.\n  formula: Ad spend ÷ first orders\n\nevents:\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n      - name: channel\n        description: The platform (google, meta, tiktok, microsoft, pinterest).\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: is_first_order\n        description: True when this is the customer's first ever paid order, by email or customer id, across guest and account checkouts.\n      - name: customer_id\n        description: The store's customer id, stable across orders.\n\nnumerator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\ndenominator:\n  label: First orders\n  aggregate: count\n  event: order_completed\n  where:\n    - property: is_first_order\n      op: eq\n      value: true\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: new customers a week\n  typical: 55\n\nexample:\n  business: store\n  level: 58\n  volume: 5200\n  trend: 0.12\n\ndrivers:\n  - id: data\n    label: Spend and first-order data\n    dropped:\n      check: Is spend missing for a channel, or are returning customers being flagged as first orders?\n      yes: One channel's spend has gaps, or first orders jump while total orders hold, often after a platform or checkout migration.\n    spiked:\n      check: Is spend synced twice, or did a change stop first orders being flagged?\n      yes: One channel's spend doubles for a day, or first orders fall to near zero while total orders hold.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is this a sale or gifting week that brings in first-time buyers at the same spend?\n      yes: First orders jump in the event week and the same week last year shows the same fall in nCAC.\n    spiked:\n      check: Did a sale end, or is spend rising ahead of an event before buyers arrive?\n      yes: The same weeks last year show the same rise once aligned on the event.\n  - id: new-customers\n    label: New customers\n    metric: new-customers\n    dropped:\n      check: Did more first-time customers order at steady spend?\n      yes: New customers rise by about as much as nCAC falls.\n    spiked:\n      check: Did fewer first-time customers order at steady spend?\n      yes: New customers fall by about as much as nCAC rises; check paid conversion and traffic next.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall, cutting the least efficient campaigns first?\n      yes: Spend falls more than new customers do.\n    spiked:\n      check: Did a budget increase or a new prospecting campaign add spend faster than customers?\n      yes: Spend rises on one channel while new customers grow less; scaling usually raises nCAC.\n  - id: cpm\n    label: Price of attention\n    metric: cpm\n    dropped:\n      check: Did impressions get cheaper across platforms?\n      yes: CPM falls by about as much as nCAC, while click-through and conversion hold.\n    spiked:\n      check: Did impressions get more expensive, as they do in Q4?\n      yes: CPM rises by about as much as nCAC, while click-through and conversion hold.\n  - id: paid-conversion\n    label: Paid conversion rate\n    metric: paid-conversion-rate\n    dropped:\n      check: Did more paid visits turn into first orders?\n      yes: Paid conversion rises while CPC holds.\n    spiked:\n      check: Did fewer paid visits order, from a landing page, offer, stock or checkout problem?\n      yes: Paid conversion falls while CPC holds.\n\ndiagnose_order: [data, calendar, new-customers, spend, cpm, paid-conversion]\n\nrelated: [blended-cac, mer, ad-spend, new-customers, ltv-to-cac, cpm]\n\nprose:\n  why_it_matters: >-\n    nCAC is the price of growth for a store: what the ads cost for each customer who had never\n    bought before. Returning customers are left out of the denominator, so it can't be flattered\n    by a loyal base the way MER can. At $58 per new customer and a $100 first order with 60%\n    gross margin, the first order alone pays the ad back with $2 to spare.\n  pitfalls:\n    - Ad spend divided by all orders is cost per order, not nCAC. Including returning customers makes acquisition look two or three times cheaper on a store with a strong repeat base.\n    - All new customers are in the denominator, including those from organic search, email signups and word of mouth. A week with a press mention lowers nCAC without the ads doing anything.\n    - First orders need one customer identity across guest and account checkouts. Matching by email misses people who buy again with a different address and makes them new twice.\n    - Spend in one week buys customers over the next several. Weekly nCAC swings when budgets change fast; read a four-week view before cutting a channel.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"ncac","name":"New customer acquisition cost","aliases":["nCAC","NCPA","New customer CPA","Cost per new customer"],"family":"acquisition","catalog_id":"ncac","kind":"currency","polarity":"down-is-good","definition":{"one_line":"Ad spend in the week divided by the customers who placed their first ever order that week.","formula":"Ad spend ÷ first orders"},"events":[{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."},{"name":"channel","description":"The platform (google, meta, tiktok, microsoft, pinterest)."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"is_first_order","description":"True when this is the customer's first ever paid order, by email or customer id, across guest and account checkouts."},{"name":"customer_id","description":"The store's customer id, stable across orders."}]}],"numerator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"denominator":{"label":"First orders","aggregate":"count","event":"order_completed","where":[{"property":"is_first_order","op":"eq","value":true}]},"noise":{"type":"process","min_denominator":20,"volume_unit":"new customers a week","typical":55},"example":{"business":"store","level":58,"volume":5200,"trend":0.12},"drivers":[{"id":"data","label":"Spend and first-order data","dropped":{"check":"Is spend missing for a channel, or are returning customers being flagged as first orders?","yes":"One channel's spend has gaps, or first orders jump while total orders hold, often after a platform or checkout migration."},"spiked":{"check":"Is spend synced twice, or did a change stop first orders being flagged?","yes":"One channel's spend doubles for a day, or first orders fall to near zero while total orders hold."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is this a sale or gifting week that brings in first-time buyers at the same spend?","yes":"First orders jump in the event week and the same week last year shows the same fall in nCAC."},"spiked":{"check":"Did a sale end, or is spend rising ahead of an event before buyers arrive?","yes":"The same weeks last year show the same rise once aligned on the event."}},{"id":"new-customers","label":"New customers","metric":"new-customers","dropped":{"check":"Did more first-time customers order at steady spend?","yes":"New customers rise by about as much as nCAC falls."},"spiked":{"check":"Did fewer first-time customers order at steady spend?","yes":"New customers fall by about as much as nCAC rises; check paid conversion and traffic next."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall, cutting the least efficient campaigns first?","yes":"Spend falls more than new customers do."},"spiked":{"check":"Did a budget increase or a new prospecting campaign add spend faster than customers?","yes":"Spend rises on one channel while new customers grow less; scaling usually raises nCAC."}},{"id":"cpm","label":"Price of attention","metric":"cpm","dropped":{"check":"Did impressions get cheaper across platforms?","yes":"CPM falls by about as much as nCAC, while click-through and conversion hold."},"spiked":{"check":"Did impressions get more expensive, as they do in Q4?","yes":"CPM rises by about as much as nCAC, while click-through and conversion hold."}},{"id":"paid-conversion","label":"Paid conversion rate","metric":"paid-conversion-rate","dropped":{"check":"Did more paid visits turn into first orders?","yes":"Paid conversion rises while CPC holds."},"spiked":{"check":"Did fewer paid visits order, from a landing page, offer, stock or checkout problem?","yes":"Paid conversion falls while CPC holds."}}],"diagnose_order":["data","calendar","new-customers","spend","cpm","paid-conversion"],"related":["blended-cac","mer","ad-spend","new-customers","ltv-to-cac","cpm"],"prose":{"why_it_matters":"nCAC is the price of growth for a store: what the ads cost for each customer who had never bought before. Returning customers are left out of the denominator, so it can't be flattered by a loyal base the way MER can. At $58 per new customer and a $100 first order with 60% gross margin, the first order alone pays the ad back with $2 to spare.","pitfalls":["Ad spend divided by all orders is cost per order, not nCAC. Including returning customers makes acquisition look two or three times cheaper on a store with a strong repeat base.","All new customers are in the denominator, including those from organic search, email signups and word of mouth. A week with a press mention lowers nCAC without the ads doing anything.","First orders need one customer identity across guest and account checkouts. Matching by email misses people who buy again with a different address and makes them new twice.","Spend in one week buys customers over the next several. Weekly nCAC swings when budgets change fast; read a four-week view before cutting a channel."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "net-revenue": { yaml: "id: net-revenue\nname: Net revenue\naliases:\n  - Weekly revenue\n  - Net sales\nfamily: revenue\ncatalog_id: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue after discounts and refunds, before tax and shipping, for orders paid this week.\n  formula: Sum of order totals − refunds issued, excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n\nnumerator:\n  label: Net revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 400000\n\nexample:\n  business: store\n  level: 1300000\n  volume: 13000\n  trend: 0.2\n  season: 1\n\ndrivers:\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth?\n      yes: Orders fall by about as much as revenue while order value holds.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as revenue while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did the average order shrink, from a discount, a mix shift or fewer items per order?\n      yes: Order value falls while the number of orders holds.\n    spiked:\n      check: Did a few large orders or a price rise lift the average?\n      yes: Order value jumps, often driven by a handful of orders far above the usual size.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors?\n      yes: Sessions rise in one channel, and conversion holds.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which step?\n      yes: Conversion falls while traffic holds; one funnel step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which step?\n      yes: Conversion rises while traffic holds; one funnel step explains most of it.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?\n      yes: Gross sales hold while refunds rise.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refunds return to their usual share and net revenue recovers.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is last week's comparison a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this week a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n\ndiagnose_order: [calendar, orders, order-value, traffic, conversion, refunds]\n\nrelated: [orders, aov, conversion-rate, gross-sales, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Revenue is the number everyone reads first, which is why it is the worst number to act on\n    alone. It is orders times order value, and orders are traffic times conversion; a move in\n    revenue is only useful once you know which of those moved. Most weeks, nothing did, and the\n    honest answer is that the change is the ordinary wobble of a few thousand orders.\n  pitfalls:\n    - Booking revenue when the order is placed but refunds when they are issued mixes two weeks. Report both by the week they happen and say so.\n    - Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.\n    - A few very large orders can move a small store's week by 10% or more. Check the order count before the total.\n    - Revenue in several currencies needs one fixed exchange rate per week, or currency moves look like sales.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"net-revenue","name":"Net revenue","aliases":["Weekly revenue","Net sales"],"family":"revenue","catalog_id":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue after discounts and refunds, before tax and shipping, for orders paid this week.","formula":"Sum of order totals − refunds issued, excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]}],"numerator":{"label":"Net revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":400000},"example":{"business":"store","level":1300000,"volume":13000,"trend":0.2,"season":1},"drivers":[{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth?","yes":"Orders fall by about as much as revenue while order value holds."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as revenue while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did the average order shrink, from a discount, a mix shift or fewer items per order?","yes":"Order value falls while the number of orders holds."},"spiked":{"check":"Did a few large orders or a price rise lift the average?","yes":"Order value jumps, often driven by a handful of orders far above the usual size."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors?","yes":"Sessions rise in one channel, and conversion holds."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which step?","yes":"Conversion falls while traffic holds; one funnel step explains most of it."},"spiked":{"check":"Did more visits buy, and at which step?","yes":"Conversion rises while traffic holds; one funnel step explains most of it."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?","yes":"Gross sales hold while refunds rise."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refunds return to their usual share and net revenue recovers."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is last week's comparison a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this week a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}}],"diagnose_order":["calendar","orders","order-value","traffic","conversion","refunds"],"related":["orders","aov","conversion-rate","gross-sales","refund-rate"],"prose":{"why_it_matters":"Revenue is the number everyone reads first, which is why it is the worst number to act on alone. It is orders times order value, and orders are traffic times conversion; a move in revenue is only useful once you know which of those moved. Most weeks, nothing did, and the honest answer is that the change is the ordinary wobble of a few thousand orders.","pitfalls":["Booking revenue when the order is placed but refunds when they are issued mixes two weeks. Report both by the week they happen and say so.","Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.","A few very large orders can move a small store's week by 10% or more. Check the order count before the total.","Revenue in several currencies needs one fixed exchange rate per week, or currency moves look like sales."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "new-visitor-share": { yaml: "id: new-visitor-share\nname: New visitor share\naliases:\n  - New visitor rate\n  - Percent new visitors\n  - New vs returning visitors\nfamily: traffic\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of the week's unique visitors who had never viewed a page on the site before.\n  formula: Visitors whose first ever page view is this week ÷ unique visitors this week\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_source\n        description: The campaign source from the landing URL (google, facebook, newsletter).\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n\nnumerator:\n  label: First-time visitors\n  aggregate: first_time_users\n  event: $pageview\ndenominator:\n  label: Unique visitors\n  aggregate: unique_users\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 200\n  volume_unit: visitors a week\n  typical: 0.65\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.64\n  volume: 390000\n  trend: -0.03\n\ndrivers:\n  - id: identity\n    label: Cookies and identity\n    breakdown: $browser\n    dropped:\n      check: Did a login, identity merge or tracking fix start recognising people who used to look new?\n      yes: The share falls on the day of the change while sessions and orders hold.\n    spiked:\n      check: Did cookies start resetting, from a consent change, a new domain or a browser update?\n      yes: The share jumps in one browser, sessions per visitor fall, and returning customers suddenly look new.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did a gifting or sale period end, leaving mostly regulars?\n      yes: The same weeks last year show the same fall after the event.\n    spiked:\n      check: Is this a gifting or sale week that brings people who don't usually visit?\n      yes: The same week last year shows the same rise.\n  - id: prospecting\n    label: Prospecting spend\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did prospecting campaigns pause or shift budget to retargeting?\n      yes: Paid sessions fall, or their mix moves toward retargeting audiences.\n    spiked:\n      check: Did a new prospecting campaign or a budget increase start?\n      yes: Paid sessions rise from one platform and most of them are first visits.\n  - id: email\n    label: Email and returning traffic\n    metric: email-click-rate\n    dropped:\n      check: Did a big email or SMS send bring regulars back, diluting the share?\n      yes: Returning visitors jump on send days while first-time visitors hold.\n    spiked:\n      check: Did the usual emails go out less, so fewer regulars came back?\n      yes: Email-driven sessions fall while first-time visitors hold.\n  - id: press-and-referrals\n    label: Press and referrals\n    metric: referral-sessions\n    dropped:\n      check: Did a referral source that sends new people dry up?\n      yes: One referring domain that sent first visits has stopped.\n    spiked:\n      check: Did a press piece, creator post or viral link send a wave of new people?\n      yes: One referring domain explains most of the first visits and fades within days.\n\ndiagnose_order: [identity, calendar, prospecting, email, press-and-referrals]\n\nrelated: [unique-visitors, sessions, returning-customers, new-customers, paid-sessions]\n\nprose:\n  why_it_matters: >-\n    A store grows only if new people keep finding it, and this share shows whether this week's\n    traffic is reach or the same regulars coming back. It also explains other moves: new\n    visitors convert at a fraction of returning ones, so when the share jumps from 70% to 78%,\n    expect store conversion to dip with no change to the site.\n  pitfalls:\n    - A new visitor is new to this browser's cookie. Cleared cookies, private browsing, a second device and Safari's seven-day cookie limit all make returning people look new, so the share runs high.\n    - A share can rise with no new people at all, when returning visitors fall. Read it next to the count of first-time visitors.\n    - The first-visit test needs the full history. A query limited to recent months calls everyone seen before that window new.\n    - Changing the domain, the analytics project or the cookie name resets everyone to new for months.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"new-visitor-share","name":"New visitor share","aliases":["New visitor rate","Percent new visitors","New vs returning visitors"],"family":"traffic","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of the week's unique visitors who had never viewed a page on the site before.","formula":"Visitors whose first ever page view is this week ÷ unique visitors this week"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_source","description":"The campaign source from the landing URL (google, facebook, newsletter)."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."}]}],"numerator":{"label":"First-time visitors","aggregate":"first_time_users","event":"$pageview"},"denominator":{"label":"Unique visitors","aggregate":"unique_users","event":"$pageview"},"noise":{"type":"binomial","min_denominator":200,"volume_unit":"visitors a week","typical":0.65,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.64,"volume":390000,"trend":-0.03},"drivers":[{"id":"identity","label":"Cookies and identity","breakdown":"$browser","dropped":{"check":"Did a login, identity merge or tracking fix start recognising people who used to look new?","yes":"The share falls on the day of the change while sessions and orders hold."},"spiked":{"check":"Did cookies start resetting, from a consent change, a new domain or a browser update?","yes":"The share jumps in one browser, sessions per visitor fall, and returning customers suddenly look new."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did a gifting or sale period end, leaving mostly regulars?","yes":"The same weeks last year show the same fall after the event."},"spiked":{"check":"Is this a gifting or sale week that brings people who don't usually visit?","yes":"The same week last year shows the same rise."}},{"id":"prospecting","label":"Prospecting spend","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did prospecting campaigns pause or shift budget to retargeting?","yes":"Paid sessions fall, or their mix moves toward retargeting audiences."},"spiked":{"check":"Did a new prospecting campaign or a budget increase start?","yes":"Paid sessions rise from one platform and most of them are first visits."}},{"id":"email","label":"Email and returning traffic","metric":"email-click-rate","dropped":{"check":"Did a big email or SMS send bring regulars back, diluting the share?","yes":"Returning visitors jump on send days while first-time visitors hold."},"spiked":{"check":"Did the usual emails go out less, so fewer regulars came back?","yes":"Email-driven sessions fall while first-time visitors hold."}},{"id":"press-and-referrals","label":"Press and referrals","metric":"referral-sessions","dropped":{"check":"Did a referral source that sends new people dry up?","yes":"One referring domain that sent first visits has stopped."},"spiked":{"check":"Did a press piece, creator post or viral link send a wave of new people?","yes":"One referring domain explains most of the first visits and fades within days."}}],"diagnose_order":["identity","calendar","prospecting","email","press-and-referrals"],"related":["unique-visitors","sessions","returning-customers","new-customers","paid-sessions"],"prose":{"why_it_matters":"A store grows only if new people keep finding it, and this share shows whether this week's traffic is reach or the same regulars coming back. It also explains other moves: new visitors convert at a fraction of returning ones, so when the share jumps from 70% to 78%, expect store conversion to dip with no change to the site.","pitfalls":["A new visitor is new to this browser's cookie. Cleared cookies, private browsing, a second device and Safari's seven-day cookie limit all make returning people look new, so the share runs high.","A share can rise with no new people at all, when returning visitors fall. Read it next to the count of first-time visitors.","The first-visit test needs the full history. A query limited to recent months calls everyone seen before that window new.","Changing the domain, the analytics project or the cookie name resets everyone to new for months."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "orders": { yaml: "id: orders\nname: Orders\naliases:\n  - Order count\n  - Weekly orders\n  - Number of orders\n  - Paid orders\n  - Transactions\nfamily: revenue\ncatalog_id: orders\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of paid orders placed in the week, each counted once, before any refunds.\n  formula: Count of paid orders, by the week they were paid\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server or the payment processor, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: poisson\n  min_denominator: 30\n  volume_unit: orders a week\n  typical: 3000\n\nexample:\n  business: store\n  level: 13300\n  volume: 13300\n  trend: 0.2\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did recorded orders fall while the store platform or payment processor shows the usual count?\n      yes: The processor's order count holds, often after a checkout, consent or tag change.\n    spiked:\n      check: Are orders duplicated by thank-you page reloads or webhook retries, or are test orders included?\n      yes: Recorded orders exceed the processor's count, or the same order_id appears more than once.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week, or is this the week before one?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: payments\n    label: Payment outages\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did a processor incident or a fraud rule block payments for part of the week?\n      yes: Payment success falls for one gateway or method during the hours orders are missing.\n    spiked:\n      check: Did a payment problem from the week before clear?\n      yes: Payment success returns to its usual level and orders recover with it.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do, while conversion holds.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors who buy?\n      yes: Sessions rise in one channel and conversion holds; a bot wave would lift sessions but not orders.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which funnel step?\n      yes: Conversion falls while traffic holds; one step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which funnel step?\n      yes: Conversion rises while traffic holds; one step explains most of it.\n  - id: first-orders\n    label: First vs repeat orders\n    metric: new-customers\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders fall, after an ad budget cut or a campaign ending, while repeat orders held?\n      yes: New customers fall by about as much as orders.\n    spiked:\n      check: Did an email, a launch or a restock bring back past customers?\n      yes: Repeat orders jump while first orders hold.\n\ndiagnose_order: [tracking, calendar, payments, traffic, conversion, first-orders]\n\nrelated: [net-revenue, aov, conversion-rate, sessions, new-customers]\n\nprose:\n  why_it_matters: >-\n    Orders are the store's heartbeat, a count of decisions to buy, free of price and basket\n    effects. Because they are a count, chance alone moves them by about 2.8 ÷ √N: a store with\n    800 orders a week swings ±10% on noise, while Northwind's 13,300 swing about ±2.5%.\n  pitfalls:\n    - Count orders from the server or the payment processor, never from thank-you page views, which double count reloads and miss redirect payments.\n    - Removing fully refunded orders rewrites past weeks for a month or more after they close. This spec counts orders when paid and reads refunds in refund rate.\n    - Test orders, draft orders and $0 replacement orders inflate the count. Flag them at the source rather than filtering in every query.\n    - Subscription renewals and marketplace orders follow their own calendars; mixed in with site orders, a renewal date looks like a sales spike.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"orders","name":"Orders","aliases":["Order count","Weekly orders","Number of orders","Paid orders","Transactions"],"family":"revenue","catalog_id":"orders","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of paid orders placed in the week, each counted once, before any refunds.","formula":"Count of paid orders, by the week they were paid"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server or the payment processor, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"poisson","min_denominator":30,"volume_unit":"orders a week","typical":3000},"example":{"business":"store","level":13300,"volume":13300,"trend":0.2},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did recorded orders fall while the store platform or payment processor shows the usual count?","yes":"The processor's order count holds, often after a checkout, consent or tag change."},"spiked":{"check":"Are orders duplicated by thank-you page reloads or webhook retries, or are test orders included?","yes":"Recorded orders exceed the processor's count, or the same order_id appears more than once."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week, or is this the week before one?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"payments","label":"Payment outages","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did a processor incident or a fraud rule block payments for part of the week?","yes":"Payment success falls for one gateway or method during the hours orders are missing."},"spiked":{"check":"Did a payment problem from the week before clear?","yes":"Payment success returns to its usual level and orders recover with it."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do, while conversion holds."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors who buy?","yes":"Sessions rise in one channel and conversion holds; a bot wave would lift sessions but not orders."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which funnel step?","yes":"Conversion falls while traffic holds; one step explains most of it."},"spiked":{"check":"Did more visits buy, and at which funnel step?","yes":"Conversion rises while traffic holds; one step explains most of it."}},{"id":"first-orders","label":"First vs repeat orders","metric":"new-customers","breakdown":"is_first_order","dropped":{"check":"Did first orders fall, after an ad budget cut or a campaign ending, while repeat orders held?","yes":"New customers fall by about as much as orders."},"spiked":{"check":"Did an email, a launch or a restock bring back past customers?","yes":"Repeat orders jump while first orders hold."}}],"diagnose_order":["tracking","calendar","payments","traffic","conversion","first-orders"],"related":["net-revenue","aov","conversion-rate","sessions","new-customers"],"prose":{"why_it_matters":"Orders are the store's heartbeat, a count of decisions to buy, free of price and basket effects. Because they are a count, chance alone moves them by about 2.8 ÷ √N: a store with 800 orders a week swings ±10% on noise, while Northwind's 13,300 swing about ±2.5%.","pitfalls":["Count orders from the server or the payment processor, never from thank-you page views, which double count reloads and miss redirect payments.","Removing fully refunded orders rewrites past weeks for a month or more after they close. This spec counts orders when paid and reads refunds in refund rate.","Test orders, draft orders and $0 replacement orders inflate the count. Flag them at the source rather than filtering in every query.","Subscription renewals and marketplace orders follow their own calendars; mixed in with site orders, a renewal date looks like a sales spike."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "organic-sessions": { yaml: "id: organic-sessions\nname: Organic search sessions\naliases:\n  - Organic traffic\n  - Organic search traffic\n  - SEO traffic\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits that arrived from an unpaid search result, judged by the first page of the visit.\n  formula: Sessions whose first page view came from a search engine, or is tagged utm_medium=organic, with no paid tag or ad click id\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; the session's first page view decides its channel.\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n      - name: utm_medium\n        description: The campaign medium from the landing URL. When set, it decides the channel.\n      - name: gclid\n        description: Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads. Marks the visit as paid.\n\nnumerator:\n  label: Organic search sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: is_not_set\n    - property: $referring_domain\n      op: in\n      value: [www.google.com, google.com, www.bing.com, duckduckgo.com, search.yahoo.com, yandex.ru, www.ecosia.org, search.brave.com]\n\nqueries:\n  hogql: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\n    SELECT week, count() AS value\n    FROM (\n      SELECT\n        $session_id AS session_id,\n        toMonday(min(timestamp)) AS week,\n        argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n        argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n        argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp) AS ad_click\n      FROM events\n      WHERE event = '$pageview'\n        AND $session_id IS NOT NULL\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY session_id\n    )\n    WHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      AND (medium = 'organic' OR (medium = '' AND match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\n    WITH entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at)::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      ORDER BY session_id, occurred_at\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n      AND (medium = 'organic' OR (medium = '' AND referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'))\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        lower(coalesce(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n        coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      AND (medium = 'organic' OR (medium = '' AND REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\n    -- Assumes WEEK_START = 1 (Monday).\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n        lower(coalesce(properties:\"$referring_domain\"::string, '')) AS referrer,\n        coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      AND (medium = 'organic' OR (medium = '' AND REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: organic sessions a week\n  typical: 12000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 125000\n  volume: 125000\n  trend: 0.08\n\ndrivers:\n  - id: classification\n    label: Tracking and channel rules\n    dropped:\n      check: Did a redirect, consent change or new domain strip the referrer, so search visits now look direct?\n      yes: Direct sessions rise by about as much as organic falls, from the day of the change.\n    spiked:\n      check: Did paid search lose its tags, so ad clicks now count as organic?\n      yes: Paid search sessions fall by about as much as organic rises, often after auto-tagging was switched off or a redirect dropped the click id.\n  - id: google-update\n    label: Google updates and results pages\n    feed: google-search\n    dropped:\n      check: Did a core update, a ranking loss or an AI Overview start taking clicks from key queries?\n      yes: The fall starts on a dated update and concentrates on a few landing pages or query groups.\n    spiked:\n      check: Did a core update or a new results feature reward the site's pages?\n      yes: The rise starts on a dated update and holds for more than one week.\n  - id: calendar\n    label: Seasonal search demand\n    feed: shopping\n    dropped:\n      check: Did people simply search less for what the store sells, after a holiday or a season?\n      yes: The same weeks last year show the same fall once aligned on the event.\n    spiked:\n      check: Is this a gifting, sale or seasonal week when people search more?\n      yes: The same week last year shows the same rise.\n  - id: brand-demand\n    label: Branded searches\n    metric: paid-sessions\n    dropped:\n      check: Did advertising, press or a launch that drove people to search the brand name stop?\n      yes: Visits landing on the home page from search fall while product-page search visits hold.\n    spiked:\n      check: Did a campaign, a press piece or a creator post make people search the brand?\n      yes: The rise lands on the home page and brand queries, and fades when the campaign ends.\n  - id: landing-pages\n    label: Pages that rank\n    breakdown: $pathname\n    dropped:\n      check: Did a ranking page get removed, redirected, noindexed or slower?\n      yes: One or two landing paths account for most of the fall.\n    spiked:\n      check: Did a new or updated page start ranking for a valuable query?\n      yes: One or two landing paths account for most of the rise.\n\ndiagnose_order: [classification, google-update, calendar, brand-demand, landing-pages]\n\nrelated: [sessions, paid-sessions, referral-sessions, new-visitor-share, conversion-rate]\n\nprose:\n  why_it_matters: >-\n    Organic search is the traffic a store doesn't pay for each week, so it sets how much of\n    growth has to be bought. It also moves on dates you can look up: Google ships several core\n    updates a year, and a store with 125,000 organic sessions a week can lose 15% in the days\n    after one without changing a thing.\n  pitfalls:\n    - Google Ads auto-tagging adds a gclid but no UTM tags. Without checking the click id, paid search clicks land in organic and organic looks better than it is.\n    - Organic here means search engines only. Unpaid social posts, emails and links from other sites are separate channels, and GA4's \"Organic\" groups differ by tool.\n    - Visits from ChatGPT, Perplexity and other AI assistants arrive as referrals, not search. They are the fastest-growing source of non-paid visits for many stores; read them in referral sessions.\n    - Most search referrers carry no keyword, so this number can't tell branded from unbranded searches. Use Search Console for that split, and expect its clicks to differ from sessions by 10 to 20%.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"organic-sessions","name":"Organic search sessions","aliases":["Organic traffic","Organic search traffic","SEO traffic"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits that arrived from an unpaid search result, judged by the first page of the visit.","formula":"Sessions whose first page view came from a search engine, or is tagged utm_medium=organic, with no paid tag or ad click id"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; the session's first page view decides its channel."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."},{"name":"utm_medium","description":"The campaign medium from the landing URL. When set, it decides the channel."},{"name":"gclid","description":"Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads. Marks the visit as paid."}]}],"numerator":{"label":"Organic search sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"is_not_set"},{"property":"$referring_domain","op":"in","value":["www.google.com","google.com","www.bing.com","duckduckgo.com","search.yahoo.com","yandex.ru","www.ecosia.org","search.brave.com"]}]},"queries":{"hogql":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\nSELECT week, count() AS value\nFROM (\n  SELECT\n    $session_id AS session_id,\n    toMonday(min(timestamp)) AS week,\n    argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n    argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n    argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp) AS ad_click\n  FROM events\n  WHERE event = '$pageview'\n    AND $session_id IS NOT NULL\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY session_id\n)\nWHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  AND (medium = 'organic' OR (medium = '' AND match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\nGROUP BY week\nORDER BY week","postgres":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\nWITH entries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at)::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  ORDER BY session_id, occurred_at\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n  AND (medium = 'organic' OR (medium = '' AND referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'))\nGROUP BY week\nORDER BY week;","bigquery":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    lower(coalesce(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n    coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  AND (medium = 'organic' OR (medium = '' AND REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\nGROUP BY week\nORDER BY week;","snowflake":"-- Organic search sessions per week: sessions whose first page view came from a search engine (or utm_medium=organic), with no paid tag or ad click id.\n-- Assumes WEEK_START = 1 (Monday).\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n    lower(coalesce(properties:\"$referring_domain\"::string, '')) AS referrer,\n    coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  AND (medium = 'organic' OR (medium = '' AND REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')))\nGROUP BY week\nORDER BY week;"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"organic sessions a week","typical":12000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":125000,"volume":125000,"trend":0.08},"drivers":[{"id":"classification","label":"Tracking and channel rules","dropped":{"check":"Did a redirect, consent change or new domain strip the referrer, so search visits now look direct?","yes":"Direct sessions rise by about as much as organic falls, from the day of the change."},"spiked":{"check":"Did paid search lose its tags, so ad clicks now count as organic?","yes":"Paid search sessions fall by about as much as organic rises, often after auto-tagging was switched off or a redirect dropped the click id."}},{"id":"google-update","label":"Google updates and results pages","feed":"google-search","dropped":{"check":"Did a core update, a ranking loss or an AI Overview start taking clicks from key queries?","yes":"The fall starts on a dated update and concentrates on a few landing pages or query groups."},"spiked":{"check":"Did a core update or a new results feature reward the site's pages?","yes":"The rise starts on a dated update and holds for more than one week."}},{"id":"calendar","label":"Seasonal search demand","feed":"shopping","dropped":{"check":"Did people simply search less for what the store sells, after a holiday or a season?","yes":"The same weeks last year show the same fall once aligned on the event."},"spiked":{"check":"Is this a gifting, sale or seasonal week when people search more?","yes":"The same week last year shows the same rise."}},{"id":"brand-demand","label":"Branded searches","metric":"paid-sessions","dropped":{"check":"Did advertising, press or a launch that drove people to search the brand name stop?","yes":"Visits landing on the home page from search fall while product-page search visits hold."},"spiked":{"check":"Did a campaign, a press piece or a creator post make people search the brand?","yes":"The rise lands on the home page and brand queries, and fades when the campaign ends."}},{"id":"landing-pages","label":"Pages that rank","breakdown":"$pathname","dropped":{"check":"Did a ranking page get removed, redirected, noindexed or slower?","yes":"One or two landing paths account for most of the fall."},"spiked":{"check":"Did a new or updated page start ranking for a valuable query?","yes":"One or two landing paths account for most of the rise."}}],"diagnose_order":["classification","google-update","calendar","brand-demand","landing-pages"],"related":["sessions","paid-sessions","referral-sessions","new-visitor-share","conversion-rate"],"prose":{"why_it_matters":"Organic search is the traffic a store doesn't pay for each week, so it sets how much of growth has to be bought. It also moves on dates you can look up: Google ships several core updates a year, and a store with 125,000 organic sessions a week can lose 15% in the days after one without changing a thing.","pitfalls":["Google Ads auto-tagging adds a gclid but no UTM tags. Without checking the click id, paid search clicks land in organic and organic looks better than it is.","Organic here means search engines only. Unpaid social posts, emails and links from other sites are separate channels, and GA4's \"Organic\" groups differ by tool.","Visits from ChatGPT, Perplexity and other AI assistants arrive as referrals, not search. They are the fastest-growing source of non-paid visits for many stores; read them in referral sessions.","Most search referrers carry no keyword, so this number can't tell branded from unbranded searches. Use Search Console for that split, and expect its clicks to differ from sessions by 10 to 20%."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "pages-per-session": { yaml: "id: pages-per-session\nname: Pages per session\naliases:\n  - Pages per visit\n  - Pageviews per session\n  - Views per session\n  - Page depth\nfamily: traffic\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of pages viewed in one visit, across all visits in the week.\n  formula: Page views ÷ sessions with a page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; ties the page view to a visit.\n      - name: $pathname\n        description: The page's path, for finding where visits end.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet.\n\nnumerator:\n  label: Page views\n  aggregate: count\n  event: $pageview\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: mean\n  cv: 1.3\n  min_denominator: 200\n  volume_unit: sessions a week\n  typical: 3.4\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 3.6\n  volume: 520000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    breakdown: $browser\n    dropped:\n      check: Did a release stop client-side route changes from sending a page view?\n      yes: Page views fall on the release day while sessions, product views and orders hold.\n    spiked:\n      check: Is a page view firing twice, from two tags or a router that reports every route change twice?\n      yes: Page views per session jump by close to one overnight while orders don't move.\n  - id: bounce\n    label: One-page visits\n    metric: bounce-rate\n    dropped:\n      check: Did more visits leave after the first page?\n      yes: Bounce rate rises by enough to explain the fall; visits that stay browse as deeply as before.\n    spiked:\n      check: Did fewer visits bounce, or did a bot that viewed one page stop?\n      yes: Bounce rate falls and the visits that remain look like last week's.\n  - id: traffic-mix\n    label: Who arrived\n    metric: paid-sessions\n    breakdown: utm_medium\n    dropped:\n      check: Did a larger share of visits come from paid social, email or a viral link, which browse less?\n      yes: Every channel holds its own depth but the shallow channel grew.\n    spiked:\n      check: Did returning visitors or search traffic, which browse more, grow as a share?\n      yes: Every channel holds its own depth but the deep channel grew.\n  - id: navigation\n    label: Navigation, search and collections\n    metric: product-view-rate\n    breakdown: $pathname\n    dropped:\n      check: Did a menu, collection page or on-site search change make it harder to find more products?\n      yes: Fewer visits move from collection or search pages to product pages after the change.\n    spiked:\n      check: Did a change add steps, such as pagination, a quiz or an interstitial, without adding interest?\n      yes: Pages per session rise but product views and orders per session don't.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the fall on one device only?\n      yes: One device drops after a layout or menu change while the other holds.\n    spiked:\n      check: Is the rise on one device only?\n      yes: One device rises after a release; confirm it isn't a page view firing twice there.\n\ndiagnose_order: [tracking, bounce, traffic-mix, navigation, device-split]\n\nrelated: [bounce-rate, sessions, product-view-rate, conversion-rate, sessions-per-user]\n\nprose:\n  why_it_matters: >-\n    Pages per session says how far an average visit gets into the store. It moves with intent,\n    with navigation and with tracking, and only the first two are real. A store averaging 3.6\n    pages gains nothing from 4.0 if the extra page is a slower checkout or a second page view\n    firing; read it with product views and conversion, never alone.\n  pitfalls:\n    - On a single-page app, page views depend on whether every route change is tracked. A router update can change this number by a full page with no change in behaviour.\n    - More pages is not always better. Pagination, quizzes and confusing menus add pages to visits that end the same way.\n    - The average hides a long tail. A few bots or heavy browsers viewing hundreds of pages can lift it; check the median when it jumps.\n    - Comparing with GA4 views per session needs the same unit. GA4 counts screen views from apps too and divides by all sessions, not sessions with a page view.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"pages-per-session","name":"Pages per session","aliases":["Pages per visit","Pageviews per session","Views per session","Page depth"],"family":"traffic","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The average number of pages viewed in one visit, across all visits in the week.","formula":"Page views ÷ sessions with a page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; ties the page view to a visit."},{"name":"$pathname","description":"The page's path, for finding where visits end."},{"name":"$device_type","description":"Mobile, Desktop or Tablet."}]}],"numerator":{"label":"Page views","aggregate":"count","event":"$pageview"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"mean","cv":1.3,"min_denominator":200,"volume_unit":"sessions a week","typical":3.4,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":3.6,"volume":520000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking change","breakdown":"$browser","dropped":{"check":"Did a release stop client-side route changes from sending a page view?","yes":"Page views fall on the release day while sessions, product views and orders hold."},"spiked":{"check":"Is a page view firing twice, from two tags or a router that reports every route change twice?","yes":"Page views per session jump by close to one overnight while orders don't move."}},{"id":"bounce","label":"One-page visits","metric":"bounce-rate","dropped":{"check":"Did more visits leave after the first page?","yes":"Bounce rate rises by enough to explain the fall; visits that stay browse as deeply as before."},"spiked":{"check":"Did fewer visits bounce, or did a bot that viewed one page stop?","yes":"Bounce rate falls and the visits that remain look like last week's."}},{"id":"traffic-mix","label":"Who arrived","metric":"paid-sessions","breakdown":"utm_medium","dropped":{"check":"Did a larger share of visits come from paid social, email or a viral link, which browse less?","yes":"Every channel holds its own depth but the shallow channel grew."},"spiked":{"check":"Did returning visitors or search traffic, which browse more, grow as a share?","yes":"Every channel holds its own depth but the deep channel grew."}},{"id":"navigation","label":"Navigation, search and collections","metric":"product-view-rate","breakdown":"$pathname","dropped":{"check":"Did a menu, collection page or on-site search change make it harder to find more products?","yes":"Fewer visits move from collection or search pages to product pages after the change."},"spiked":{"check":"Did a change add steps, such as pagination, a quiz or an interstitial, without adding interest?","yes":"Pages per session rise but product views and orders per session don't."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the fall on one device only?","yes":"One device drops after a layout or menu change while the other holds."},"spiked":{"check":"Is the rise on one device only?","yes":"One device rises after a release; confirm it isn't a page view firing twice there."}}],"diagnose_order":["tracking","bounce","traffic-mix","navigation","device-split"],"related":["bounce-rate","sessions","product-view-rate","conversion-rate","sessions-per-user"],"prose":{"why_it_matters":"Pages per session says how far an average visit gets into the store. It moves with intent, with navigation and with tracking, and only the first two are real. A store averaging 3.6 pages gains nothing from 4.0 if the extra page is a slower checkout or a second page view firing; read it with product views and conversion, never alone.","pitfalls":["On a single-page app, page views depend on whether every route change is tracked. A router update can change this number by a full page with no change in behaviour.","More pages is not always better. Pagination, quizzes and confusing menus add pages to visits that end the same way.","The average hides a long tail. A few bots or heavy browsers viewing hundreds of pages can lift it; check the median when it jumps.","Comparing with GA4 views per session needs the same unit. GA4 counts screen views from apps too and divides by all sessions, not sessions with a page view."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "paid-conversion-rate": { yaml: "id: paid-conversion-rate\nname: Paid conversion rate\naliases:\n  - Paid traffic conversion rate\n  - Ad conversion rate\n  - Paid session conversion rate\nfamily: acquisition\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of visits that arrived through a paid ad and placed an order in the same visit.\n  formula: Paid-ad sessions with an order ÷ paid-ad sessions\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change; the session's first page view decides whether it came from an ad.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_medium\n        description: The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner.\n      - name: utm_source\n        description: The platform that sent the click (google, facebook, tiktok).\n      - name: gclid\n        description: Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the session id of the visit it was placed in.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: $session_id\n        description: The visit the order was placed in, passed from the browser to the server event.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Paid sessions with an order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Paid sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: in\n      value: [cpc, ppc, cpm, paid, paid_search, paid_social, paidsocial, display, retargeting]\n\nqueries:\n  hogql: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\n    SELECT week, numerator, denominator, if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM (\n      SELECT week, countIf(orders > 0) AS numerator, count() AS denominator\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(minIf(timestamp, event = '$pageview')) AS week,\n          argMinIf(lower(coalesce(properties.utm_medium, '')), timestamp, event = '$pageview') AS medium,\n          argMinIf(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp, event = '$pageview') AS ad_click,\n          countIf(event = 'order_completed') AS orders\n        FROM events\n        WHERE event IN ('$pageview', 'order_completed')\n          AND $session_id IS NOT NULL\n          AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n          AND timestamp < toStartOfWeek(now(), 1)\n        GROUP BY session_id\n        HAVING countIf(event = '$pageview') > 0\n      )\n      WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      GROUP BY week\n    )\n    ORDER BY week\n  postgres: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\n    WITH entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at)::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      ORDER BY session_id, occurred_at\n    ),\n    ordered AS (\n      SELECT DISTINCT session_id\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n    )\n    SELECT\n      e.week,\n      count(o.session_id) AS numerator,\n      count(*) AS denominator,\n      count(o.session_id)::numeric / nullif(count(*), 0) AS value\n    FROM entries AS e\n    LEFT JOIN ordered AS o ON o.session_id = e.session_id\n    WHERE (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n    GROUP BY e.week\n    ORDER BY e.week;\n  bigquery: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    ordered AS (\n      SELECT DISTINCT session_id\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    )\n    SELECT\n      e.week,\n      count(o.session_id) AS numerator,\n      count(*) AS denominator,\n      SAFE_DIVIDE(COUNT(o.session_id), COUNT(*)) AS value\n    FROM entries AS e\n    LEFT JOIN ordered AS o ON o.session_id = e.session_id\n    WHERE (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n    GROUP BY e.week\n    ORDER BY e.week;\n  snowflake: |-\n    -- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\n    -- Assumes WEEK_START = 1 (Monday).\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n        coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    ordered AS (\n      SELECT DISTINCT session_id\n      FROM events\n      WHERE event_name = 'order_completed'\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n    )\n    SELECT\n      e.week,\n      count(o.session_id) AS numerator,\n      count(*) AS denominator,\n      DIV0NULL(COUNT(o.session_id), COUNT(*)) AS value\n    FROM entries AS e\n    LEFT JOIN ordered AS o ON o.session_id = e.session_id\n    WHERE (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n    GROUP BY e.week\n    ORDER BY e.week;\n\nnoise:\n  type: binomial\n  min_denominator: 300\n  volume_unit: paid sessions a week\n  typical: 0.02\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.021\n  volume: 180000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking and attribution\n    dropped:\n      check: Did orders stop carrying the browser's session id, or did a redirect strip tags from the landing URL?\n      yes: Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change.\n    spiked:\n      check: Did paid sessions lose tags, shrinking the denominator, or are orders recorded twice?\n      yes: Paid sessions fall with no fall in ad clicks, or recorded orders exceed the store admin's.\n  - id: landing\n    label: Landing pages and site health\n    feed: cloudflare\n    dropped:\n      check: Did a landing page break, slow down, sell out or stop matching its ad?\n      yes: Bounce from paid traffic rises on one landing path or device from a dated change.\n    spiked:\n      check: Did a faster or better-matched landing page go live, or did last week's outage end?\n      yes: The rise starts on the day of the page change on the campaigns that use it.\n  - id: calendar\n    label: Calendar and offers\n    feed: shopping\n    dropped:\n      check: Did a sale or holiday end, so the same ads now reach people with less reason to buy?\n      yes: The same weeks last year show the same fall after the event.\n    spiked:\n      check: Is a sale, holiday or new offer turning the same clicks into more orders?\n      yes: The same week last year shows the same rise, and promo code use is up.\n  - id: audience\n    label: Who the ads reached\n    metric: paid-sessions\n    breakdown: utm_source\n    dropped:\n      check: Did spend shift to prospecting, a new platform or broad audiences that convert lower?\n      yes: Each source holds its own rate but a low-converting one grew its share of paid sessions.\n    spiked:\n      check: Did spend shift to retargeting or branded search, which convert far higher?\n      yes: Each source holds its own rate but a high-converting one grew its share.\n  - id: checkout\n    label: Checkout and payment\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did checkout or payment break for everyone, not only paid visitors?\n      yes: Checkout conversion falls across all channels in the same days.\n    spiked:\n      check: Did a checkout or payment fix lift every channel?\n      yes: Checkout conversion rises across all channels from the day of the fix.\n  - id: device\n    label: Mobile conversion\n    metric: mobile-conversion-rate\n    dropped:\n      check: Did mobile conversion fall, where most paid social traffic lands?\n      yes: Mobile conversion falls while desktop holds.\n    spiked:\n      check: Did a mobile fix or a faster mobile page lift conversion?\n      yes: Mobile conversion rises while desktop holds.\n\ndiagnose_order: [tracking, landing, calendar, audience, checkout, device]\n\nrelated: [conversion-rate, paid-sessions, roas, ncac, cpc, checkout-conversion]\n\nprose:\n  why_it_matters: >-\n    This is the step between a paid click and an order, and the one the store, not the ad\n    platform, controls. With cost per click fixed by the auction, it sets what a paid order\n    costs: at $1.25 a click, 2.1% conversion is $60 of media per order, and 1.7% is $74.\n  pitfalls:\n    - Same-visit attribution misses buyers who click an ad and come back later to buy. Many stores see half their ad-driven orders arrive this way, so this rate reads lower than the platforms' own.\n    - Prospecting and retargeting convert several times apart. A move in the blended rate is usually a mix change; split by source and campaign first.\n    - Server-side order events need the browser's session id passed through checkout, or orders can't be matched to the visit that brought them.\n    - Google Ads auto-tagged clicks carry a gclid and no UTM tags. This query counts the click id; a tag-only rule drops those sessions from the denominator.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"paid-conversion-rate","name":"Paid conversion rate","aliases":["Paid traffic conversion rate","Ad conversion rate","Paid session conversion rate"],"family":"acquisition","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of visits that arrived through a paid ad and placed an order in the same visit.","formula":"Paid-ad sessions with an order ÷ paid-ad sessions"},"events":[{"name":"$pageview","description":"One page load or client-side route change; the session's first page view decides whether it came from an ad.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_medium","description":"The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner."},{"name":"utm_source","description":"The platform that sent the click (google, facebook, tiktok)."},{"name":"gclid","description":"Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the session id of the visit it was placed in.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"$session_id","description":"The visit the order was placed in, passed from the browser to the server event."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Paid sessions with an order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Paid sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"in","value":["cpc","ppc","cpm","paid","paid_search","paid_social","paidsocial","display","retargeting"]}]},"queries":{"hogql":"-- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\nSELECT week, numerator, denominator, if(denominator > 0, numerator / denominator, NULL) AS value\nFROM (\n  SELECT week, countIf(orders > 0) AS numerator, count() AS denominator\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(minIf(timestamp, event = '$pageview')) AS week,\n      argMinIf(lower(coalesce(properties.utm_medium, '')), timestamp, event = '$pageview') AS medium,\n      argMinIf(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp, event = '$pageview') AS ad_click,\n      countIf(event = 'order_completed') AS orders\n    FROM events\n    WHERE event IN ('$pageview', 'order_completed')\n      AND $session_id IS NOT NULL\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY session_id\n    HAVING countIf(event = '$pageview') > 0\n  )\n  WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  GROUP BY week\n)\nORDER BY week","postgres":"-- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\nWITH entries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at)::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  ORDER BY session_id, occurred_at\n),\nordered AS (\n  SELECT DISTINCT session_id\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n)\nSELECT\n  e.week,\n  count(o.session_id) AS numerator,\n  count(*) AS denominator,\n  count(o.session_id)::numeric / nullif(count(*), 0) AS value\nFROM entries AS e\nLEFT JOIN ordered AS o ON o.session_id = e.session_id\nWHERE (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\nGROUP BY e.week\nORDER BY e.week;","bigquery":"-- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nordered AS (\n  SELECT DISTINCT session_id\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n)\nSELECT\n  e.week,\n  count(o.session_id) AS numerator,\n  count(*) AS denominator,\n  SAFE_DIVIDE(COUNT(o.session_id), COUNT(*)) AS value\nFROM entries AS e\nLEFT JOIN ordered AS o ON o.session_id = e.session_id\nWHERE (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\nGROUP BY e.week\nORDER BY e.week;","snowflake":"-- Paid conversion rate per week: sessions that arrived through a paid ad and placed an order ÷ sessions that arrived through a paid ad.\n-- Assumes WEEK_START = 1 (Monday).\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n    coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\nordered AS (\n  SELECT DISTINCT session_id\n  FROM events\n  WHERE event_name = 'order_completed'\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n)\nSELECT\n  e.week,\n  count(o.session_id) AS numerator,\n  count(*) AS denominator,\n  DIV0NULL(COUNT(o.session_id), COUNT(*)) AS value\nFROM entries AS e\nLEFT JOIN ordered AS o ON o.session_id = e.session_id\nWHERE (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\nGROUP BY e.week\nORDER BY e.week;"},"noise":{"type":"binomial","min_denominator":300,"volume_unit":"paid sessions a week","typical":0.02,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.021,"volume":180000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking and attribution","dropped":{"check":"Did orders stop carrying the browser's session id, or did a redirect strip tags from the landing URL?","yes":"Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change."},"spiked":{"check":"Did paid sessions lose tags, shrinking the denominator, or are orders recorded twice?","yes":"Paid sessions fall with no fall in ad clicks, or recorded orders exceed the store admin's."}},{"id":"landing","label":"Landing pages and site health","feed":"cloudflare","dropped":{"check":"Did a landing page break, slow down, sell out or stop matching its ad?","yes":"Bounce from paid traffic rises on one landing path or device from a dated change."},"spiked":{"check":"Did a faster or better-matched landing page go live, or did last week's outage end?","yes":"The rise starts on the day of the page change on the campaigns that use it."}},{"id":"calendar","label":"Calendar and offers","feed":"shopping","dropped":{"check":"Did a sale or holiday end, so the same ads now reach people with less reason to buy?","yes":"The same weeks last year show the same fall after the event."},"spiked":{"check":"Is a sale, holiday or new offer turning the same clicks into more orders?","yes":"The same week last year shows the same rise, and promo code use is up."}},{"id":"audience","label":"Who the ads reached","metric":"paid-sessions","breakdown":"utm_source","dropped":{"check":"Did spend shift to prospecting, a new platform or broad audiences that convert lower?","yes":"Each source holds its own rate but a low-converting one grew its share of paid sessions."},"spiked":{"check":"Did spend shift to retargeting or branded search, which convert far higher?","yes":"Each source holds its own rate but a high-converting one grew its share."}},{"id":"checkout","label":"Checkout and payment","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did checkout or payment break for everyone, not only paid visitors?","yes":"Checkout conversion falls across all channels in the same days."},"spiked":{"check":"Did a checkout or payment fix lift every channel?","yes":"Checkout conversion rises across all channels from the day of the fix."}},{"id":"device","label":"Mobile conversion","metric":"mobile-conversion-rate","dropped":{"check":"Did mobile conversion fall, where most paid social traffic lands?","yes":"Mobile conversion falls while desktop holds."},"spiked":{"check":"Did a mobile fix or a faster mobile page lift conversion?","yes":"Mobile conversion rises while desktop holds."}}],"diagnose_order":["tracking","landing","calendar","audience","checkout","device"],"related":["conversion-rate","paid-sessions","roas","ncac","cpc","checkout-conversion"],"prose":{"why_it_matters":"This is the step between a paid click and an order, and the one the store, not the ad platform, controls. With cost per click fixed by the auction, it sets what a paid order costs: at $1.25 a click, 2.1% conversion is $60 of media per order, and 1.7% is $74.","pitfalls":["Same-visit attribution misses buyers who click an ad and come back later to buy. Many stores see half their ad-driven orders arrive this way, so this rate reads lower than the platforms' own.","Prospecting and retargeting convert several times apart. A move in the blended rate is usually a mix change; split by source and campaign first.","Server-side order events need the browser's session id passed through checkout, or orders can't be matched to the visit that brought them.","Google Ads auto-tagged clicks carry a gclid and no UTM tags. This query counts the click id; a tag-only rule drops those sessions from the denominator."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "paid-sessions": { yaml: "id: paid-sessions\nname: Paid sessions\naliases:\n  - Paid traffic\n  - Paid visits\n  - Paid media sessions\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits that arrived from a paid ad, judged by the campaign tag or ad click id on the first page of the visit.\n  formula: Sessions whose first page view has a paid utm_medium (cpc, cpm, paid_social, display) or a Google or Microsoft ad click id\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; the session's first page view decides its channel.\n      - name: utm_medium\n        description: The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner.\n      - name: utm_source\n        description: The platform that sent the click (google, facebook, tiktok).\n      - name: gclid\n        description: Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads.\n\nnumerator:\n  label: Paid sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: in\n      value: [cpc, ppc, cpm, paid, paid_search, paid_social, paidsocial, display, retargeting]\n\nqueries:\n  hogql: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\n    SELECT week, count() AS value\n    FROM (\n      SELECT\n        $session_id AS session_id,\n        toMonday(min(timestamp)) AS week,\n        argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n        argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp) AS ad_click\n      FROM events\n      WHERE event = '$pageview'\n        AND $session_id IS NOT NULL\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY session_id\n    )\n    WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\n    WITH entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at)::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      ORDER BY session_id, occurred_at\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\n    -- Assumes WEEK_START = 1 (Monday).\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n        coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: paid sessions a week\n  typical: 15000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 180000\n  volume: 180000\n  trend: 0.2\n\ndrivers:\n  - id: tagging\n    label: Campaign tags and click ids\n    dropped:\n      check: Did a new campaign, landing page or redirect lose its UTM tags or click id?\n      yes: Organic or direct sessions rise by about as much as paid falls, from the day the campaign or redirect changed.\n    spiked:\n      check: Did someone tag non-paid links as paid, such as a newsletter or an influencer link with utm_medium=cpc?\n      yes: The new paid sessions come from a source with no spend behind it.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend fall, from a paused campaign, a budget cut, a declined card or a rejected ad?\n      yes: Spend on one platform falls by about the same share as its paid sessions.\n    spiked:\n      check: Did a budget increase or a new campaign start?\n      yes: Spend rises on one platform by about the share paid sessions did; check that conversion held.\n  - id: cpc\n    label: Cost per click\n    metric: cpc\n    dropped:\n      check: With spend steady, did each click get more expensive?\n      yes: CPC rises on one platform while spend holds, so the same budget buys fewer clicks.\n    spiked:\n      check: With spend steady, did clicks get cheaper?\n      yes: CPC falls; check whether a cheap placement such as Audience Network or display is buying low-quality clicks.\n  - id: invalid-clicks\n    label: Bots and invalid clicks\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did the platform start filtering a bot source that used to click?\n      yes: Clicks fall in one country or placement while orders hold.\n    spiked:\n      check: Is a bot, click farm or an accidental-click placement inflating visits?\n      yes: The new sessions bounce at once, come from one placement, country or app, and never order.\n  - id: landing\n    label: Landing page availability\n    feed: cloudflare\n    dropped:\n      check: Did the landing page error or redirect, so clicks were paid for but never recorded as visits?\n      yes: Platform clicks hold while recorded paid sessions fall in the hours of an incident.\n    spiked:\n      check: Was last week depressed by a landing-page outage?\n      yes: Last week shows the gap; this week is back to its usual level.\n\ndiagnose_order: [tagging, spend, cpc, invalid-clicks, landing]\n\nrelated: [ad-spend, cpc, ctr, paid-conversion-rate, sessions, organic-sessions]\n\nprose:\n  why_it_matters: >-\n    Paid sessions are the traffic the store buys, so they should move with spend and almost\n    nothing else. When they don't, either the price of a click changed or the tracking did.\n    Ad platforms report clicks, not visits; on most stores 10 to 25% of paid clicks never\n    become a recorded session, and that gap is worth watching on its own.\n  pitfalls:\n    - Clicks in the ad platform and sessions in analytics never match. Slow pages, consent banners, ad blockers and accidental taps on mobile all lose visits between the two.\n    - Google Ads auto-tagging adds a gclid but no UTM tags. Checking only utm_medium puts those clicks in organic search.\n    - The classification is by first page view. A visitor who clicks an ad, leaves and returns later from a bookmark is paid once and direct the second time.\n    - Tags are case sensitive in most tools. CPC, Cpc and cpc split one channel three ways unless the query lowercases them, as this one does.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"paid-sessions","name":"Paid sessions","aliases":["Paid traffic","Paid visits","Paid media sessions"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits that arrived from a paid ad, judged by the campaign tag or ad click id on the first page of the visit.","formula":"Sessions whose first page view has a paid utm_medium (cpc, cpm, paid_social, display) or a Google or Microsoft ad click id"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; the session's first page view decides its channel."},{"name":"utm_medium","description":"The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner."},{"name":"utm_source","description":"The platform that sent the click (google, facebook, tiktok)."},{"name":"gclid","description":"Google Ads click id, added by auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads."}]}],"numerator":{"label":"Paid sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"in","value":["cpc","ppc","cpm","paid","paid_search","paid_social","paidsocial","display","retargeting"]}]},"queries":{"hogql":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\nSELECT week, count() AS value\nFROM (\n  SELECT\n    $session_id AS session_id,\n    toMonday(min(timestamp)) AS week,\n    argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n    argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp) AS ad_click\n  FROM events\n  WHERE event = '$pageview'\n    AND $session_id IS NOT NULL\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY session_id\n)\nWHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\nGROUP BY week\nORDER BY week","postgres":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\nWITH entries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at)::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  ORDER BY session_id, occurred_at\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\nGROUP BY week\nORDER BY week;","bigquery":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\nGROUP BY week\nORDER BY week;","snowflake":"-- Paid sessions per week: sessions whose first page view carries a paid utm_medium (GA4's paid rule) or an ad click id.\n-- Assumes WEEK_START = 1 (Monday).\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n    coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\nGROUP BY week\nORDER BY week;"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"paid sessions a week","typical":15000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":180000,"volume":180000,"trend":0.2},"drivers":[{"id":"tagging","label":"Campaign tags and click ids","dropped":{"check":"Did a new campaign, landing page or redirect lose its UTM tags or click id?","yes":"Organic or direct sessions rise by about as much as paid falls, from the day the campaign or redirect changed."},"spiked":{"check":"Did someone tag non-paid links as paid, such as a newsletter or an influencer link with utm_medium=cpc?","yes":"The new paid sessions come from a source with no spend behind it."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend fall, from a paused campaign, a budget cut, a declined card or a rejected ad?","yes":"Spend on one platform falls by about the same share as its paid sessions."},"spiked":{"check":"Did a budget increase or a new campaign start?","yes":"Spend rises on one platform by about the share paid sessions did; check that conversion held."}},{"id":"cpc","label":"Cost per click","metric":"cpc","dropped":{"check":"With spend steady, did each click get more expensive?","yes":"CPC rises on one platform while spend holds, so the same budget buys fewer clicks."},"spiked":{"check":"With spend steady, did clicks get cheaper?","yes":"CPC falls; check whether a cheap placement such as Audience Network or display is buying low-quality clicks."}},{"id":"invalid-clicks","label":"Bots and invalid clicks","breakdown":"$geoip_country_code","dropped":{"check":"Did the platform start filtering a bot source that used to click?","yes":"Clicks fall in one country or placement while orders hold."},"spiked":{"check":"Is a bot, click farm or an accidental-click placement inflating visits?","yes":"The new sessions bounce at once, come from one placement, country or app, and never order."}},{"id":"landing","label":"Landing page availability","feed":"cloudflare","dropped":{"check":"Did the landing page error or redirect, so clicks were paid for but never recorded as visits?","yes":"Platform clicks hold while recorded paid sessions fall in the hours of an incident."},"spiked":{"check":"Was last week depressed by a landing-page outage?","yes":"Last week shows the gap; this week is back to its usual level."}}],"diagnose_order":["tagging","spend","cpc","invalid-clicks","landing"],"related":["ad-spend","cpc","ctr","paid-conversion-rate","sessions","organic-sessions"],"prose":{"why_it_matters":"Paid sessions are the traffic the store buys, so they should move with spend and almost nothing else. When they don't, either the price of a click changed or the tracking did. Ad platforms report clicks, not visits; on most stores 10 to 25% of paid clicks never become a recorded session, and that gap is worth watching on its own.","pitfalls":["Clicks in the ad platform and sessions in analytics never match. Slow pages, consent banners, ad blockers and accidental taps on mobile all lose visits between the two.","Google Ads auto-tagging adds a gclid but no UTM tags. Checking only utm_medium puts those clicks in organic search.","The classification is by first page view. A visitor who clicks an ad, leaves and returns later from a bookmark is paid once and direct the second time.","Tags are case sensitive in most tools. CPC, Cpc and cpc split one channel three ways unless the query lowercases them, as this one does."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "payment-success-rate": { yaml: "id: payment-success-rate\nname: Payment success rate\naliases:\n  - Payment authorization rate\n  - Authorization rate\n  - Payment approval rate\n  - Payment acceptance rate\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of payment attempts that succeed, across every gateway and payment method, in the week.\n  formula: Successful payment attempts ÷ all payment attempts (succeeded + failed)\n\nevents:\n  - name: payment_succeeded\n    description: A payment authorized and captured, from the processor's webhook, not the browser.\n    also_called: [payment_intent.succeeded, charge.succeeded, Payment Succeeded]\n    properties:\n      - name: gateway\n        description: The processor that handled it (stripe, adyen, paypal, shopify_payments).\n      - name: method\n        description: card, apple_pay, google_pay, paypal, klarna and so on.\n      - name: amount\n        description: The amount attempted.\n  - name: payment_failed\n    description: A payment attempt declined or errored, one event per attempt, from the processor's webhook.\n    also_called: [payment_intent.payment_failed, charge.failed, Payment Failed]\n    properties:\n      - name: gateway\n        description: The processor that handled it.\n      - name: method\n        description: The payment method attempted.\n      - name: decline_code\n        description: The issuer's or processor's reason, such as insufficient_funds, do_not_honor or fraudulent.\n\nnumerator:\n  label: Successful payment attempts\n  aggregate: count\n  event: payment_succeeded\n\nqueries:\n  hogql: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    SELECT\n      toMonday(timestamp) AS week,\n      countIf(event = 'payment_succeeded') AS numerator,\n      count() AS denominator,\n      if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM events\n    WHERE event IN ('payment_succeeded', 'payment_failed')\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    -- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    SELECT\n      date_trunc('week', occurred_at)::date AS week,\n      count(*) FILTER (WHERE event_name = 'payment_succeeded') AS numerator,\n      count(*) AS denominator,\n      (count(*) FILTER (WHERE event_name = 'payment_succeeded'))::numeric / nullif(count(*), 0) AS value\n    FROM events\n    WHERE event_name IN ('payment_succeeded', 'payment_failed')\n      AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n      AND occurred_at < date_trunc('week', now())\n    GROUP BY 1\n    ORDER BY 1;\n  bigquery: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    -- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    SELECT\n      DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n      COUNTIF(event_name = 'payment_succeeded') AS numerator,\n      COUNT(*) AS denominator,\n      SAFE_DIVIDE(COUNTIF(event_name = 'payment_succeeded'), COUNT(*)) AS value\n    FROM events\n    WHERE event_name IN ('payment_succeeded', 'payment_failed')\n      AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n      AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    -- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\n    SELECT\n      DATE_TRUNC('week', occurred_at)::date AS week,\n      COUNT_IF(event_name = 'payment_succeeded') AS numerator,\n      COUNT(*) AS denominator,\n      DIV0NULL(COUNT_IF(event_name = 'payment_succeeded'), COUNT(*)) AS value\n    FROM events\n    WHERE event_name IN ('payment_succeeded', 'payment_failed')\n      AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n      AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n    GROUP BY 1\n    ORDER BY 1;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: payment attempts a week\n  typical: 0.92\n\nexample:\n  business: store\n  level: 0.93\n  volume: 14300\n  trend: 0\n\ndrivers:\n  - id: card-testing\n    label: Card testing and bots\n    dropped:\n      check: Is a card-testing attack sending bursts of failed attempts with stolen cards?\n      yes: Failed attempts spike within hours from a few sessions or IPs, with small amounts and codes like incorrect_cvc, while orders hold.\n    spiked:\n      check: Did a card-testing attack from last week stop, or did a new rule block bots before they reach the processor?\n      yes: Failed attempts fall back while successful payments hold; the rise is a smaller denominator, not more customers paying.\n  - id: processor\n    label: Processor incidents\n    breakdown: gateway\n    feed: stripe\n    dropped:\n      check: Did one gateway or processor have an outage or a degraded period this week?\n      yes: Failures concentrate on one gateway during the hours of an incident on its status page.\n    spiked:\n      check: Did an incident from the week before clear?\n      yes: The affected gateway returns to its usual rate and the others never moved.\n  - id: method\n    label: Payment methods\n    breakdown: method\n    dropped:\n      check: Is one method failing, such as Apple Pay, PayPal, a buy-now-pay-later provider or 3-D Secure cards?\n      yes: One method's success falls while cards and the other methods hold.\n    spiked:\n      check: Did wallets, which approve more often than typed cards, gain share, or did a weak method get removed?\n      yes: Each method's own rate holds and only the mix moved.\n  - id: fraud-rules\n    label: Fraud rules and 3-D Secure\n    breakdown: decline_code\n    dropped:\n      check: Did a fraud rule, risk setting or 3-D Secure change start blocking good customers?\n      yes: One decline code, such as fraudulent or authentication_required, rises from the day the rule changed.\n    spiked:\n      check: Was a fraud rule loosened? Check disputes before celebrating.\n      yes: Blocked attempts fall from the day of the change, and fraud disputes may rise a few weeks later.\n  - id: country-mix\n    label: Countries and card issuers\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did more attempts come from countries where cross-border cards decline more often, for example after a new campaign?\n      yes: One country's share of attempts grows and its success rate sits well below the rest.\n    spiked:\n      check: Did a low-approval country shrink, or did a local payment method launch there?\n      yes: The country mix moved, or one country's rate rose from the day a method launched.\n\ndiagnose_order: [card-testing, processor, method, fraud-rules, country-mix]\n\nrelated: [checkout-conversion, conversion-rate, orders, mobile-conversion-rate, net-revenue]\n\nprose:\n  why_it_matters: >-\n    Every failed payment is a shopper who had already decided to buy and typed in a card. A fall\n    is rarely about the shopper; it is a processor incident, a fraud rule or a bot testing stolen\n    cards. At Northwind, with about 14,000 attempts a week, one point is 140 failed attempts a\n    week, most of them from people standing at the till.\n  pitfalls:\n    - Retries count as attempts, so a shopper who is declined twice and then pays is one success in three. Read checkout conversion beside it to see what shoppers experienced.\n    - Card-testing bots can send thousands of failed attempts in an hour and pull a week down ten points with no real customer affected. Split by session or IP before reacting.\n    - Record payment events from the processor's webhooks, not the browser. Browser events miss redirect methods such as PayPal and Klarna and duplicate on reloads.\n    - Processors disagree on what a failure is; a 3-D Secure challenge the shopper abandons is a failure in some and nothing in others. Changing processors moves the rate with no change in approvals.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"payment-success-rate","name":"Payment success rate","aliases":["Payment authorization rate","Authorization rate","Payment approval rate","Payment acceptance rate"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of payment attempts that succeed, across every gateway and payment method, in the week.","formula":"Successful payment attempts ÷ all payment attempts (succeeded + failed)"},"events":[{"name":"payment_succeeded","description":"A payment authorized and captured, from the processor's webhook, not the browser.","also_called":["payment_intent.succeeded","charge.succeeded","Payment Succeeded"],"properties":[{"name":"gateway","description":"The processor that handled it (stripe, adyen, paypal, shopify_payments)."},{"name":"method","description":"card, apple_pay, google_pay, paypal, klarna and so on."},{"name":"amount","description":"The amount attempted."}]},{"name":"payment_failed","description":"A payment attempt declined or errored, one event per attempt, from the processor's webhook.","also_called":["payment_intent.payment_failed","charge.failed","Payment Failed"],"properties":[{"name":"gateway","description":"The processor that handled it."},{"name":"method","description":"The payment method attempted."},{"name":"decline_code","description":"The issuer's or processor's reason, such as insufficient_funds, do_not_honor or fraudulent."}]}],"numerator":{"label":"Successful payment attempts","aggregate":"count","event":"payment_succeeded"},"queries":{"hogql":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\nSELECT\n  toMonday(timestamp) AS week,\n  countIf(event = 'payment_succeeded') AS numerator,\n  count() AS denominator,\n  if(denominator > 0, numerator / denominator, NULL) AS value\nFROM events\nWHERE event IN ('payment_succeeded', 'payment_failed')\n  AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n  AND timestamp < toStartOfWeek(now(), 1)\nGROUP BY week\nORDER BY week","postgres":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n-- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nSELECT\n  date_trunc('week', occurred_at)::date AS week,\n  count(*) FILTER (WHERE event_name = 'payment_succeeded') AS numerator,\n  count(*) AS denominator,\n  (count(*) FILTER (WHERE event_name = 'payment_succeeded'))::numeric / nullif(count(*), 0) AS value\nFROM events\nWHERE event_name IN ('payment_succeeded', 'payment_failed')\n  AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n  AND occurred_at < date_trunc('week', now())\nGROUP BY 1\nORDER BY 1;","bigquery":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n-- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nSELECT\n  DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n  COUNTIF(event_name = 'payment_succeeded') AS numerator,\n  COUNT(*) AS denominator,\n  SAFE_DIVIDE(COUNTIF(event_name = 'payment_succeeded'), COUNT(*)) AS value\nFROM events\nWHERE event_name IN ('payment_succeeded', 'payment_failed')\n  AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n  AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\nGROUP BY week\nORDER BY week;","snowflake":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n-- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\nSELECT\n  DATE_TRUNC('week', occurred_at)::date AS week,\n  COUNT_IF(event_name = 'payment_succeeded') AS numerator,\n  COUNT(*) AS denominator,\n  DIV0NULL(COUNT_IF(event_name = 'payment_succeeded'), COUNT(*)) AS value\nFROM events\nWHERE event_name IN ('payment_succeeded', 'payment_failed')\n  AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n  AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\nGROUP BY 1\nORDER BY 1;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"payment attempts a week","typical":0.92},"example":{"business":"store","level":0.93,"volume":14300,"trend":0},"drivers":[{"id":"card-testing","label":"Card testing and bots","dropped":{"check":"Is a card-testing attack sending bursts of failed attempts with stolen cards?","yes":"Failed attempts spike within hours from a few sessions or IPs, with small amounts and codes like incorrect_cvc, while orders hold."},"spiked":{"check":"Did a card-testing attack from last week stop, or did a new rule block bots before they reach the processor?","yes":"Failed attempts fall back while successful payments hold; the rise is a smaller denominator, not more customers paying."}},{"id":"processor","label":"Processor incidents","breakdown":"gateway","feed":"stripe","dropped":{"check":"Did one gateway or processor have an outage or a degraded period this week?","yes":"Failures concentrate on one gateway during the hours of an incident on its status page."},"spiked":{"check":"Did an incident from the week before clear?","yes":"The affected gateway returns to its usual rate and the others never moved."}},{"id":"method","label":"Payment methods","breakdown":"method","dropped":{"check":"Is one method failing, such as Apple Pay, PayPal, a buy-now-pay-later provider or 3-D Secure cards?","yes":"One method's success falls while cards and the other methods hold."},"spiked":{"check":"Did wallets, which approve more often than typed cards, gain share, or did a weak method get removed?","yes":"Each method's own rate holds and only the mix moved."}},{"id":"fraud-rules","label":"Fraud rules and 3-D Secure","breakdown":"decline_code","dropped":{"check":"Did a fraud rule, risk setting or 3-D Secure change start blocking good customers?","yes":"One decline code, such as fraudulent or authentication_required, rises from the day the rule changed."},"spiked":{"check":"Was a fraud rule loosened? Check disputes before celebrating.","yes":"Blocked attempts fall from the day of the change, and fraud disputes may rise a few weeks later."}},{"id":"country-mix","label":"Countries and card issuers","breakdown":"$geoip_country_code","dropped":{"check":"Did more attempts come from countries where cross-border cards decline more often, for example after a new campaign?","yes":"One country's share of attempts grows and its success rate sits well below the rest."},"spiked":{"check":"Did a low-approval country shrink, or did a local payment method launch there?","yes":"The country mix moved, or one country's rate rose from the day a method launched."}}],"diagnose_order":["card-testing","processor","method","fraud-rules","country-mix"],"related":["checkout-conversion","conversion-rate","orders","mobile-conversion-rate","net-revenue"],"prose":{"why_it_matters":"Every failed payment is a shopper who had already decided to buy and typed in a card. A fall is rarely about the shopper; it is a processor incident, a fraud rule or a bot testing stolen cards. At Northwind, with about 14,000 attempts a week, one point is 140 failed attempts a week, most of them from people standing at the till.","pitfalls":["Retries count as attempts, so a shopper who is declined twice and then pays is one success in three. Read checkout conversion beside it to see what shoppers experienced.","Card-testing bots can send thousands of failed attempts in an hour and pull a week down ten points with no real customer affected. Split by session or IP before reacting.","Record payment events from the processor's webhooks, not the browser. Browser events miss redirect methods such as PayPal and Klarna and duplicate on reloads.","Processors disagree on what a failure is; a 3-D Secure challenge the shopper abandons is a failure in some and nothing in others. Changing processors moves the rate with no change in approvals."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "product-view-rate": { yaml: "id: product-view-rate\nname: Product view rate\naliases:\n  - Product page view rate\n  - PDP view rate\n  - Product detail view rate\nfamily: conversion\ncatalog_id: product_view_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that viewed at least one product page, the first step of the store funnel.\n  formula: Sessions with a product view ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: product_viewed\n    description: A product detail page rendered with its product, once per view.\n    also_called: [view_item, Product Viewed, product_viewed]\n    properties:\n      - name: product_id\n        description: The product shown.\n      - name: price\n        description: The price shown, before discounts.\n\nnumerator:\n  label: Sessions that viewed a product\n  aggregate: unique_sessions\n  event: product_viewed\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions a week\n  typical: 0.55\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.62\n  volume: 600000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a theme, app or tag change stop product_viewed firing on some product templates?\n      yes: Page views on product URLs hold while product_viewed events fall, often on one template or device.\n    spiked:\n      check: Is product_viewed now firing on quick views, collection grids or twice per page?\n      yes: Product views per session jump, or the event appears on paths that are not product pages.\n  - id: bot-traffic\n    label: Bots and junk sessions\n    breakdown: $browser\n    dropped:\n      check: Did a wave of bot or junk sessions add visits that never reach a product?\n      yes: Sessions jump from one browser, country or referrer with one page per session and almost no product views.\n    spiked:\n      check: Did a bot source stop, shrinking the denominator rather than lifting real browsing?\n      yes: Sessions fall from one browser or country while sessions that viewed a product hold.\n  - id: traffic-mix\n    label: Landing channel\n    breakdown: utm_source\n    dropped:\n      check: Did a channel that rarely browses grow, such as a viral blog post, a giveaway or broad paid social?\n      yes: One source gains share of sessions and its product view rate sits far below the rest.\n    spiked:\n      check: Did campaigns start sending people straight to product pages, or did a low-intent source shrink?\n      yes: One source's share or view rate moves from the day a campaign or link changed.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, for example after a mobile menu or search change?\n      yes: Mobile falls several points while desktop is flat, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm product_viewed didn't start firing twice there first.\n  - id: navigation\n    label: Homepage and navigation\n    dropped:\n      check: Did a homepage, menu, search or collection change make products harder to reach?\n      yes: Sessions that land on the changed page view fewer products from the day it shipped, on every channel.\n    spiked:\n      check: Did a homepage, menu or collection change put products one click closer?\n      yes: Sessions that land on the changed page view more products from the day it shipped, on every channel.\n\ndiagnose_order: [tracking, bot-traffic, traffic-mix, device-split, navigation]\n\nrelated: [sessions, bounce-rate, add-to-cart-rate, conversion-rate, pages-per-session]\n\nprose:\n  why_it_matters: >-\n    Product view rate says whether visitors find something worth a closer look, before price,\n    stock or checkout can matter. On a store with 600,000 sessions a week, one point is 6,000\n    sessions that never see a product; at the 3.6% of product viewers who go on to order, that\n    is about 200 orders a week.\n  pitfalls:\n    - Counting product views instead of sessions with a product view lets a few heavy browsers lift the rate. This spec counts each session once.\n    - Decide whether quick-view pop-ups count as product views and keep that choice; switching it moves the rate several points with no change in shoppers.\n    - Bot and crawler sessions land in the denominator only, so a bot wave reads as a fall in browsing. Split sessions by browser and country before acting.\n    - Landing pages with their own buy button skip the product page, so the rate falls while sales hold. Fire product_viewed on those pages or read add-to-cart over all sessions instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"product-view-rate","name":"Product view rate","aliases":["Product page view rate","PDP view rate","Product detail view rate"],"family":"conversion","catalog_id":"product_view_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that viewed at least one product page, the first step of the store funnel.","formula":"Sessions with a product view ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"product_viewed","description":"A product detail page rendered with its product, once per view.","also_called":["view_item","Product Viewed","product_viewed"],"properties":[{"name":"product_id","description":"The product shown."},{"name":"price","description":"The price shown, before discounts."}]}],"numerator":{"label":"Sessions that viewed a product","aggregate":"unique_sessions","event":"product_viewed"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions a week","typical":0.55,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.62,"volume":600000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a theme, app or tag change stop product_viewed firing on some product templates?","yes":"Page views on product URLs hold while product_viewed events fall, often on one template or device."},"spiked":{"check":"Is product_viewed now firing on quick views, collection grids or twice per page?","yes":"Product views per session jump, or the event appears on paths that are not product pages."}},{"id":"bot-traffic","label":"Bots and junk sessions","breakdown":"$browser","dropped":{"check":"Did a wave of bot or junk sessions add visits that never reach a product?","yes":"Sessions jump from one browser, country or referrer with one page per session and almost no product views."},"spiked":{"check":"Did a bot source stop, shrinking the denominator rather than lifting real browsing?","yes":"Sessions fall from one browser or country while sessions that viewed a product hold."}},{"id":"traffic-mix","label":"Landing channel","breakdown":"utm_source","dropped":{"check":"Did a channel that rarely browses grow, such as a viral blog post, a giveaway or broad paid social?","yes":"One source gains share of sessions and its product view rate sits far below the rest."},"spiked":{"check":"Did campaigns start sending people straight to product pages, or did a low-intent source shrink?","yes":"One source's share or view rate moves from the day a campaign or link changed."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, for example after a mobile menu or search change?","yes":"Mobile falls several points while desktop is flat, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm product_viewed didn't start firing twice there first."}},{"id":"navigation","label":"Homepage and navigation","dropped":{"check":"Did a homepage, menu, search or collection change make products harder to reach?","yes":"Sessions that land on the changed page view fewer products from the day it shipped, on every channel."},"spiked":{"check":"Did a homepage, menu or collection change put products one click closer?","yes":"Sessions that land on the changed page view more products from the day it shipped, on every channel."}}],"diagnose_order":["tracking","bot-traffic","traffic-mix","device-split","navigation"],"related":["sessions","bounce-rate","add-to-cart-rate","conversion-rate","pages-per-session"],"prose":{"why_it_matters":"Product view rate says whether visitors find something worth a closer look, before price, stock or checkout can matter. On a store with 600,000 sessions a week, one point is 6,000 sessions that never see a product; at the 3.6% of product viewers who go on to order, that is about 200 orders a week.","pitfalls":["Counting product views instead of sessions with a product view lets a few heavy browsers lift the rate. This spec counts each session once.","Decide whether quick-view pop-ups count as product views and keep that choice; switching it moves the rate several points with no change in shoppers.","Bot and crawler sessions land in the denominator only, so a bot wave reads as a fall in browsing. Split sessions by browser and country before acting.","Landing pages with their own buy button skip the product page, so the rate falls while sales hold. Fire product_viewed on those pages or read add-to-cart over all sessions instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "promo-code-usage-rate": { yaml: "id: promo-code-usage-rate\nname: Promo code usage rate\naliases:\n  - Coupon usage rate\n  - Discount code usage rate\n  - Coupon redemption rate\n  - Promo code redemption rate\nfamily: conversion\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of paid orders placed with a discount code, the part of demand that only bought at a lower price.\n  formula: Paid orders with a discount code ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: coupon\n        description: The code redeemed on the order; absent when no code was used.\n      - name: discount\n        description: The total discount on the order, from codes and automatic offers.\n  - name: coupon_applied\n    description: A code entered at cart or checkout, valid or not.\n    also_called: [Coupon Entered, Coupon Applied, Coupon Denied]\n    properties:\n      - name: coupon\n        description: The code entered.\n      - name: valid\n        description: Whether the code was accepted.\n\nnumerator:\n  label: Orders with a code\n  aggregate: count\n  event: order_completed\n  where:\n    - property: coupon\n      op: is_set\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: orders a week\n  typical: 0.25\n\nexample:\n  business: store\n  level: 0.24\n  volume: 13300\n  trend: 0.03\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a checkout migration or a new discount app stop sending the code on the order event?\n      yes: Discounts on orders hold while the coupon field goes blank from one day.\n    spiked:\n      check: Is the order event now sending an empty string or an automatic offer's name as the coupon?\n      yes: Orders with a coupon but no discount appear, or one code name shows up on most orders.\n  - id: campaigns\n    label: Sales and campaign codes\n    feed: shopping\n    dropped:\n      check: Did a sale end or a campaign code expire this week?\n      yes: One or two campaign codes that carried last week's orders fall away.\n    spiked:\n      check: Is a sale running on a code, or did an email or SMS send one this week?\n      yes: One or two campaign codes explain most of the rise, starting on the send or launch day.\n  - id: leaked-codes\n    label: Leaked codes\n    breakdown: coupon\n    dropped:\n      check: Did you disable a code that had leaked to coupon sites or browser extensions?\n      yes: That code's uses fall to zero and invalid attempts with it appear in coupon_applied.\n    spiked:\n      check: Did a code leak to a coupon site, a browser extension or a deal forum?\n      yes: One code's uses climb across channels it was never sent to, often on first orders.\n  - id: invalid-codes\n    label: Codes that fail\n    dropped:\n      check: Did codes start failing, from an expiry, a new minimum spend or a discount app error?\n      yes: coupon_applied with valid false rises, and checkout conversion may fall with it.\n    spiked:\n      check: Did the code field move up to the cart or become more visible, sending shoppers to look for codes?\n      yes: Uses of codes nobody sent this week rise from the day the field moved.\n  - id: partner-codes\n    label: Influencer and affiliate codes\n    breakdown: utm_source\n    dropped:\n      check: Did an influencer, affiliate or podcast campaign with its own code end?\n      yes: The partner's code and its traffic source fall away together.\n    spiked:\n      check: Did an influencer, affiliate or podcast campaign with its own code launch?\n      yes: The partner's code accounts for most of the rise, with orders from its source.\n  - id: new-customers\n    label: First orders and welcome codes\n    metric: new-customers\n    dropped:\n      check: Did fewer first-time customers arrive with a welcome code?\n      yes: Welcome code uses fall with new customers while repeat customers' code use holds.\n    spiked:\n      check: Did more first-time customers arrive with a welcome code, from a pop-up change or an ad push?\n      yes: Welcome code uses rise with new customers while repeat customers' code use holds.\n\ndiagnose_order: [tracking, campaigns, leaked-codes, invalid-codes, partner-codes, new-customers]\n\nrelated: [discount-rate, aov, checkout-conversion, new-customers, gross-margin]\n\nprose:\n  why_it_matters: >-\n    Every coded order is margin given away, and code usage creeps: a welcome code, an influencer\n    code and a leaked code each add a few points that nobody decided on. At Northwind, 24% of\n    13,300 weekly orders use a code; five more points is about 650 more discounted orders a\n    week.\n  pitfalls:\n    - Automatic discounts and free-shipping rules leave the coupon empty, so a store that moves from codes to automatic offers sees code usage fall while it discounts more. Read discount rate beside it.\n    - Send no coupon property when no code was used. An empty string counts as a code in most query engines, including this spec's test.\n    - Welcome codes tie code usage to the new-customer mix, so a week with more first orders shows more codes without any change in promotions.\n    - Browser coupon extensions try every code they know at checkout, so a code shared once can spread to a large share of orders within days. Watch the top code's share, not only the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"promo-code-usage-rate","name":"Promo code usage rate","aliases":["Coupon usage rate","Discount code usage rate","Coupon redemption rate","Promo code redemption rate"],"family":"conversion","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of paid orders placed with a discount code, the part of demand that only bought at a lower price.","formula":"Paid orders with a discount code ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"coupon","description":"The code redeemed on the order; absent when no code was used."},{"name":"discount","description":"The total discount on the order, from codes and automatic offers."}]},{"name":"coupon_applied","description":"A code entered at cart or checkout, valid or not.","also_called":["Coupon Entered","Coupon Applied","Coupon Denied"],"properties":[{"name":"coupon","description":"The code entered."},{"name":"valid","description":"Whether the code was accepted."}]}],"numerator":{"label":"Orders with a code","aggregate":"count","event":"order_completed","where":[{"property":"coupon","op":"is_set"}]},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"orders a week","typical":0.25},"example":{"business":"store","level":0.24,"volume":13300,"trend":0.03,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a checkout migration or a new discount app stop sending the code on the order event?","yes":"Discounts on orders hold while the coupon field goes blank from one day."},"spiked":{"check":"Is the order event now sending an empty string or an automatic offer's name as the coupon?","yes":"Orders with a coupon but no discount appear, or one code name shows up on most orders."}},{"id":"campaigns","label":"Sales and campaign codes","feed":"shopping","dropped":{"check":"Did a sale end or a campaign code expire this week?","yes":"One or two campaign codes that carried last week's orders fall away."},"spiked":{"check":"Is a sale running on a code, or did an email or SMS send one this week?","yes":"One or two campaign codes explain most of the rise, starting on the send or launch day."}},{"id":"leaked-codes","label":"Leaked codes","breakdown":"coupon","dropped":{"check":"Did you disable a code that had leaked to coupon sites or browser extensions?","yes":"That code's uses fall to zero and invalid attempts with it appear in coupon_applied."},"spiked":{"check":"Did a code leak to a coupon site, a browser extension or a deal forum?","yes":"One code's uses climb across channels it was never sent to, often on first orders."}},{"id":"invalid-codes","label":"Codes that fail","dropped":{"check":"Did codes start failing, from an expiry, a new minimum spend or a discount app error?","yes":"coupon_applied with valid false rises, and checkout conversion may fall with it."},"spiked":{"check":"Did the code field move up to the cart or become more visible, sending shoppers to look for codes?","yes":"Uses of codes nobody sent this week rise from the day the field moved."}},{"id":"partner-codes","label":"Influencer and affiliate codes","breakdown":"utm_source","dropped":{"check":"Did an influencer, affiliate or podcast campaign with its own code end?","yes":"The partner's code and its traffic source fall away together."},"spiked":{"check":"Did an influencer, affiliate or podcast campaign with its own code launch?","yes":"The partner's code accounts for most of the rise, with orders from its source."}},{"id":"new-customers","label":"First orders and welcome codes","metric":"new-customers","dropped":{"check":"Did fewer first-time customers arrive with a welcome code?","yes":"Welcome code uses fall with new customers while repeat customers' code use holds."},"spiked":{"check":"Did more first-time customers arrive with a welcome code, from a pop-up change or an ad push?","yes":"Welcome code uses rise with new customers while repeat customers' code use holds."}}],"diagnose_order":["tracking","campaigns","leaked-codes","invalid-codes","partner-codes","new-customers"],"related":["discount-rate","aov","checkout-conversion","new-customers","gross-margin"],"prose":{"why_it_matters":"Every coded order is margin given away, and code usage creeps: a welcome code, an influencer code and a leaked code each add a few points that nobody decided on. At Northwind, 24% of 13,300 weekly orders use a code; five more points is about 650 more discounted orders a week.","pitfalls":["Automatic discounts and free-shipping rules leave the coupon empty, so a store that moves from codes to automatic offers sees code usage fall while it discounts more. Read discount rate beside it.","Send no coupon property when no code was used. An empty string counts as a code in most query engines, including this spec's test.","Welcome codes tie code usage to the new-customer mix, so a week with more first orders shows more codes without any change in promotions.","Browser coupon extensions try every code they know at checkout, so a code shared once can spread to a large share of orders within days. Watch the top code's share, not only the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "referral-sessions": { yaml: "id: referral-sessions\nname: Referral sessions\naliases:\n  - Referral traffic\n  - Referral visits\n  - Referring site traffic\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits that arrived through a link on another website that is not a search engine, a social network or an ad.\n  formula: Sessions whose first page view came from another site (not search, social, a payment page or this site) with no campaign tag, or tagged utm_medium=referral\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; the session's first page view decides its channel.\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n      - name: $host\n        description: This site's own domain, so internal links and returns from checkout don't count as referrals.\n      - name: utm_medium\n        description: The campaign medium from the landing URL. When set, it decides the channel.\n\nnumerator:\n  label: Referral sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: utm_medium\n      op: is_not_set\n    - property: $referring_domain\n      op: not_in\n      value: [$direct, www.google.com, www.bing.com, duckduckgo.com, www.facebook.com, l.facebook.com, t.co, www.instagram.com]\n\nqueries:\n  hogql: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\n    SELECT week, count() AS value\n    FROM (\n      SELECT\n        $session_id AS session_id,\n        toMonday(min(timestamp)) AS week,\n        argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n        argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n        argMin(lower(coalesce(properties.$host, '')), timestamp) AS host,\n        argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp) AS ad_click\n      FROM events\n      WHERE event = '$pageview'\n        AND $session_id IS NOT NULL\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY session_id\n    )\n    WHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      AND (\n        medium = 'referral'\n        OR (\n          medium = ''\n          AND referrer NOT IN ('', '$direct')\n          AND replaceRegexpOne(referrer, '^www[.]', '') <> replaceRegexpOne(host, '^www[.]', '')\n          AND NOT match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n          AND NOT match(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n          AND NOT match(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n        )\n      )\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\n    WITH entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at)::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n        lower(coalesce(properties->>'$host', '')) AS host,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      ORDER BY session_id, occurred_at\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n      AND (\n        medium = 'referral'\n        OR (\n          medium = ''\n          AND referrer NOT IN ('', '$direct')\n          AND regexp_replace(referrer, '^www[.]', '') <> regexp_replace(host, '^www[.]', '')\n          AND NOT referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'\n          AND NOT referrer ~ '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$'\n          AND NOT referrer ~ '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$'\n        )\n      )\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        lower(coalesce(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n        lower(coalesce(JSON_VALUE(properties, '$.\"$host\"'), '')) AS host,\n        coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      AND (\n        medium = 'referral'\n        OR (\n          medium = ''\n          AND referrer NOT IN ('', '$direct')\n          AND REGEXP_REPLACE(referrer, r'^www[.]', '') <> REGEXP_REPLACE(host, r'^www[.]', '')\n          AND NOT REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n          AND NOT REGEXP_CONTAINS(referrer, r'^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n          AND NOT REGEXP_CONTAINS(referrer, r'^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n        )\n      )\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\n    -- Assumes WEEK_START = 1 (Monday).\n    WITH entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n        lower(coalesce(properties:\"$referring_domain\"::string, '')) AS referrer,\n        lower(coalesce(properties:\"$host\"::string, '')) AS host,\n        coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    )\n    SELECT week, count(*) AS value\n    FROM entries\n    WHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      AND (\n        medium = 'referral'\n        OR (\n          medium = ''\n          AND referrer NOT IN ('', '$direct')\n          AND REGEXP_REPLACE(referrer, '^www[.]', '') <> REGEXP_REPLACE(host, '^www[.]', '')\n          AND NOT REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n          AND NOT REGEXP_LIKE(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n          AND NOT REGEXP_LIKE(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n        )\n      )\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: poisson\n  min_denominator: 50\n  volume_unit: referral sessions a week\n  typical: 2500\n  reference_volumes: [200, 1000, 5000, 25000]\n\nexample:\n  business: store\n  level: 21000\n  volume: 21000\n  trend: 0.05\n\ndrivers:\n  - id: self-referrals\n    label: Self-referrals and classification\n    breakdown: $referring_domain\n    dropped:\n      check: Did a referrer change, a new domain or stricter referrer policy turn referrals into direct visits?\n      yes: Direct sessions rise by about as much as referrals fall, from the day of the change.\n    spiked:\n      check: Are your own subdomains, a payment page or a login provider showing up as referrers?\n      yes: The top new referrer is a checkout, payment, help-centre or sign-in domain you own or use.\n  - id: referral-spam\n    label: Bots and referral spam\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did a spam referrer that used to send junk visits stop?\n      yes: One unfamiliar domain that bounced every time has disappeared.\n    spiked:\n      check: Is an unknown domain sending visits that bounce at once and never buy?\n      yes: One unfamiliar referrer explains the rise, with near-total bounce and no orders.\n  - id: top-referrer\n    label: Press, creators and partners\n    breakdown: $referring_domain\n    dropped:\n      check: Did a link that sent steady traffic come down, or did last week's press mention fade?\n      yes: One referring domain that sent many visits last week sends few this week.\n    spiked:\n      check: Did an article, a gift guide, a creator or a partner link to the store?\n      yes: One referring domain explains most of the rise; expect it to fade within one or two weeks.\n  - id: ai-assistants\n    label: AI assistants\n    dropped:\n      check: Did visits from chatgpt.com, perplexity.ai, gemini.google.com or copilot fall?\n      yes: The AI assistant referrers send fewer visits, often after a model or citation change on their side.\n    spiked:\n      check: Are AI assistants citing the store more often?\n      yes: chatgpt.com, perplexity.ai and similar referrers grow steadily, landing on product and guide pages.\n  - id: affiliates\n    label: Affiliate and coupon sites\n    dropped:\n      check: Did an affiliate network, coupon site or marketplace listing stop linking?\n      yes: Referrals from coupon or affiliate domains fall and affiliate orders fall with them.\n    spiked:\n      check: Did a coupon or deal site start listing the store, possibly with a leaked code?\n      yes: A coupon domain grows and promo-code use rises with it.\n\ndiagnose_order: [self-referrals, referral-spam, top-referrer, ai-assistants, affiliates]\n\nrelated: [sessions, organic-sessions, paid-sessions, new-visitor-share, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Referrals are earned traffic: press, gift guides, creators, partners and, more and more, AI\n    assistants that cite the store. They are spiky by nature, so a single article can double a\n    week and be gone the next. On a store with 21,000 referral sessions a week, the question is\n    always which one domain moved, not whether referrals did.\n  pitfalls:\n    - Payment pages, sign-in providers and your own subdomains show up as referrers when a visit restarts after them. This spec drops this site's domain and common payment pages; add others you see.\n    - Many apps and sites strip the referrer. Links from email clients, messaging apps and some social apps arrive as direct visits, not referrals.\n    - Referral spam sends fake visits with a made-up referrer. It never orders, so check orders from a new referrer before thanking anyone.\n    - Social networks and search engines are excluded here and counted in their own channels. Tools group the long tail differently, so referral totals rarely match GA4.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"referral-sessions","name":"Referral sessions","aliases":["Referral traffic","Referral visits","Referring site traffic"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits that arrived through a link on another website that is not a search engine, a social network or an ad.","formula":"Sessions whose first page view came from another site (not search, social, a payment page or this site) with no campaign tag, or tagged utm_medium=referral"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; the session's first page view decides its channel."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."},{"name":"$host","description":"This site's own domain, so internal links and returns from checkout don't count as referrals."},{"name":"utm_medium","description":"The campaign medium from the landing URL. When set, it decides the channel."}]}],"numerator":{"label":"Referral sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"utm_medium","op":"is_not_set"},{"property":"$referring_domain","op":"not_in","value":["$direct","www.google.com","www.bing.com","duckduckgo.com","www.facebook.com","l.facebook.com","t.co","www.instagram.com"]}]},"queries":{"hogql":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\nSELECT week, count() AS value\nFROM (\n  SELECT\n    $session_id AS session_id,\n    toMonday(min(timestamp)) AS week,\n    argMin(lower(coalesce(properties.utm_medium, '')), timestamp) AS medium,\n    argMin(lower(coalesce(properties.$referring_domain, '')), timestamp) AS referrer,\n    argMin(lower(coalesce(properties.$host, '')), timestamp) AS host,\n    argMin(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp) AS ad_click\n  FROM events\n  WHERE event = '$pageview'\n    AND $session_id IS NOT NULL\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY session_id\n)\nWHERE NOT (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  AND (\n    medium = 'referral'\n    OR (\n      medium = ''\n      AND referrer NOT IN ('', '$direct')\n      AND replaceRegexpOne(referrer, '^www[.]', '') <> replaceRegexpOne(host, '^www[.]', '')\n      AND NOT match(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n      AND NOT match(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n      AND NOT match(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n    )\n  )\nGROUP BY week\nORDER BY week","postgres":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\nWITH entries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at)::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    lower(coalesce(properties->>'$referring_domain', '')) AS referrer,\n    lower(coalesce(properties->>'$host', '')) AS host,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  ORDER BY session_id, occurred_at\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE NOT (medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR ad_click)\n  AND (\n    medium = 'referral'\n    OR (\n      medium = ''\n      AND referrer NOT IN ('', '$direct')\n      AND regexp_replace(referrer, '^www[.]', '') <> regexp_replace(host, '^www[.]', '')\n      AND NOT referrer ~ '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$'\n      AND NOT referrer ~ '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$'\n      AND NOT referrer ~ '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$'\n    )\n  )\nGROUP BY week\nORDER BY week;","bigquery":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    lower(coalesce(JSON_VALUE(properties, '$.\"$referring_domain\"'), '')) AS referrer,\n    lower(coalesce(JSON_VALUE(properties, '$.\"$host\"'), '')) AS host,\n    coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE NOT (REGEXP_CONTAINS(medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  AND (\n    medium = 'referral'\n    OR (\n      medium = ''\n      AND referrer NOT IN ('', '$direct')\n      AND REGEXP_REPLACE(referrer, r'^www[.]', '') <> REGEXP_REPLACE(host, r'^www[.]', '')\n      AND NOT REGEXP_CONTAINS(referrer, r'^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n      AND NOT REGEXP_CONTAINS(referrer, r'^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n      AND NOT REGEXP_CONTAINS(referrer, r'^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n    )\n  )\nGROUP BY week\nORDER BY week;","snowflake":"-- Referral sessions per week: sessions whose first page view came from another site that is not a search engine, social network, payment page or this site, and carried no campaign tag (or utm_medium=referral).\n-- Assumes WEEK_START = 1 (Monday).\nWITH entries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n    lower(coalesce(properties:\"$referring_domain\"::string, '')) AS referrer,\n    lower(coalesce(properties:\"$host\"::string, '')) AS host,\n    coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n)\nSELECT week, count(*) AS value\nFROM entries\nWHERE NOT (REGEXP_LIKE(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  AND (\n    medium = 'referral'\n    OR (\n      medium = ''\n      AND referrer NOT IN ('', '$direct')\n      AND REGEXP_REPLACE(referrer, '^www[.]', '') <> REGEXP_REPLACE(host, '^www[.]', '')\n      AND NOT REGEXP_LIKE(referrer, '^(www[.])?(google|bing|duckduckgo|yandex|baidu|ecosia|naver|seznam|qwant|startpage)[.][a-z.]+$|^(.*[.])?search[.](yahoo|brave)[.]com$|^com[.]google[.]android[.]googlequicksearchbox$')\n      AND NOT REGEXP_LIKE(referrer, '^(www[.]|m[.]|l[.]|lm[.]|out[.])?(facebook|instagram|linkedin|pinterest|reddit|tiktok|youtube|twitter)[.][a-z.]+$|^(x[.]com|t[.]co|lnkd[.]in|threads[.]net|bsky[.]app)$')\n      AND NOT REGEXP_LIKE(referrer, '^(.*[.])?(paypal|stripe|klarna|afterpay|affirm)[.]com$|^shop[.]app$')\n    )\n  )\nGROUP BY week\nORDER BY week;"},"noise":{"type":"poisson","min_denominator":50,"volume_unit":"referral sessions a week","typical":2500,"reference_volumes":[200,1000,5000,25000]},"example":{"business":"store","level":21000,"volume":21000,"trend":0.05},"drivers":[{"id":"self-referrals","label":"Self-referrals and classification","breakdown":"$referring_domain","dropped":{"check":"Did a referrer change, a new domain or stricter referrer policy turn referrals into direct visits?","yes":"Direct sessions rise by about as much as referrals fall, from the day of the change."},"spiked":{"check":"Are your own subdomains, a payment page or a login provider showing up as referrers?","yes":"The top new referrer is a checkout, payment, help-centre or sign-in domain you own or use."}},{"id":"referral-spam","label":"Bots and referral spam","breakdown":"$geoip_country_code","dropped":{"check":"Did a spam referrer that used to send junk visits stop?","yes":"One unfamiliar domain that bounced every time has disappeared."},"spiked":{"check":"Is an unknown domain sending visits that bounce at once and never buy?","yes":"One unfamiliar referrer explains the rise, with near-total bounce and no orders."}},{"id":"top-referrer","label":"Press, creators and partners","breakdown":"$referring_domain","dropped":{"check":"Did a link that sent steady traffic come down, or did last week's press mention fade?","yes":"One referring domain that sent many visits last week sends few this week."},"spiked":{"check":"Did an article, a gift guide, a creator or a partner link to the store?","yes":"One referring domain explains most of the rise; expect it to fade within one or two weeks."}},{"id":"ai-assistants","label":"AI assistants","dropped":{"check":"Did visits from chatgpt.com, perplexity.ai, gemini.google.com or copilot fall?","yes":"The AI assistant referrers send fewer visits, often after a model or citation change on their side."},"spiked":{"check":"Are AI assistants citing the store more often?","yes":"chatgpt.com, perplexity.ai and similar referrers grow steadily, landing on product and guide pages."}},{"id":"affiliates","label":"Affiliate and coupon sites","dropped":{"check":"Did an affiliate network, coupon site or marketplace listing stop linking?","yes":"Referrals from coupon or affiliate domains fall and affiliate orders fall with them."},"spiked":{"check":"Did a coupon or deal site start listing the store, possibly with a leaked code?","yes":"A coupon domain grows and promo-code use rises with it."}}],"diagnose_order":["self-referrals","referral-spam","top-referrer","ai-assistants","affiliates"],"related":["sessions","organic-sessions","paid-sessions","new-visitor-share","promo-code-usage-rate"],"prose":{"why_it_matters":"Referrals are earned traffic: press, gift guides, creators, partners and, more and more, AI assistants that cite the store. They are spiky by nature, so a single article can double a week and be gone the next. On a store with 21,000 referral sessions a week, the question is always which one domain moved, not whether referrals did.","pitfalls":["Payment pages, sign-in providers and your own subdomains show up as referrers when a visit restarts after them. This spec drops this site's domain and common payment pages; add others you see.","Many apps and sites strip the referrer. Links from email clients, messaging apps and some social apps arrive as direct visits, not referrals.","Referral spam sends fake visits with a made-up referrer. It never orders, so check orders from a new referrer before thanking anyone.","Social networks and search engines are excluded here and counted in their own channels. Tools group the long tail differently, so referral totals rarely match GA4."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "refund-rate": { yaml: "id: refund-rate\nname: Refund rate\naliases:\n  - Return rate\n  - Returns rate\n  - Refund percentage\nfamily: revenue\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: Refunds issued this week as a share of this week's order revenue.\n  formula: Refunds issued ÷ order revenue after discounts, each by the week it happened\n\nevents:\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: order_id\n        description: The order refunded; links the refund to the week it was sold.\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\ndenominator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.06\n\nexample:\n  business: store\n  level: 0.0335\n  volume: 13300\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking and processing\n    dropped:\n      check: Did refund events stop syncing, for example after a returns app or processor change?\n      yes: Refunds in the payment processor hold while recorded refunds fall.\n    spiked:\n      check: Did a backlog of refunds get processed in one batch, or are refunds recorded twice?\n      yes: Refunds cluster on one or two days, or the same order_id carries a partial and a full refund.\n  - id: past-sales\n    label: Last month's sales\n    feed: shopping\n    dropped:\n      check: Did a post-season wave of returns just end?\n      yes: Refunds fall back as the orders from the busy weeks pass their return window.\n    spiked:\n      check: Did a big sale or gifting season end two to six weeks ago?\n      yes: Refunds rise in step with the orders of those weeks, not this week's, and the same weeks last year show it.\n  - id: product-batch\n    label: One product or batch\n    dropped:\n      check: Did fixing a defect, a size chart or a product description cut returns on one product?\n      yes: Refunds on that product fall from the weeks after the fix.\n    spiked:\n      check: Is one product, size or batch behind most of the refunds?\n      yes: Return reasons cluster on one product, often defective, not as described or wrong size.\n  - id: delivery\n    label: Delivery problems\n    dropped:\n      check: Did a carrier or warehouse problem that caused refunds clear?\n      yes: Refunds for orders not received fall back to their usual level.\n    spiked:\n      check: Did a carrier delay, lost parcels or a warehouse error lead to refunds for orders not received?\n      yes: Refunds for orders not received rise in one region or with one carrier.\n  - id: fraud\n    label: Fraud and disputes\n    feed: stripe\n    dropped:\n      check: Did tighter fraud rules cut refunds issued to settle disputes?\n      yes: Refunds on first orders with high values or shared addresses fall.\n    spiked:\n      check: Did a fraud ring or a wave of disputes get settled with refunds?\n      yes: Refunds concentrate on first orders with high values, new cards or shared shipping addresses.\n  - id: policy\n    label: Return policy\n    dropped:\n      check: Did the return window shorten, return shipping start costing, or exchanges get pushed over refunds?\n      yes: Refunds fall from the policy date while exchanges rise.\n    spiked:\n      check: Did returns become free, the window lengthen, or a try-before-you-buy option launch?\n      yes: Refunds rise from the policy date, on orders placed after it.\n\ndiagnose_order: [tracking, past-sales, product-batch, delivery, fraud, policy]\n\nrelated: [net-revenue, orders, gross-margin, contribution-margin, gross-sales]\n\nprose:\n  why_it_matters: >-\n    Refunds are revenue the store already counted and then gave back, plus shipping both ways.\n    Because they follow sales by two to six weeks, the rate moves with last month's orders as\n    much as with today's quality. At Northwind, 3.5% of $1.33M of order revenue is about\n    $46,000 a week; one more point costs $13,300 a week before return shipping.\n  pitfalls:\n    - This spec divides refunds issued this week by this week's order revenue, so the rate rises for weeks after a big sale with no quality problem. For product quality, group refunds by the week of the original order instead.\n    - Exchanges and store credit aren't refunds and don't appear here, so a store that pushes exchanges sees the rate fall while returns hold.\n    - Partial refunds, price adjustments and goodwill credits count as refunds here. Tag them if you want returns alone.\n    - Chargebacks run through a separate flow in most processors and appear here only if they are recorded as refunds.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"refund-rate","name":"Refund rate","aliases":["Return rate","Returns rate","Refund percentage"],"family":"revenue","kind":"rate","polarity":"down-is-good","definition":{"one_line":"Refunds issued this week as a share of this week's order revenue.","formula":"Refunds issued ÷ order revenue after discounts, each by the week it happened"},"events":[{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"order_id","description":"The order refunded; links the refund to the week it was sold."},{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"denominator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.06},"example":{"business":"store","level":0.0335,"volume":13300,"trend":0},"drivers":[{"id":"tracking","label":"Tracking and processing","dropped":{"check":"Did refund events stop syncing, for example after a returns app or processor change?","yes":"Refunds in the payment processor hold while recorded refunds fall."},"spiked":{"check":"Did a backlog of refunds get processed in one batch, or are refunds recorded twice?","yes":"Refunds cluster on one or two days, or the same order_id carries a partial and a full refund."}},{"id":"past-sales","label":"Last month's sales","feed":"shopping","dropped":{"check":"Did a post-season wave of returns just end?","yes":"Refunds fall back as the orders from the busy weeks pass their return window."},"spiked":{"check":"Did a big sale or gifting season end two to six weeks ago?","yes":"Refunds rise in step with the orders of those weeks, not this week's, and the same weeks last year show it."}},{"id":"product-batch","label":"One product or batch","dropped":{"check":"Did fixing a defect, a size chart or a product description cut returns on one product?","yes":"Refunds on that product fall from the weeks after the fix."},"spiked":{"check":"Is one product, size or batch behind most of the refunds?","yes":"Return reasons cluster on one product, often defective, not as described or wrong size."}},{"id":"delivery","label":"Delivery problems","dropped":{"check":"Did a carrier or warehouse problem that caused refunds clear?","yes":"Refunds for orders not received fall back to their usual level."},"spiked":{"check":"Did a carrier delay, lost parcels or a warehouse error lead to refunds for orders not received?","yes":"Refunds for orders not received rise in one region or with one carrier."}},{"id":"fraud","label":"Fraud and disputes","feed":"stripe","dropped":{"check":"Did tighter fraud rules cut refunds issued to settle disputes?","yes":"Refunds on first orders with high values or shared addresses fall."},"spiked":{"check":"Did a fraud ring or a wave of disputes get settled with refunds?","yes":"Refunds concentrate on first orders with high values, new cards or shared shipping addresses."}},{"id":"policy","label":"Return policy","dropped":{"check":"Did the return window shorten, return shipping start costing, or exchanges get pushed over refunds?","yes":"Refunds fall from the policy date while exchanges rise."},"spiked":{"check":"Did returns become free, the window lengthen, or a try-before-you-buy option launch?","yes":"Refunds rise from the policy date, on orders placed after it."}}],"diagnose_order":["tracking","past-sales","product-batch","delivery","fraud","policy"],"related":["net-revenue","orders","gross-margin","contribution-margin","gross-sales"],"prose":{"why_it_matters":"Refunds are revenue the store already counted and then gave back, plus shipping both ways. Because they follow sales by two to six weeks, the rate moves with last month's orders as much as with today's quality. At Northwind, 3.5% of $1.33M of order revenue is about $46,000 a week; one more point costs $13,300 a week before return shipping.","pitfalls":["This spec divides refunds issued this week by this week's order revenue, so the rate rises for weeks after a big sale with no quality problem. For product quality, group refunds by the week of the original order instead.","Exchanges and store credit aren't refunds and don't appear here, so a store that pushes exchanges sees the rate fall while returns hold.","Partial refunds, price adjustments and goodwill credits count as refunds here. Tag them if you want returns alone.","Chargebacks run through a separate flow in most processors and appear here only if they are recorded as refunds."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "revenue-per-session": { yaml: "id: revenue-per-session\nname: Revenue per session\naliases:\n  - Revenue per visit\n  - RPS\n  - Revenue per visitor\n  - RPV\n  - Session value\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue earned per session, the one number that combines conversion rate and order value.\n  formula: Order revenue after discounts ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: mean\n  cv: 9\n  min_denominator: 2000\n  volume_unit: sessions a week\n  typical: 2\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 2.22\n  volume: 600000\n  trend: 0.1\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did orders stop recording, or did a new tag start splitting visits into extra sessions?\n      yes: Orders in the store platform hold while recorded orders fall, or sessions per visitor jump on one day.\n    spiked:\n      check: Did page views stop recording on some pages or browsers, or did orders start recording twice?\n      yes: Sessions fall with no matching fall in ad clicks, or the same order_id appears twice.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: traffic-mix\n    label: Who arrived\n    breakdown: utm_source\n    dropped:\n      check: Did sessions grow from a low-intent source or from bots?\n      yes: Sessions jump from one source that earns a fraction of the rest per visit, while revenue barely moves.\n    spiked:\n      check: Did a low-intent source or a bot wave shrink, lifting revenue per session without more revenue?\n      yes: Sessions fall while revenue holds. Check total revenue before celebrating.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did a smaller share of sessions buy?\n      yes: Conversion falls by about as much as revenue per session while order value holds.\n    spiked:\n      check: Did a larger share of sessions buy?\n      yes: Conversion rises by about as much as revenue per session while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did orders get smaller, from discounts, fewer items or cheaper products?\n      yes: Order value falls while conversion holds.\n    spiked:\n      check: Did orders get larger, or did a handful of very large orders land?\n      yes: Order value rises while conversion holds; check the largest orders first.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, or did mobile take a larger share of sessions?\n      yes: One device falls while the other holds, or each holds and only the mix moved.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device rises after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, traffic-mix, conversion, order-value, device-split]\n\nrelated: [conversion-rate, aov, sessions, net-revenue, cpc]\n\nprose:\n  why_it_matters: >-\n    Revenue per session is what a visit is worth, so it is the number to set beside what a visit\n    costs. At Northwind a session earns about $2.22; a channel that pays more than that times\n    gross margin, about $1.29, per session loses money on the first order. Because it multiplies\n    conversion by order value, it is also the fairest single number for tests that trade one\n    against the other.\n  pitfalls:\n    - Most sessions earn nothing and a few earn a lot, so the weekly figure swings with a handful of large orders. Below about 50,000 sessions a week, a 10% move is often chance.\n    - Revenue per visitor divides by people, not sessions, and reads higher because visitors make several sessions. Don't compare one with the other's benchmark.\n    - Bot sessions lower it without any change in shoppers. When it drops with revenue flat, check sessions by browser and country.\n    - This spec uses order revenue before refunds so it matches what the sessions produced. Subtracting refunds makes it move with returns from earlier weeks.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"revenue-per-session","name":"Revenue per session","aliases":["Revenue per visit","RPS","Revenue per visitor","RPV","Session value"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue earned per session, the one number that combines conversion rate and order value.","formula":"Order revenue after discounts ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"mean","cv":9,"min_denominator":2000,"volume_unit":"sessions a week","typical":2,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":2.22,"volume":600000,"trend":0.1,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did orders stop recording, or did a new tag start splitting visits into extra sessions?","yes":"Orders in the store platform hold while recorded orders fall, or sessions per visitor jump on one day."},"spiked":{"check":"Did page views stop recording on some pages or browsers, or did orders start recording twice?","yes":"Sessions fall with no matching fall in ad clicks, or the same order_id appears twice."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"traffic-mix","label":"Who arrived","breakdown":"utm_source","dropped":{"check":"Did sessions grow from a low-intent source or from bots?","yes":"Sessions jump from one source that earns a fraction of the rest per visit, while revenue barely moves."},"spiked":{"check":"Did a low-intent source or a bot wave shrink, lifting revenue per session without more revenue?","yes":"Sessions fall while revenue holds. Check total revenue before celebrating."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did a smaller share of sessions buy?","yes":"Conversion falls by about as much as revenue per session while order value holds."},"spiked":{"check":"Did a larger share of sessions buy?","yes":"Conversion rises by about as much as revenue per session while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did orders get smaller, from discounts, fewer items or cheaper products?","yes":"Order value falls while conversion holds."},"spiked":{"check":"Did orders get larger, or did a handful of very large orders land?","yes":"Order value rises while conversion holds; check the largest orders first."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, or did mobile take a larger share of sessions?","yes":"One device falls while the other holds, or each holds and only the mix moved."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device rises after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","traffic-mix","conversion","order-value","device-split"],"related":["conversion-rate","aov","sessions","net-revenue","cpc"],"prose":{"why_it_matters":"Revenue per session is what a visit is worth, so it is the number to set beside what a visit costs. At Northwind a session earns about $2.22; a channel that pays more than that times gross margin, about $1.29, per session loses money on the first order. Because it multiplies conversion by order value, it is also the fairest single number for tests that trade one against the other.","pitfalls":["Most sessions earn nothing and a few earn a lot, so the weekly figure swings with a handful of large orders. Below about 50,000 sessions a week, a 10% move is often chance.","Revenue per visitor divides by people, not sessions, and reads higher because visitors make several sessions. Don't compare one with the other's benchmark.","Bot sessions lower it without any change in shoppers. When it drops with revenue flat, check sessions by browser and country.","This spec uses order revenue before refunds so it matches what the sessions produced. Subtracting refunds makes it move with returns from earlier weeks."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "roas": { yaml: "id: roas\nname: Return on ad spend\naliases:\n  - Ad ROAS\n  - Paid ROAS\n  - Return on advertising spend\nfamily: acquisition\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: Revenue from orders placed in visits that arrived through a paid ad, for each dollar of ad spend in the same week.\n  formula: Order revenue from paid-ad sessions ÷ ad spend\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change; the session's first page view decides whether it came from an ad.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: utm_medium\n        description: The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner.\n      - name: gclid\n        description: Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the session id of the visit it was placed in.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: $session_id\n        description: The visit the order was placed in, passed from the browser to the server event.\n  - name: ad_spend\n    description: One row per channel per day, synced from each ad platform's reporting API.\n    also_called: [Ad Spend, ad_performance, campaign_daily_stats]\n    properties:\n      - name: spend\n        description: Amount spent that day, in the store's reporting currency.\n\nnumerator:\n  label: Revenue from paid-ad sessions\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Ad spend\n  aggregate: sum\n  event: ad_spend\n  property: spend\n\nqueries:\n  hogql: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\n    SELECT\n      a.week AS week,\n      coalesce(r.revenue, 0) AS numerator,\n      a.spend AS denominator,\n      if(a.spend > 0, coalesce(r.revenue, 0) / a.spend, NULL) AS value\n    FROM (\n      SELECT toMonday(timestamp) AS week, sum(toFloat(properties.spend)) AS spend\n      FROM events\n      WHERE event = 'ad_spend'\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY week\n    ) AS a\n    LEFT JOIN (\n      SELECT week, sum(revenue) AS revenue\n      FROM (\n        SELECT\n          $session_id AS session_id,\n          toMonday(minIf(timestamp, event = 'order_completed')) AS week,\n          argMinIf(lower(coalesce(properties.utm_medium, '')), timestamp, event = '$pageview') AS medium,\n          argMinIf(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp, event = '$pageview') AS ad_click,\n          sumIf(toFloat(properties.total), event = 'order_completed') AS revenue\n        FROM events\n        WHERE event IN ('$pageview', 'order_completed')\n          AND $session_id IS NOT NULL\n          AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n          AND timestamp < toStartOfWeek(now(), 1)\n        GROUP BY session_id\n        HAVING countIf(event = 'order_completed') > 0 AND countIf(event = '$pageview') > 0\n      )\n      WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n      GROUP BY week\n    ) AS r ON r.week = a.week\n    ORDER BY week\n  postgres: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\n    WITH spend AS (\n      SELECT date_trunc('week', occurred_at)::date AS week, sum((properties->>'spend')::numeric) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY 1\n    ),\n    entries AS (\n      SELECT DISTINCT ON (session_id)\n        session_id,\n        date_trunc('week', occurred_at)::date AS week,\n        lower(coalesce(properties->>'utm_medium', '')) AS medium,\n        coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      ORDER BY session_id, occurred_at\n    ),\n    paid_revenue AS (\n      SELECT date_trunc('week', o.occurred_at)::date AS week, sum((o.properties->>'total')::numeric) AS revenue\n      FROM events AS o\n      JOIN entries AS e ON e.session_id = o.session_id\n      WHERE o.event_name = 'order_completed'\n        AND o.occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND o.occurred_at < date_trunc('week', now())\n        AND (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n      GROUP BY 1\n    )\n    SELECT\n      s.week,\n      coalesce(p.revenue, 0) AS numerator,\n      s.spend AS denominator,\n      coalesce(p.revenue, 0) / nullif(s.spend, 0) AS value\n    FROM spend AS s\n    LEFT JOIN paid_revenue AS p ON p.week = s.week\n    ORDER BY s.week;\n  bigquery: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\n    WITH spend AS (\n      SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, sum(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY 1\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n        coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    paid_revenue AS (\n      SELECT DATE_TRUNC(DATE(o.occurred_at), ISOWEEK) AS week, sum(CAST(JSON_VALUE(o.properties, '$.total') AS FLOAT64)) AS revenue\n      FROM events AS o\n      JOIN entries AS e ON e.session_id = o.session_id\n      WHERE o.event_name = 'order_completed'\n        AND o.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND o.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n        AND (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY 1\n    )\n    SELECT\n      s.week,\n      coalesce(p.revenue, 0) AS numerator,\n      s.spend AS denominator,\n      SAFE_DIVIDE(COALESCE(p.revenue, 0), s.spend) AS value\n    FROM spend AS s\n    LEFT JOIN paid_revenue AS p ON p.week = s.week\n    ORDER BY s.week;\n  snowflake: |-\n    -- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\n    -- Assumes WEEK_START = 1 (Monday).\n    WITH spend AS (\n      SELECT DATE_TRUNC('week', occurred_at)::date AS week, sum(properties:\"spend\"::float) AS spend\n      FROM events\n      WHERE event_name = 'ad_spend'\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY 1\n    ),\n    entries AS (\n      SELECT\n        session_id,\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n        coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n      FROM events\n      WHERE event_name = '$pageview'\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n    ),\n    paid_revenue AS (\n      SELECT DATE_TRUNC('week', o.occurred_at)::date AS week, sum(o.properties:\"total\"::float) AS revenue\n      FROM events AS o\n      JOIN entries AS e ON e.session_id = o.session_id\n      WHERE o.event_name = 'order_completed'\n        AND o.occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND o.occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n        AND (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n      GROUP BY 1\n    )\n    SELECT\n      s.week,\n      coalesce(p.revenue, 0) AS numerator,\n      s.spend AS denominator,\n      DIV0NULL(COALESCE(p.revenue, 0), s.spend) AS value\n    FROM spend AS s\n    LEFT JOIN paid_revenue AS p ON p.week = s.week\n    ORDER BY s.week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders from paid sessions a week\n  typical: 2\n\nexample:\n  business: store\n  level: 1.7\n  volume: 3800\n  trend: -0.05\n\ndrivers:\n  - id: attribution\n    label: Tracking and attribution\n    dropped:\n      check: Did orders stop carrying the session id, or did a redirect strip campaign tags, so paid orders look unpaid?\n      yes: Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change.\n    spiked:\n      check: Did untagged traffic start counting as paid, or are orders recorded twice?\n      yes: Paid revenue rises with no rise in paid sessions, or order count exceeds the store admin's.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end while budgets stayed high?\n      yes: The same weeks last year show the same fall in return after the event.\n    spiked:\n      check: Is a sale or holiday turning the same clicks into more orders?\n      yes: Paid conversion jumps for the event week and the same week last year shows it too.\n  - id: spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did spend rise faster than results, from a budget increase or a new prospecting campaign?\n      yes: Spend rises while paid revenue grows less; returns usually fall as budgets scale.\n    spiked:\n      check: Did spend fall, cutting the least efficient campaigns first?\n      yes: Spend falls more than paid revenue does.\n  - id: click-cost\n    label: Cost per click\n    metric: cpc\n    dropped:\n      check: Did each click get more expensive?\n      yes: CPC rises by about as much as ROAS falls, while paid conversion and order value hold.\n    spiked:\n      check: Did clicks get cheaper?\n      yes: CPC falls by about as much as ROAS rises, while paid conversion and order value hold.\n  - id: paid-conversion\n    label: Paid conversion rate\n    metric: paid-conversion-rate\n    dropped:\n      check: Did fewer paid visits order, from a landing page, stock or checkout problem?\n      yes: Paid conversion falls while CPC and order value hold.\n    spiked:\n      check: Did more paid visits order, from a better landing page or offer?\n      yes: Paid conversion rises while CPC and order value hold.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did paid orders get smaller, from a discount or a cheaper hero product?\n      yes: Order value from paid sessions falls while the number of paid orders holds.\n    spiked:\n      check: Did paid orders get bigger, from a bundle, a price rise or a few large orders?\n      yes: Order value from paid sessions rises while the number of paid orders holds.\n\ndiagnose_order: [attribution, calendar, spend, click-cost, paid-conversion, order-value]\n\nrelated: [mer, ad-spend, paid-conversion-rate, cpc, ncac, aov]\n\nprose:\n  why_it_matters: >-\n    ROAS says whether the ads pay for themselves, and splits into three numbers that each point\n    at a different team: ROAS is roughly paid conversion rate × order value ÷ cost per click. A store at\n    1.7 earns $1.70 in session-attributed revenue per ad dollar; whether that is profitable\n    depends on margin, so set a break-even ROAS of 1 ÷ gross margin and read against it.\n  pitfalls:\n    - Platform ROAS is not this number. Meta and Google count view-through and modeled conversions and each claim the same order, so the platforms' sum often runs 1.5 to 2 times what the store can match to an ad visit.\n    - Session-attributed ROAS undercounts ads that work slowly. A shopper who clicks an ad, leaves, and buys from a bookmark two days later counts as direct here; read MER alongside it.\n    - High ROAS can mean too little spend. Retargeting and branded search show the best returns because they reach people who would have bought anyway.\n    - Orders must carry the browser's session id for this query to match them to a visit. Server-side orders without it count as unpaid.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"roas","name":"Return on ad spend","aliases":["Ad ROAS","Paid ROAS","Return on advertising spend"],"family":"acquisition","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"Revenue from orders placed in visits that arrived through a paid ad, for each dollar of ad spend in the same week.","formula":"Order revenue from paid-ad sessions ÷ ad spend"},"events":[{"name":"$pageview","description":"One page load or client-side route change; the session's first page view decides whether it came from an ad.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"utm_medium","description":"The campaign medium from the landing URL. Paid when it contains \"cp\", starts with \"paid\", or is ppc, retargeting, display or banner."},{"name":"gclid","description":"Google Ads click id from auto-tagging. Also gbraid, wbraid, and msclkid for Microsoft Ads."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the session id of the visit it was placed in.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"$session_id","description":"The visit the order was placed in, passed from the browser to the server event."}]},{"name":"ad_spend","description":"One row per channel per day, synced from each ad platform's reporting API.","also_called":["Ad Spend","ad_performance","campaign_daily_stats"],"properties":[{"name":"spend","description":"Amount spent that day, in the store's reporting currency."}]}],"numerator":{"label":"Revenue from paid-ad sessions","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Ad spend","aggregate":"sum","event":"ad_spend","property":"spend"},"queries":{"hogql":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\nSELECT\n  a.week AS week,\n  coalesce(r.revenue, 0) AS numerator,\n  a.spend AS denominator,\n  if(a.spend > 0, coalesce(r.revenue, 0) / a.spend, NULL) AS value\nFROM (\n  SELECT toMonday(timestamp) AS week, sum(toFloat(properties.spend)) AS spend\n  FROM events\n  WHERE event = 'ad_spend'\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY week\n) AS a\nLEFT JOIN (\n  SELECT week, sum(revenue) AS revenue\n  FROM (\n    SELECT\n      $session_id AS session_id,\n      toMonday(minIf(timestamp, event = 'order_completed')) AS week,\n      argMinIf(lower(coalesce(properties.utm_medium, '')), timestamp, event = '$pageview') AS medium,\n      argMinIf(coalesce(properties.gclid, properties.gbraid, properties.wbraid, properties.msclkid, '') != '', timestamp, event = '$pageview') AS ad_click,\n      sumIf(toFloat(properties.total), event = 'order_completed') AS revenue\n    FROM events\n    WHERE event IN ('$pageview', 'order_completed')\n      AND $session_id IS NOT NULL\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY session_id\n    HAVING countIf(event = 'order_completed') > 0 AND countIf(event = '$pageview') > 0\n  )\n  WHERE (match(medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR ad_click)\n  GROUP BY week\n) AS r ON r.week = a.week\nORDER BY week","postgres":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\nWITH spend AS (\n  SELECT date_trunc('week', occurred_at)::date AS week, sum((properties->>'spend')::numeric) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY 1\n),\nentries AS (\n  SELECT DISTINCT ON (session_id)\n    session_id,\n    date_trunc('week', occurred_at)::date AS week,\n    lower(coalesce(properties->>'utm_medium', '')) AS medium,\n    coalesce(properties->>'gclid', properties->>'gbraid', properties->>'wbraid', properties->>'msclkid', '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  ORDER BY session_id, occurred_at\n),\npaid_revenue AS (\n  SELECT date_trunc('week', o.occurred_at)::date AS week, sum((o.properties->>'total')::numeric) AS revenue\n  FROM events AS o\n  JOIN entries AS e ON e.session_id = o.session_id\n  WHERE o.event_name = 'order_completed'\n    AND o.occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND o.occurred_at < date_trunc('week', now())\n    AND (e.medium ~ '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$' OR e.ad_click)\n  GROUP BY 1\n)\nSELECT\n  s.week,\n  coalesce(p.revenue, 0) AS numerator,\n  s.spend AS denominator,\n  coalesce(p.revenue, 0) / nullif(s.spend, 0) AS value\nFROM spend AS s\nLEFT JOIN paid_revenue AS p ON p.week = s.week\nORDER BY s.week;","bigquery":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\nWITH spend AS (\n  SELECT DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week, sum(CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64)) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY 1\n),\nentries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    lower(coalesce(JSON_VALUE(properties, '$.utm_medium'), '')) AS medium,\n    coalesce(JSON_VALUE(properties, '$.gclid'), JSON_VALUE(properties, '$.gbraid'), JSON_VALUE(properties, '$.wbraid'), JSON_VALUE(properties, '$.msclkid'), '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\npaid_revenue AS (\n  SELECT DATE_TRUNC(DATE(o.occurred_at), ISOWEEK) AS week, sum(CAST(JSON_VALUE(o.properties, '$.total') AS FLOAT64)) AS revenue\n  FROM events AS o\n  JOIN entries AS e ON e.session_id = o.session_id\n  WHERE o.event_name = 'order_completed'\n    AND o.occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND o.occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    AND (REGEXP_CONTAINS(e.medium, r'^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY 1\n)\nSELECT\n  s.week,\n  coalesce(p.revenue, 0) AS numerator,\n  s.spend AS denominator,\n  SAFE_DIVIDE(COALESCE(p.revenue, 0), s.spend) AS value\nFROM spend AS s\nLEFT JOIN paid_revenue AS p ON p.week = s.week\nORDER BY s.week;","snowflake":"-- ROAS per week: revenue from orders placed in sessions that arrived through a paid ad ÷ ad spend, both by the week they happened.\n-- Assumes WEEK_START = 1 (Monday).\nWITH spend AS (\n  SELECT DATE_TRUNC('week', occurred_at)::date AS week, sum(properties:\"spend\"::float) AS spend\n  FROM events\n  WHERE event_name = 'ad_spend'\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY 1\n),\nentries AS (\n  SELECT\n    session_id,\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    lower(coalesce(properties:\"utm_medium\"::string, '')) AS medium,\n    coalesce(properties:\"gclid\"::string, properties:\"gbraid\"::string, properties:\"wbraid\"::string, properties:\"msclkid\"::string, '') <> '' AS ad_click\n  FROM events\n  WHERE event_name = '$pageview'\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY occurred_at) = 1\n),\npaid_revenue AS (\n  SELECT DATE_TRUNC('week', o.occurred_at)::date AS week, sum(o.properties:\"total\"::float) AS revenue\n  FROM events AS o\n  JOIN entries AS e ON e.session_id = o.session_id\n  WHERE o.event_name = 'order_completed'\n    AND o.occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND o.occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n    AND (REGEXP_LIKE(e.medium, '^(.*cp.*|ppc|retargeting|paid.*|display|banner|interstitial|expandable)$') OR e.ad_click)\n  GROUP BY 1\n)\nSELECT\n  s.week,\n  coalesce(p.revenue, 0) AS numerator,\n  s.spend AS denominator,\n  DIV0NULL(COALESCE(p.revenue, 0), s.spend) AS value\nFROM spend AS s\nLEFT JOIN paid_revenue AS p ON p.week = s.week\nORDER BY s.week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders from paid sessions a week","typical":2},"example":{"business":"store","level":1.7,"volume":3800,"trend":-0.05},"drivers":[{"id":"attribution","label":"Tracking and attribution","dropped":{"check":"Did orders stop carrying the session id, or did a redirect strip campaign tags, so paid orders look unpaid?","yes":"Total orders hold while orders matched to paid sessions fall, from the day of a checkout or redirect change."},"spiked":{"check":"Did untagged traffic start counting as paid, or are orders recorded twice?","yes":"Paid revenue rises with no rise in paid sessions, or order count exceeds the store admin's."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Did a sale end while budgets stayed high?","yes":"The same weeks last year show the same fall in return after the event."},"spiked":{"check":"Is a sale or holiday turning the same clicks into more orders?","yes":"Paid conversion jumps for the event week and the same week last year shows it too."}},{"id":"spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did spend rise faster than results, from a budget increase or a new prospecting campaign?","yes":"Spend rises while paid revenue grows less; returns usually fall as budgets scale."},"spiked":{"check":"Did spend fall, cutting the least efficient campaigns first?","yes":"Spend falls more than paid revenue does."}},{"id":"click-cost","label":"Cost per click","metric":"cpc","dropped":{"check":"Did each click get more expensive?","yes":"CPC rises by about as much as ROAS falls, while paid conversion and order value hold."},"spiked":{"check":"Did clicks get cheaper?","yes":"CPC falls by about as much as ROAS rises, while paid conversion and order value hold."}},{"id":"paid-conversion","label":"Paid conversion rate","metric":"paid-conversion-rate","dropped":{"check":"Did fewer paid visits order, from a landing page, stock or checkout problem?","yes":"Paid conversion falls while CPC and order value hold."},"spiked":{"check":"Did more paid visits order, from a better landing page or offer?","yes":"Paid conversion rises while CPC and order value hold."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did paid orders get smaller, from a discount or a cheaper hero product?","yes":"Order value from paid sessions falls while the number of paid orders holds."},"spiked":{"check":"Did paid orders get bigger, from a bundle, a price rise or a few large orders?","yes":"Order value from paid sessions rises while the number of paid orders holds."}}],"diagnose_order":["attribution","calendar","spend","click-cost","paid-conversion","order-value"],"related":["mer","ad-spend","paid-conversion-rate","cpc","ncac","aov"],"prose":{"why_it_matters":"ROAS says whether the ads pay for themselves, and splits into three numbers that each point at a different team: ROAS is roughly paid conversion rate × order value ÷ cost per click. A store at 1.7 earns $1.70 in session-attributed revenue per ad dollar; whether that is profitable depends on margin, so set a break-even ROAS of 1 ÷ gross margin and read against it.","pitfalls":["Platform ROAS is not this number. Meta and Google count view-through and modeled conversions and each claim the same order, so the platforms' sum often runs 1.5 to 2 times what the store can match to an ad visit.","Session-attributed ROAS undercounts ads that work slowly. A shopper who clicks an ad, leaves, and buys from a bookmark two days later counts as direct here; read MER alongside it.","High ROAS can mean too little spend. Retargeting and branded search show the best returns because they reach people who would have bought anyway.","Orders must carry the browser's session id for this query to match them to a visit. Server-side orders without it count as unpaid."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "search-conversion-rate": { yaml: "id: search-conversion-rate\nname: Search conversion rate\naliases:\n  - Site search conversion rate\n  - Search to purchase rate\n  - Search conversion\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that used site search and then placed a paid order in the same session.\n  formula: Sessions that searched, then ordered ÷ sessions that searched\n\nevents:\n  - name: product_searched\n    description: A search submitted in the store's search box, or its results page shown, once per search.\n    also_called: [search, view_search_results, Products Searched, search_submitted]\n    properties:\n      - name: query\n        description: What the shopper typed, as submitted.\n      - name: results_count\n        description: How many products the search returned; 0 is a dead end.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Sessions that searched, then ordered\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that searched\n  aggregate: unique_sessions\n  event: product_searched\n\nqueries:\n  hogql: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    SELECT\n      toMonday(searched_at) AS week,\n      countIf(ordered_at >= searched_at) AS numerator,\n      count() AS denominator,\n      if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM (\n      SELECT\n        $session_id AS session_id,\n        minIf(timestamp, event = 'product_searched') AS searched_at,\n        maxIf(timestamp, event = 'order_completed') AS ordered_at\n      FROM events\n      WHERE event IN ('product_searched', 'order_completed')\n        AND $session_id != ''\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY session_id\n      HAVING countIf(event = 'product_searched') > 0\n    )\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    -- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH searches AS (\n      SELECT\n        session_id,\n        min(occurred_at) FILTER (WHERE event_name = 'product_searched') AS searched_at,\n        max(occurred_at) FILTER (WHERE event_name = 'order_completed') AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY session_id\n    )\n    SELECT\n      date_trunc('week', searched_at)::date AS week,\n      count(*) FILTER (WHERE ordered_at >= searched_at) AS numerator,\n      count(*) AS denominator,\n      (count(*) FILTER (WHERE ordered_at >= searched_at))::numeric / nullif(count(*), 0) AS value\n    FROM searches\n    WHERE searched_at IS NOT NULL\n    GROUP BY 1\n    ORDER BY 1;\n  bigquery: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    -- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH searches AS (\n      SELECT\n        session_id,\n        MIN(IF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n        MAX(IF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY session_id\n    )\n    SELECT\n      DATE_TRUNC(DATE(searched_at), ISOWEEK) AS week,\n      COUNTIF(ordered_at >= searched_at) AS numerator,\n      COUNT(*) AS denominator,\n      SAFE_DIVIDE(COUNTIF(ordered_at >= searched_at), COUNT(*)) AS value\n    FROM searches\n    WHERE searched_at IS NOT NULL\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    -- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\n    WITH searches AS (\n      SELECT\n        session_id,\n        MIN(IFF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n        MAX(IFF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY session_id\n    )\n    SELECT\n      DATE_TRUNC('week', searched_at)::date AS week,\n      COUNT_IF(ordered_at >= searched_at) AS numerator,\n      COUNT(*) AS denominator,\n      DIV0NULL(COUNT_IF(ordered_at >= searched_at), COUNT(*)) AS value\n    FROM searches\n    WHERE searched_at IS NOT NULL\n    GROUP BY 1\n    ORDER BY 1;\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions with a search a week\n  typical: 0.05\n  reference_volumes: [500, 2000, 10000, 50000]\n\nexample:\n  business: store\n  level: 0.052\n  volume: 66000\n  trend: 0.03\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a search app or theme change start firing product_searched on autocomplete keystrokes?\n      yes: Sessions with a search jump on the release day, many with a one- or two-letter query and nothing after it.\n    spiked:\n      check: Did product_searched stop firing on some pages or devices, leaving only the most determined searchers?\n      yes: Sessions with a search fall on one device or template while search orders hold.\n  - id: store-wide\n    label: The whole store\n    metric: conversion-rate\n    dropped:\n      check: Did conversion fall for everyone, not only for searchers?\n      yes: Search conversion and store conversion fall together, so the cause is checkout, price or the calendar, not search.\n    spiked:\n      check: Did conversion rise for everyone, from a sale or a fix elsewhere?\n      yes: Search conversion and store conversion rise together, so search itself didn't change.\n  - id: zero-results\n    label: Searches with no results\n    dropped:\n      check: Did more searches return nothing, from a catalogue change, lost synonyms or a trending term you don't stock?\n      yes: The share of searches with results_count of 0 rises, concentrated in a few queries.\n    spiked:\n      check: Did a synonym, spelling or catalogue fix cut dead-end searches?\n      yes: Zero-result searches fall from the day of the fix, on the queries it covered.\n  - id: stock\n    label: Stock of searched products\n    dropped:\n      check: Are the products people search for most out of stock or missing common sizes?\n      yes: Top queries still return results, but their first results are sold out.\n    spiked:\n      check: Did a much-searched product come back in stock or launch?\n      yes: Orders after searching for that product's name jump from the restock or launch day.\n  - id: relevance\n    label: Ranking and relevance\n    dropped:\n      check: Did a search app update, re-index or merchandising rule push irrelevant or sold-out products to the top?\n      yes: Clicks on the first results fall for the top queries from the day of the change.\n    spiked:\n      check: Did a relevance change or test ship, and is it on for everyone?\n      yes: The rise starts on the release day across devices and queries.\n  - id: who-searches\n    label: Who searches\n    breakdown: $device_type\n    dropped:\n      check: Did the search box become more prominent, so more casual browsers search?\n      yes: Sessions with a search grow faster than orders after searching; search-driven orders still rise.\n    spiked:\n      check: Did the search box move or shrink, leaving fewer but more committed searchers?\n      yes: Sessions with a search fall while orders after searching hold.\n\ndiagnose_order: [tracking, store-wide, zero-results, stock, relevance, who-searches]\n\nrelated: [conversion-rate, product-view-rate, add-to-cart-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Shoppers who search say what they want in their own words, and they convert at roughly\n    twice the store average; at Northwind, 5.2% against 2.2%. A fall here is usually something\n    the team controls, such as a search app update, lost synonyms or empty results for the\n    words people actually type.\n  pitfalls:\n    - Searchers are more committed than average, so a high search conversion doesn't prove search works. Compare search conversion with itself over time, not with the store rate.\n    - Predictive search that fires the event on each keystroke counts sessions that never submitted a search. Fire product_searched on submit or on the results view.\n    - This spec credits search only when the order follows in the same session. A shopper who searches today and buys tomorrow counts as a search that didn't convert.\n    - Zero-result searches are the fastest thing to check. A rise in dead-end searches nearly always comes before a fall in search conversion.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"search-conversion-rate","name":"Search conversion rate","aliases":["Site search conversion rate","Search to purchase rate","Search conversion"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that used site search and then placed a paid order in the same session.","formula":"Sessions that searched, then ordered ÷ sessions that searched"},"events":[{"name":"product_searched","description":"A search submitted in the store's search box, or its results page shown, once per search.","also_called":["search","view_search_results","Products Searched","search_submitted"],"properties":[{"name":"query","description":"What the shopper typed, as submitted."},{"name":"results_count","description":"How many products the search returned; 0 is a dead end."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Sessions that searched, then ordered","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that searched","aggregate":"unique_sessions","event":"product_searched"},"queries":{"hogql":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\nSELECT\n  toMonday(searched_at) AS week,\n  countIf(ordered_at >= searched_at) AS numerator,\n  count() AS denominator,\n  if(denominator > 0, numerator / denominator, NULL) AS value\nFROM (\n  SELECT\n    $session_id AS session_id,\n    minIf(timestamp, event = 'product_searched') AS searched_at,\n    maxIf(timestamp, event = 'order_completed') AS ordered_at\n  FROM events\n  WHERE event IN ('product_searched', 'order_completed')\n    AND $session_id != ''\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY session_id\n  HAVING countIf(event = 'product_searched') > 0\n)\nGROUP BY week\nORDER BY week","postgres":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n-- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH searches AS (\n  SELECT\n    session_id,\n    min(occurred_at) FILTER (WHERE event_name = 'product_searched') AS searched_at,\n    max(occurred_at) FILTER (WHERE event_name = 'order_completed') AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY session_id\n)\nSELECT\n  date_trunc('week', searched_at)::date AS week,\n  count(*) FILTER (WHERE ordered_at >= searched_at) AS numerator,\n  count(*) AS denominator,\n  (count(*) FILTER (WHERE ordered_at >= searched_at))::numeric / nullif(count(*), 0) AS value\nFROM searches\nWHERE searched_at IS NOT NULL\nGROUP BY 1\nORDER BY 1;","bigquery":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n-- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH searches AS (\n  SELECT\n    session_id,\n    MIN(IF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n    MAX(IF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY session_id\n)\nSELECT\n  DATE_TRUNC(DATE(searched_at), ISOWEEK) AS week,\n  COUNTIF(ordered_at >= searched_at) AS numerator,\n  COUNT(*) AS denominator,\n  SAFE_DIVIDE(COUNTIF(ordered_at >= searched_at), COUNT(*)) AS value\nFROM searches\nWHERE searched_at IS NOT NULL\nGROUP BY week\nORDER BY week;","snowflake":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n-- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\nWITH searches AS (\n  SELECT\n    session_id,\n    MIN(IFF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n    MAX(IFF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY session_id\n)\nSELECT\n  DATE_TRUNC('week', searched_at)::date AS week,\n  COUNT_IF(ordered_at >= searched_at) AS numerator,\n  COUNT(*) AS denominator,\n  DIV0NULL(COUNT_IF(ordered_at >= searched_at), COUNT(*)) AS value\nFROM searches\nWHERE searched_at IS NOT NULL\nGROUP BY 1\nORDER BY 1;"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions with a search a week","typical":0.05,"reference_volumes":[500,2000,10000,50000]},"example":{"business":"store","level":0.052,"volume":66000,"trend":0.03},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a search app or theme change start firing product_searched on autocomplete keystrokes?","yes":"Sessions with a search jump on the release day, many with a one- or two-letter query and nothing after it."},"spiked":{"check":"Did product_searched stop firing on some pages or devices, leaving only the most determined searchers?","yes":"Sessions with a search fall on one device or template while search orders hold."}},{"id":"store-wide","label":"The whole store","metric":"conversion-rate","dropped":{"check":"Did conversion fall for everyone, not only for searchers?","yes":"Search conversion and store conversion fall together, so the cause is checkout, price or the calendar, not search."},"spiked":{"check":"Did conversion rise for everyone, from a sale or a fix elsewhere?","yes":"Search conversion and store conversion rise together, so search itself didn't change."}},{"id":"zero-results","label":"Searches with no results","dropped":{"check":"Did more searches return nothing, from a catalogue change, lost synonyms or a trending term you don't stock?","yes":"The share of searches with results_count of 0 rises, concentrated in a few queries."},"spiked":{"check":"Did a synonym, spelling or catalogue fix cut dead-end searches?","yes":"Zero-result searches fall from the day of the fix, on the queries it covered."}},{"id":"stock","label":"Stock of searched products","dropped":{"check":"Are the products people search for most out of stock or missing common sizes?","yes":"Top queries still return results, but their first results are sold out."},"spiked":{"check":"Did a much-searched product come back in stock or launch?","yes":"Orders after searching for that product's name jump from the restock or launch day."}},{"id":"relevance","label":"Ranking and relevance","dropped":{"check":"Did a search app update, re-index or merchandising rule push irrelevant or sold-out products to the top?","yes":"Clicks on the first results fall for the top queries from the day of the change."},"spiked":{"check":"Did a relevance change or test ship, and is it on for everyone?","yes":"The rise starts on the release day across devices and queries."}},{"id":"who-searches","label":"Who searches","breakdown":"$device_type","dropped":{"check":"Did the search box become more prominent, so more casual browsers search?","yes":"Sessions with a search grow faster than orders after searching; search-driven orders still rise."},"spiked":{"check":"Did the search box move or shrink, leaving fewer but more committed searchers?","yes":"Sessions with a search fall while orders after searching hold."}}],"diagnose_order":["tracking","store-wide","zero-results","stock","relevance","who-searches"],"related":["conversion-rate","product-view-rate","add-to-cart-rate","revenue-per-session"],"prose":{"why_it_matters":"Shoppers who search say what they want in their own words, and they convert at roughly twice the store average; at Northwind, 5.2% against 2.2%. A fall here is usually something the team controls, such as a search app update, lost synonyms or empty results for the words people actually type.","pitfalls":["Searchers are more committed than average, so a high search conversion doesn't prove search works. Compare search conversion with itself over time, not with the store rate.","Predictive search that fires the event on each keystroke counts sessions that never submitted a search. Fire product_searched on submit or on the results view.","This spec credits search only when the order follows in the same session. A shopper who searches today and buys tomorrow counts as a search that didn't convert.","Zero-result searches are the fastest thing to check. A rise in dead-end searches nearly always comes before a fall in search conversion."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "sessions": { yaml: "id: sessions\nname: Sessions\naliases:\n  - Visits\n  - Website sessions\n  - Site visits\nfamily: traffic\ncatalog_id: sessions\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: Visits to the site in the week, where a visit ends after 30 minutes without activity.\n  formula: Distinct session ids with at least one page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; a new id after 30 minutes idle or at most 24 hours.\n      - name: $referring_domain\n        description: The domain the visitor came from, or $direct when there was none.\n      - name: utm_medium\n        description: The campaign medium from the landing URL (cpc, email, social).\n\nnumerator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: sessions a week\n  typical: 40000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 520000\n  volume: 520000\n  trend: 0.15\n\ndrivers:\n  - id: tracking\n    label: Tracking and bots\n    breakdown: $browser\n    dropped:\n      check: Did a consent banner, tag manager or SDK change stop page views being recorded?\n      yes: Orders in the store admin hold while recorded sessions fall, starting on the day of the change and often in one browser.\n    spiked:\n      check: Is a bot, crawler or a page view firing twice inflating the count?\n      yes: The extra sessions come from one browser, country or data-centre network, bounce almost every time and never order.\n  - id: site-availability\n    label: Site and CDN availability\n    feed: cloudflare\n    dropped:\n      check: Was the site, its CDN or its DNS down or slow for part of the week?\n      yes: Sessions dip in the hours of a known incident and recover after it.\n    spiked:\n      check: Was last week depressed by an outage, so this week only looks high?\n      yes: Last week has a gap in the hourly chart; this week is back to its usual level.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week that this week can't match?\n      yes: The same pair of weeks last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is this week a sale, holiday or gifting week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: paid\n    label: Paid traffic\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did ad spend fall, a campaign pause or a billing problem stop ads serving?\n      yes: Paid sessions fall by about as many sessions as the total does, while other channels hold.\n    spiked:\n      check: Did a campaign launch or a budget rise bring more ad clicks?\n      yes: Paid sessions rise by about the size of the jump; check that conversion held before celebrating.\n  - id: organic\n    label: Organic search\n    metric: organic-sessions\n    feed: google-search\n    dropped:\n      check: Did search traffic fall after a Google update or lost rankings on key pages?\n      yes: Organic sessions fall from the date of the update, concentrated on a few landing pages.\n    spiked:\n      check: Did a ranking gain, a seasonal search or a brand moment lift search traffic?\n      yes: Organic sessions rise on a handful of landing pages or on branded searches.\n  - id: referral\n    label: Referrals and press\n    metric: referral-sessions\n    dropped:\n      check: Did a partner link, affiliate or a source of steady referrals go away?\n      yes: One referring domain that used to send traffic has stopped.\n    spiked:\n      check: Did a press mention, a newsletter or a viral post link to the site?\n      yes: One referring domain explains most of the rise and fades within days.\n\ndiagnose_order: [tracking, site-availability, calendar, paid, organic, referral]\n\nrelated: [unique-visitors, organic-sessions, paid-sessions, bounce-rate, conversion-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Sessions are the top of every store funnel: orders are sessions times conversion, so a\n    traffic move shows up in revenue a few days later at the same size. They are also the\n    number most easily inflated by bots and broken tags. A 520,000-session week that grows 4%\n    from a crawler adds 20,000 sessions and no orders, and drags every rate below it down.\n  pitfalls:\n    - Sessions are not visitors. One person can have several sessions a week, so a change in how often people come back moves sessions while unique visitors hold.\n    - Tools count sessions differently. Universal Analytics also split a visit at midnight and on every campaign change, GA4 estimates its session count, and server logs include bots browser tools never see, so compare a tool only with itself.\n    - Ad blockers and consent banners hide 10 to 30% of visits from browser tracking, and the share changes when the banner or a browser changes, not when traffic does.\n    - Bot traffic rarely looks like bots in the total. Split by country, browser and landing page before trusting a jump.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"sessions","name":"Sessions","aliases":["Visits","Website sessions","Site visits"],"family":"traffic","catalog_id":"sessions","kind":"count","polarity":"up-is-good","definition":{"one_line":"Visits to the site in the week, where a visit ends after 30 minutes without activity.","formula":"Distinct session ids with at least one page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; a new id after 30 minutes idle or at most 24 hours."},{"name":"$referring_domain","description":"The domain the visitor came from, or $direct when there was none."},{"name":"utm_medium","description":"The campaign medium from the landing URL (cpc, email, social)."}]}],"numerator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"sessions a week","typical":40000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":520000,"volume":520000,"trend":0.15},"drivers":[{"id":"tracking","label":"Tracking and bots","breakdown":"$browser","dropped":{"check":"Did a consent banner, tag manager or SDK change stop page views being recorded?","yes":"Orders in the store admin hold while recorded sessions fall, starting on the day of the change and often in one browser."},"spiked":{"check":"Is a bot, crawler or a page view firing twice inflating the count?","yes":"The extra sessions come from one browser, country or data-centre network, bounce almost every time and never order."}},{"id":"site-availability","label":"Site and CDN availability","feed":"cloudflare","dropped":{"check":"Was the site, its CDN or its DNS down or slow for part of the week?","yes":"Sessions dip in the hours of a known incident and recover after it."},"spiked":{"check":"Was last week depressed by an outage, so this week only looks high?","yes":"Last week has a gap in the hourly chart; this week is back to its usual level."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week that this week can't match?","yes":"The same pair of weeks last year shows the same fall once aligned on the event."},"spiked":{"check":"Is this week a sale, holiday or gifting week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"paid","label":"Paid traffic","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did ad spend fall, a campaign pause or a billing problem stop ads serving?","yes":"Paid sessions fall by about as many sessions as the total does, while other channels hold."},"spiked":{"check":"Did a campaign launch or a budget rise bring more ad clicks?","yes":"Paid sessions rise by about the size of the jump; check that conversion held before celebrating."}},{"id":"organic","label":"Organic search","metric":"organic-sessions","feed":"google-search","dropped":{"check":"Did search traffic fall after a Google update or lost rankings on key pages?","yes":"Organic sessions fall from the date of the update, concentrated on a few landing pages."},"spiked":{"check":"Did a ranking gain, a seasonal search or a brand moment lift search traffic?","yes":"Organic sessions rise on a handful of landing pages or on branded searches."}},{"id":"referral","label":"Referrals and press","metric":"referral-sessions","dropped":{"check":"Did a partner link, affiliate or a source of steady referrals go away?","yes":"One referring domain that used to send traffic has stopped."},"spiked":{"check":"Did a press mention, a newsletter or a viral post link to the site?","yes":"One referring domain explains most of the rise and fades within days."}}],"diagnose_order":["tracking","site-availability","calendar","paid","organic","referral"],"related":["unique-visitors","organic-sessions","paid-sessions","bounce-rate","conversion-rate","revenue-per-session"],"prose":{"why_it_matters":"Sessions are the top of every store funnel: orders are sessions times conversion, so a traffic move shows up in revenue a few days later at the same size. They are also the number most easily inflated by bots and broken tags. A 520,000-session week that grows 4% from a crawler adds 20,000 sessions and no orders, and drags every rate below it down.","pitfalls":["Sessions are not visitors. One person can have several sessions a week, so a change in how often people come back moves sessions while unique visitors hold.","Tools count sessions differently. Universal Analytics also split a visit at midnight and on every campaign change, GA4 estimates its session count, and server logs include bots browser tools never see, so compare a tool only with itself.","Ad blockers and consent banners hide 10 to 30% of visits from browser tracking, and the share changes when the banner or a browser changes, not when traffic does.","Bot traffic rarely looks like bots in the total. Split by country, browser and landing page before trusting a jump."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "unique-visitors": { yaml: "id: unique-visitors\nname: Unique visitors\naliases:\n  - Visitors\n  - Website visitors\n  - Weekly unique visitors\nfamily: traffic\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of different people, counted by browser or login, who viewed at least one page in the week.\n  formula: Distinct visitor ids with at least one page view\n\nevents:\n  - name: $pageview\n    description: One page load or client-side route change, captured in the browser.\n    also_called: [page_view, Page Viewed, page]\n    properties:\n      - name: $session_id\n        description: Set by the analytics SDK; ties the page view to a visit.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet.\n\nnumerator:\n  label: Unique visitors\n  aggregate: unique_users\n  event: $pageview\n\nnoise:\n  type: poisson\n  min_denominator: 100\n  volume_unit: visitors a week\n  typical: 30000\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 390000\n  volume: 390000\n  trend: 0.12\n\ndrivers:\n  - id: identity\n    label: Cookies and identity\n    breakdown: $browser\n    dropped:\n      check: Did a consent banner, a cookie change or a merge of anonymous and logged-in people cut the count?\n      yes: Visitors fall while sessions hold, from the day of the change, often in one browser.\n    spiked:\n      check: Did cookies start resetting, so the same people now count as new visitors?\n      yes: Visitors and new-visitor share jump together while sessions per visitor fall, often on Safari or after a domain change.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or gifting week that this week can't match?\n      yes: The same pair of weeks last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or gifting week that brings people who don't usually visit?\n      yes: The same week last year shows the same jump, mostly in new visitors.\n  - id: new-visitors\n    label: New visitors\n    metric: new-visitor-share\n    dropped:\n      check: Did fewer first-time visitors arrive while returning visitors held?\n      yes: New-visitor share falls and the drop sits in prospecting channels.\n    spiked:\n      check: Is the rise all first-time visitors from one source?\n      yes: New-visitor share jumps with one campaign, post or press mention.\n  - id: paid\n    label: Paid traffic\n    metric: paid-sessions\n    feed: ad-platforms\n    dropped:\n      check: Did prospecting spend fall or a campaign stop serving?\n      yes: Paid sessions fall by about the same number of people.\n    spiked:\n      check: Did a prospecting campaign or a budget increase start?\n      yes: Paid sessions rise and the new people come from one platform.\n  - id: organic\n    label: Organic search\n    metric: organic-sessions\n    feed: google-search\n    dropped:\n      check: Did search traffic fall after a Google update or lost rankings?\n      yes: Organic sessions fall from the date of the update.\n    spiked:\n      check: Did a ranking gain or a seasonal search term bring new people?\n      yes: Organic sessions rise on a few landing pages.\n\ndiagnose_order: [identity, calendar, new-visitors, paid, organic]\n\nrelated: [sessions, new-visitor-share, sessions-per-user, wau, organic-sessions]\n\nprose:\n  why_it_matters: >-\n    Unique visitors tell you how many people the store reached, which sessions can't: a loyal\n    visitor coming back five times is five sessions and one person. When sessions grow and\n    visitors don't, the same people are visiting more; when visitors grow, reach is growing.\n    A store with 390,000 visitors a week can lose 3% of them to a cookie change without a\n    single real person leaving.\n  pitfalls:\n    - A visitor is a browser, not a person. Phone and laptop count twice, and Safari's seven-day limit on script-set cookies makes a weekly returner look new.\n    - Weekly unique visitors don't add up to monthly unique visitors. Never sum weeks; count distinct people over the longer window.\n    - In a warehouse, count the anonymous id for visitors who never log in. Counting only user_id drops most of a store's traffic.\n    - Merging anonymous and identified people, as PostHog does on login, can lower past weeks' counts after the fact. Freeze last week's number when you report it.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"unique-visitors","name":"Unique visitors","aliases":["Visitors","Website visitors","Weekly unique visitors"],"family":"traffic","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of different people, counted by browser or login, who viewed at least one page in the week.","formula":"Distinct visitor ids with at least one page view"},"events":[{"name":"$pageview","description":"One page load or client-side route change, captured in the browser.","also_called":["page_view","Page Viewed","page"],"properties":[{"name":"$session_id","description":"Set by the analytics SDK; ties the page view to a visit."},{"name":"$device_type","description":"Mobile, Desktop or Tablet."}]}],"numerator":{"label":"Unique visitors","aggregate":"unique_users","event":"$pageview"},"noise":{"type":"poisson","min_denominator":100,"volume_unit":"visitors a week","typical":30000,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":390000,"volume":390000,"trend":0.12},"drivers":[{"id":"identity","label":"Cookies and identity","breakdown":"$browser","dropped":{"check":"Did a consent banner, a cookie change or a merge of anonymous and logged-in people cut the count?","yes":"Visitors fall while sessions hold, from the day of the change, often in one browser."},"spiked":{"check":"Did cookies start resetting, so the same people now count as new visitors?","yes":"Visitors and new-visitor share jump together while sessions per visitor fall, often on Safari or after a domain change."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or gifting week that this week can't match?","yes":"The same pair of weeks last year shows the same fall once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or gifting week that brings people who don't usually visit?","yes":"The same week last year shows the same jump, mostly in new visitors."}},{"id":"new-visitors","label":"New visitors","metric":"new-visitor-share","dropped":{"check":"Did fewer first-time visitors arrive while returning visitors held?","yes":"New-visitor share falls and the drop sits in prospecting channels."},"spiked":{"check":"Is the rise all first-time visitors from one source?","yes":"New-visitor share jumps with one campaign, post or press mention."}},{"id":"paid","label":"Paid traffic","metric":"paid-sessions","feed":"ad-platforms","dropped":{"check":"Did prospecting spend fall or a campaign stop serving?","yes":"Paid sessions fall by about the same number of people."},"spiked":{"check":"Did a prospecting campaign or a budget increase start?","yes":"Paid sessions rise and the new people come from one platform."}},{"id":"organic","label":"Organic search","metric":"organic-sessions","feed":"google-search","dropped":{"check":"Did search traffic fall after a Google update or lost rankings?","yes":"Organic sessions fall from the date of the update."},"spiked":{"check":"Did a ranking gain or a seasonal search term bring new people?","yes":"Organic sessions rise on a few landing pages."}}],"diagnose_order":["identity","calendar","new-visitors","paid","organic"],"related":["sessions","new-visitor-share","sessions-per-user","wau","organic-sessions"],"prose":{"why_it_matters":"Unique visitors tell you how many people the store reached, which sessions can't: a loyal visitor coming back five times is five sessions and one person. When sessions grow and visitors don't, the same people are visiting more; when visitors grow, reach is growing. A store with 390,000 visitors a week can lose 3% of them to a cookie change without a single real person leaving.","pitfalls":["A visitor is a browser, not a person. Phone and laptop count twice, and Safari's seven-day limit on script-set cookies makes a weekly returner look new.","Weekly unique visitors don't add up to monthly unique visitors. Never sum weeks; count distinct people over the longer window.","In a warehouse, count the anonymous id for visitors who never log in. Counting only user_id drops most of a store's traffic.","Merging anonymous and identified people, as PostHog does on login, can lower past weeks' counts after the fact. Freeze last week's number when you report it."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "units-per-order": { yaml: "id: units-per-order\nname: Units per order\naliases:\n  - Units per transaction\n  - UPT\n  - Items per order\n  - Average basket size\n  - Basket size\nfamily: revenue\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of items in a paid order, the basket half of average order value.\n  formula: Items sold ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: item_count\n        description: Total units in the order, summing each line's quantity.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Items sold\n  aggregate: sum\n  event: order_completed\n  property: item_count\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: mean\n  cv: 0.75\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 1.8\n\nexample:\n  business: store\n  level: 1.86\n  volume: 13300\n  trend: 0.05\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did item_count switch from units to line items, or stop counting bundle components?\n      yes: Units per order step down on one release day while order value holds.\n    spiked:\n      check: Did item_count start counting free gifts, samples or shipping protection as items?\n      yes: Units step up on one day, and orders carry $0 lines they didn't before.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a gifting or stock-up week, when baskets run larger?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a gifting or stock-up week?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: offers\n    label: Bundles and thresholds\n    dropped:\n      check: Did a bundle, a multi-buy offer or a free-shipping threshold end or fall?\n      yes: The share of one-item orders rises from the day the offer changed.\n    spiked:\n      check: Did a buy-two offer, a bundle or a higher free-shipping threshold go live?\n      yes: The share of one-item orders falls from the launch day.\n  - id: cross-sell\n    label: Cart recommendations\n    dropped:\n      check: Did a cart upsell, recommendations widget or frequently-bought-together block break or get removed?\n      yes: Adds from recommendations fall to near zero from one day.\n    spiked:\n      check: Did a new cross-sell launch, and are its adds paid items rather than free gifts?\n      yes: Adds from recommendations rise and the extra items carry a price.\n  - id: product-mix\n    label: Product mix\n    dropped:\n      check: Did a single-item product, such as a high-priced hero or a new launch, take a larger share of orders?\n      yes: Orders for that product grow while other baskets hold their size.\n    spiked:\n      check: Did consumables, refills or small accessories that people buy several of gain share?\n      yes: Orders containing those products grow while other baskets hold their size.\n  - id: first-orders\n    label: First vs repeat orders\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders, which tend to hold fewer items, take a larger share?\n      yes: Each group's average holds and only the mix moved.\n    spiked:\n      check: Did repeat customers, who know what they want, take a larger share?\n      yes: The mix moved toward repeat orders while each group's average held.\n\ndiagnose_order: [tracking, calendar, offers, cross-sell, product-mix, first-orders]\n\nrelated: [aov, gross-sales, orders, discount-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Units per order is the basket half of average order value; AOV is units per order × the\n    average price per unit. Bundles, free-shipping thresholds and cross-sells act on it\n    directly. Going from 1.8 to 1.9 at Northwind is about 1,330 more items a week with no new\n    customers.\n  pitfalls:\n    - Decide whether item_count counts units or line items and keep it; switching changes every multi-quantity order.\n    - Free gifts, samples and shipping protection count as items unless excluded, so a gift-with-purchase lifts units with no extra sales.\n    - A bundle sold as one product counts as one item. Splitting a bundle into its parts in the catalogue changes units per order without changing what shoppers bought.\n    - An average hides the shape. A move from 1.8 to 1.9 usually means fewer one-item orders, not bigger baskets everywhere; check the share of one-item orders.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"units-per-order","name":"Units per order","aliases":["Units per transaction","UPT","Items per order","Average basket size","Basket size"],"family":"revenue","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The average number of items in a paid order, the basket half of average order value.","formula":"Items sold ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"item_count","description":"Total units in the order, summing each line's quantity."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Items sold","aggregate":"sum","event":"order_completed","property":"item_count"},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"mean","cv":0.75,"min_denominator":50,"volume_unit":"orders a week","typical":1.8},"example":{"business":"store","level":1.86,"volume":13300,"trend":0.05},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did item_count switch from units to line items, or stop counting bundle components?","yes":"Units per order step down on one release day while order value holds."},"spiked":{"check":"Did item_count start counting free gifts, samples or shipping protection as items?","yes":"Units step up on one day, and orders carry $0 lines they didn't before."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a gifting or stock-up week, when baskets run larger?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a gifting or stock-up week?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"offers","label":"Bundles and thresholds","dropped":{"check":"Did a bundle, a multi-buy offer or a free-shipping threshold end or fall?","yes":"The share of one-item orders rises from the day the offer changed."},"spiked":{"check":"Did a buy-two offer, a bundle or a higher free-shipping threshold go live?","yes":"The share of one-item orders falls from the launch day."}},{"id":"cross-sell","label":"Cart recommendations","dropped":{"check":"Did a cart upsell, recommendations widget or frequently-bought-together block break or get removed?","yes":"Adds from recommendations fall to near zero from one day."},"spiked":{"check":"Did a new cross-sell launch, and are its adds paid items rather than free gifts?","yes":"Adds from recommendations rise and the extra items carry a price."}},{"id":"product-mix","label":"Product mix","dropped":{"check":"Did a single-item product, such as a high-priced hero or a new launch, take a larger share of orders?","yes":"Orders for that product grow while other baskets hold their size."},"spiked":{"check":"Did consumables, refills or small accessories that people buy several of gain share?","yes":"Orders containing those products grow while other baskets hold their size."}},{"id":"first-orders","label":"First vs repeat orders","breakdown":"is_first_order","dropped":{"check":"Did first orders, which tend to hold fewer items, take a larger share?","yes":"Each group's average holds and only the mix moved."},"spiked":{"check":"Did repeat customers, who know what they want, take a larger share?","yes":"The mix moved toward repeat orders while each group's average held."}}],"diagnose_order":["tracking","calendar","offers","cross-sell","product-mix","first-orders"],"related":["aov","gross-sales","orders","discount-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Units per order is the basket half of average order value; AOV is units per order × the average price per unit. Bundles, free-shipping thresholds and cross-sells act on it directly. Going from 1.8 to 1.9 at Northwind is about 1,330 more items a week with no new customers.","pitfalls":["Decide whether item_count counts units or line items and keep it; switching changes every multi-quantity order.","Free gifts, samples and shipping protection count as items unless excluded, so a gift-with-purchase lifts units with no extra sales.","A bundle sold as one product counts as one item. Splitting a bundle into its parts in the catalogue changes units per order without changing what shoppers bought.","An average hides the shape. A move from 1.8 to 1.9 usually means fewer one-item orders, not bigger baskets everywhere; check the share of one-item orders."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
}
